  it("round-trips method-call style sort (order arg via receiverOffset correction) through $.vars reference storage (E2E transpile()+run())", () => {
    // matrix.sort는 pine2py _try_method_style_call의 MATRIX_METHODS 화이트리스트 밖이라(LIMITATIONS.md
    // 참조) 오라클 골든을 낼 수 없다 — receiver 배치(0-32-11 -> descending 정렬)가 정확한지를
    // hand-verified로 직접 실행해 확인.
    const source = [
      "var m = matrix.new<float>(3, 1, 0.0)",
      "m.set(0, 0, 3.0)",
      "m.set(1, 0, 1.0)",
      "m.set(2, 0, 2.0)",
      'm.sort(0, "descending")',
      "var float __obs0 = na",
      "__obs0 := matrix.get(m, 0, 0)",
      "var float __obs2 = na",
      "__obs2 := matrix.get(m, 2, 0)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [1], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs0"]).toBe(3.0);
    expect(bars[0]!["var:__obs2"]).toBe(1.0);
  });

  // ── matrix method-call 스타일 체이닝 codegen(C494, wild `kso_F.mult(...).sum(kso_Q)`류) — receiver가
  // CallExpr이어도 methodCallReceivers 소비 경로(genExpr 재귀)는 array/map과 완전히 동일해 codegen
  // 자체는 무변경, resolveMatrixExprKind/isArrayConstructorCall의 analyzer 확장만으로 충분함을 확인. ──

  it("emits method-call style matrix chaining where the receiver is itself a CallExpr identically to nested namespace calls (C494, m.transpose().det())", () => {
    const code = codegenSource("var m = matrix.new<float>(2, 2, 0.0)\nd = m.transpose().det()");
    expect(code).toContain("rt.matrix.det(rt.matrix.transpose($.vars[0]));");
  });

  it("emits matrix.row() method-call sugar chained with an array method identically to the nested namespace form (C494, m.row(0).get(1))", () => {
    const code = codegenSource("var m = matrix.new<float>(2, 2, 0.0)\nx = m.row(0).get(1)");
    expect(code).toContain("rt.array.get(rt.matrix.row($.vars[0], 0), 1);");
  });

  it("round-trips chained matrix method-call sugar (transpose().det()) through $.vars reference storage (E2E transpile()+run())", () => {
    const source = [
      "var m = matrix.new<float>(2, 2, 0.0)",
      "m.set(0, 0, 1.0)",
      "m.set(0, 1, 2.0)",
      "m.set(1, 0, 3.0)",
      "m.set(1, 1, 4.0)",
      "var float __obs0 = na",
      "__obs0 := m.transpose().det()",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [1], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    // det([[1,2],[3,4]]) = det(transpose) = 1*4 - 2*3 = -2 (transpose는 det 부호/값을 안 바꾼다)
    expect(bars[0]!["var:__obs0"]).toBe(-2.0);
  });

  // ── matrix.sum(id1, id2) 2-인자 오버로드(C656, 배치33 (6) argcount 재조사 잔여, DIVERGENCES
  // #201) — analyzer/collections.ts MATRIX_REGISTRY.sum argCount 2로 확장만으로 method-call sugar
  // 경로(methodCallReceivers)는 mult/det 등과 100% 재사용(codegen 변경은 MULTI_CONTAINER_REF_ARGS
  // na-guard 등재 1줄뿐). ──

  it("emits matrix.sum(id1, id2) as rt.matrix.sum with both matrix arguments (literal namespace form)", () => {
    const code = codegenSource(["var m1 = matrix.new<float>(2, 2, 0.0)", "var m2 = matrix.new<float>(2, 2, 0.0)", "p = matrix.sum(m1, m2)"].join("\n"));
    expect(code).toContain("rt.matrix.sum($.vars[0], $.vars[1]);");
  });

  it("emits the full Kalman-idiom method-call sugar chain m1.mult(m2).sum(m2) identically to the nested namespace form (C656)", () => {
    const code = codegenSource(["var m1 = matrix.new<float>(2, 2, 0.0)", "var m2 = matrix.new<float>(2, 2, 0.0)", "p = m1.mult(m2).sum(m2)"].join("\n"));
    expect(code).toContain("rt.matrix.sum(rt.matrix.mult($.vars[0], $.vars[1]), $.vars[1]);");
  });

  it("hand-verified E2E: matrix.sum(id1, id2) elementwise-adds two matrices (transpile()+run(), no pine2py oracle — DIVERGENCES #201)", () => {
    const source = [
      "var m1 = matrix.new<float>(2, 2, 0.0)",
      "m1.set(0, 0, 1.0), m1.set(0, 1, 2.0), m1.set(1, 0, 3.0), m1.set(1, 1, 4.0)",
      "var m2 = matrix.new<float>(2, 2, 0.0)",
      "m2.set(0, 0, 10.0), m2.set(0, 1, 20.0), m2.set(1, 0, 30.0), m2.set(1, 1, 40.0)",
      "var float __obs00 = na",
      "var float __obs11 = na",
      "p = m1.sum(m2)",
      "__obs00 := matrix.get(p, 0, 0)",
      "__obs11 := matrix.get(p, 1, 1)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [1], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs00"]).toBe(11.0);
    expect(bars[0]!["var:__obs11"]).toBe(44.0);
  });

  // ── C658: 위 C656 테스트는 `.sum(...)` 콜 자체의 배선만 확인했을 뿐, 그 결과(p)에 대한 **후속**
  // method-call 체이닝(`p.det()`)은 이전엔 analyzer 단계에서 "지원하지 않는 호출"로 거부돼 codegen까지
  // 도달하지 못했다 — isMatrixReturningMethodSugarCall/isMatrixSumCall이 sum을 matrix-반환으로
  // 인식하도록 확장(analyzer.ts resolveMatrixExprKind CallExpr 분기 + constructors.ts) 후에야
  // 이 codegen 경로가 열린다(실측: corpus/wild/scripts_v56_v2/25ea0355c6c2.pine Kalman 공분산
  // `kso_S = ....sum(kso_R_adj)` 후 `kso_S.inv()`). codegen 자체는 변경 0줄 — methodCallReceivers
  // 범용 재귀가 그대로 처리(C494/C502와 동일 패턴). ──

  it("emits further method-call chaining on a 1-arg matrix.sum(...) sugar result — p.det() after p = m1.sum(m2) (C658)", () => {
    const code = codegenSource(
      ["var m1 = matrix.new<float>(2, 2, 0.0)", "var m2 = matrix.new<float>(2, 2, 0.0)", "p = m1.sum(m2)", "d = p.det()"].join("\n"),
    );
    // p는 '=' 로컬 재참조라 receiver가 CallExpr 자체(C656 직접 체이닝 테스트)가 아니라 그 결과를
    // 담은 변수 `p` -- codegen이 두 문장으로 방출한다(var p = ...; var d = rt.matrix.det(p);).
    expect(code).toContain("var p = rt.matrix.sum($.vars[0], $.vars[1]);");
    expect(code).toContain("var d = rt.matrix.det(p);");
  });

  it("hand-verified E2E: p.det() after p = m1.sum(m2) computes the determinant of the elementwise sum (C658, no pine2py oracle — DIVERGENCES #201)", () => {
    const source = [
      "var m1 = matrix.new<float>(2, 2, 0.0)",
      "m1.set(0, 0, 1.0), m1.set(0, 1, 2.0), m1.set(1, 0, 3.0), m1.set(1, 1, 4.0)",
      "var m2 = matrix.new<float>(2, 2, 0.0)",
      "m2.set(0, 0, 10.0), m2.set(0, 1, 20.0), m2.set(1, 0, 30.0), m2.set(1, 1, 40.0)",
      "var float __obs_det = na",
      "p = m1.sum(m2)",
      "d = p.det()",
      "__obs_det := d",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [1], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    // sum = [[11,22],[33,44]] -> det = 11*44 - 22*33 = 484 - 726 = -242
    expect(bars[0]!["var:__obs_det"]).toBe(-242);
  });

  // ── func-local var matrix 판별 폴백(C646, wild 'fvgMat.add_col' 클러스터) codegen — analyzer
