  it("transpile() end-to-end: map.put/get persist across bars via a var-declared map, put returns the previous value", () => {
    const source = [
      "var m = map.new<string, float>()",
      "var float __obs_prev = na",
      '__obs_prev := map.put(m, "close", close)',
      "var float __obs_get = na",
      '__obs_get := map.get(m, "close")',
      "var float __obs_size = na",
      "__obs_size := map.size(m)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1, 1, 1], high: [1, 1, 1], low: [1, 1, 1], close: [10, 20, 30], volume: [1, 1, 1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    // bar0: 이전 값 없음(최초 put) -> NaN, put 직후 같은 바에서 get -> 방금 넣은 10.
    expect(Number.isNaN(bars[0]!["var:__obs_prev"] as unknown as number)).toBe(true);
    expect(bars[0]!["var:__obs_get"]).toBe(10);
    expect(bars[0]!["var:__obs_size"]).toBe(1);
    // bar1: 같은 키("close")를 계속 덮어써 크기는 그대로 1, put은 직전 바의 값(10)을 반환.
    expect(bars[1]!["var:__obs_prev"]).toBe(10);
    expect(bars[1]!["var:__obs_get"]).toBe(20);
    expect(bars[1]!["var:__obs_size"]).toBe(1);
    // bar2: 직전 바(20)가 반환되고, get은 이번 바에 새로 넣은 30.
    expect(bars[2]!["var:__obs_prev"]).toBe(20);
    expect(bars[2]!["var:__obs_get"]).toBe(30);
  });

