  it("transpile() end-to-end: matrix.fill/reverse/sort/copy/concat/submatrix/reshape/diff produce pine2py-equivalent results across the 8 new methods", () => {
    const source = [
      "var m = matrix.new<float>(2, 3, 0.0)",
      "matrix.set(m, 0, 0, 3.0)",
      "matrix.set(m, 0, 1, 1.0)",
      "matrix.set(m, 0, 2, 2.0)",
      "matrix.set(m, 1, 0, 6.0)",
      "matrix.set(m, 1, 1, 4.0)",
      "matrix.set(m, 1, 2, 5.0)",
      // copy: independence from the original after a later mutation.
      "mcopy = matrix.copy(m)",
      // fill: overwrite a 1x2 sub-block, leaving the rest untouched.
      "matrix.fill(m, 9.0, 0, 1, 0, 2)",
      "var float __obs_fill_hit = na",
      "__obs_fill_hit := matrix.get(m, 0, 0)",
      "var float __obs_fill_untouched = na",
      "__obs_fill_untouched := matrix.get(m, 0, 2)",
      "var float __obs_copy_independent = na",
      "__obs_copy_independent := matrix.get(mcopy, 0, 0)",
      // reverse: row order flips.
      "matrix.reverse(m)",
      "var float __obs_reverse_top = na",
      "__obs_reverse_top := matrix.get(m, 0, 0)",
      // concat rows: 2x3 + 1x3 -> 3x3.
      "mrow = matrix.new<float>(1, 3, 7.0)",
      "mcat = matrix.concat(m, mrow)",
      "var float __obs_concat_rows = na",
      "__obs_concat_rows := matrix.rows(mcat)",
      "var float __obs_concat_last = na",
      "__obs_concat_last := matrix.get(mcat, 2, 0)",
      // submatrix: extract a 1x2 block.
      "msub = matrix.submatrix(mcat, 0, 1, 0, 2)",
      "var float __obs_submatrix_rows = na",
      "__obs_submatrix_rows := matrix.rows(msub)",
      "var float __obs_submatrix_cols = na",
      "__obs_submatrix_cols := matrix.columns(msub)",
      // reshape: 2x3 -> 3x2 (row-major flatten then re-slice).
      "mreshape = matrix.reshape(m, 3, 2)",
      "var float __obs_reshape_00 = na",
      "__obs_reshape_00 := matrix.get(mreshape, 0, 0)",
      "var float __obs_reshape_12 = na",
      "__obs_reshape_12 := matrix.get(mreshape, 1, 1)",
      // sort: ascending by column 0.
      "matrix.sort(m, 0, order.ascending)",
      "var float __obs_sort_top = na",
      "__obs_sort_top := matrix.get(m, 0, 0)",
      // diff: row-to-row difference.
      "mdiff = matrix.diff(m)",
      "var float __obs_diff_00 = na",
      "__obs_diff_00 := matrix.get(mdiff, 0, 0)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [10], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    // m starts [[3,1,2],[6,4,5]] -> fill(9.0, rows[0,1), cols[0,2)) only touches row 0 cols 0-1.
    expect(bars[0]!["var:__obs_fill_hit"]).toBe(9);
    expect(bars[0]!["var:__obs_fill_untouched"]).toBe(2);
    // copy taken before fill mutated m -> still holds the original (0,0)=3.
    expect(bars[0]!["var:__obs_copy_independent"]).toBe(3);
    // after fill: [[9,9,2],[6,4,5]] -> reverse -> [[6,4,5],[9,9,2]] -> top(0,0)=6.
    expect(bars[0]!["var:__obs_reverse_top"]).toBe(6);
    // concat rows: [[6,4,5],[9,9,2]] + [[7,7,7]] -> 3 rows, last row first col = 7.
    expect(bars[0]!["var:__obs_concat_rows"]).toBe(3);
    expect(bars[0]!["var:__obs_concat_last"]).toBe(7);
    // submatrix(mcat, 0, 1, 0, 2) -> 1x2 block.
    expect(bars[0]!["var:__obs_submatrix_rows"]).toBe(1);
    expect(bars[0]!["var:__obs_submatrix_cols"]).toBe(2);
    // reshape [[6,4,5],[9,9,2]] (flat [6,4,5,9,9,2]) into 3x2 -> [[6,4],[5,9],[9,2]].
    expect(bars[0]!["var:__obs_reshape_00"]).toBe(6);
    expect(bars[0]!["var:__obs_reshape_12"]).toBe(9);
    // sort m=[[6,4,5],[9,9,2]] ascending by column 0 -> [[6,4,5],[9,9,2]] already ascending, top stays 6.
    expect(bars[0]!["var:__obs_sort_top"]).toBe(6);
    // diff of sorted m: row1-row0 = [9-6,9-4,2-5] = [3,5,-3].
    expect(bars[0]!["var:__obs_diff_00"]).toBe(3);
  });

  // ── matrix.is_square/is_symmetric/is_antisymmetric/is_diagonal/is_antidiagonal/is_identity/
  // is_triangular/is_stochastic/is_binary/is_zero (C94, 다섯 번째 슬라이스 — 순수 읽기 술어,
  // 뮤테이션 없음) ──

  it("emits matrix.is_square/is_symmetric/is_binary/is_zero through their dotted rt.matrix paths", () => {
    const code = codegenSource(
      [
        "var m = matrix.new<float>(2, 2, 0.0)",
        "a = matrix.is_square(m)",
        "b = matrix.is_symmetric(m)",
        "c = matrix.is_binary(m)",
        "d = matrix.is_zero(m)",
      ].join("\n"),
    );
    expect(code).toContain("var a = rt.matrix.is_square($.vars[0]);");
    expect(code).toContain("var b = rt.matrix.is_symmetric($.vars[0]);");
    expect(code).toContain("var c = rt.matrix.is_binary($.vars[0]);");
    expect(code).toContain("var d = rt.matrix.is_zero($.vars[0]);");
  });

  it("does not hoist non-mutating matrix.is_square in a lazy branch (pure read, C94)", () => {
    const code = codegenSource(["var m = matrix.new<float>(2, 2, 0.0)", "x = close > open ? matrix.is_square(m) : false"].join("\n"));
    expect(code).not.toContain("__lazy0");
  });

  it("allows a conditional if-body call to matrix.is_square/is_zero (stateless dispatch, no HoistingPass constraint, C94)", () => {
    const code = codegenSource(
      ["var m = matrix.new<float>(2, 2, 0.0)", "if close > open", "    x = matrix.is_square(m)", "    y = matrix.is_zero(m)"].join("\n"),
    );
    expect(code).toContain("rt.matrix.is_square($.vars[0])");
    expect(code).toContain("rt.matrix.is_zero($.vars[0])");
  });

  it("transpile() end-to-end: matrix.is_* predicates evaluate structural properties correctly", () => {
    const source = [
      // 3x3 symmetric matrix with distinct diagonal values (diagonal must be ignored).
      "var m = matrix.new<float>(3, 3, 0.0)",
      "matrix.set(m, 0, 0, 9.0)",
      "matrix.set(m, 0, 1, 2.0)",
      "matrix.set(m, 0, 2, 3.0)",
      "matrix.set(m, 1, 0, 2.0)",
      "matrix.set(m, 1, 1, 5.0)",
      "matrix.set(m, 1, 2, 6.0)",
      "matrix.set(m, 2, 0, 3.0)",
      "matrix.set(m, 2, 1, 6.0)",
      "matrix.set(m, 2, 2, 7.0)",
      "var float __obs_square = na",
      "__obs_square := matrix.is_square(m) ? 1.0 : 0.0",
      "var float __obs_symmetric = na",
      "__obs_symmetric := matrix.is_symmetric(m) ? 1.0 : 0.0",
      "var float __obs_diagonal = na",
      "__obs_diagonal := matrix.is_diagonal(m) ? 1.0 : 0.0",
      // break symmetry by mutating one off-diagonal cell.
      "matrix.set(m, 1, 2, 60.0)",
      "var float __obs_symmetric_after_break = na",
      "__obs_symmetric_after_break := matrix.is_symmetric(m) ? 1.0 : 0.0",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [10], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_square"]).toBe(1);
    expect(bars[0]!["var:__obs_symmetric"]).toBe(1);
    // diagonal itself has distinct values (9,5,7) -> not a diagonal matrix (off-diagonal 2/3/6 nonzero).
    expect(bars[0]!["var:__obs_diagonal"]).toBe(0);
    expect(bars[0]!["var:__obs_symmetric_after_break"]).toBe(0);
  });

