  it("transpile() end-to-end: matrix.sum/avg/min/max/median/mode compute over a matrix with an embedded na", () => {
    const source = [
      // 2x2 matrix: [[10, na], [30, 10]] -> valid = [10, 30, 10].
      "var m = matrix.new<float>(2, 2, 0.0)",
      "matrix.set(m, 0, 0, 10.0)",
      "matrix.set(m, 0, 1, na)",
      "matrix.set(m, 1, 0, 30.0)",
      "matrix.set(m, 1, 1, 10.0)",
      "var float __obs_sum = na",
      "__obs_sum := matrix.sum(m)",
      "var float __obs_avg = na",
      "__obs_avg := matrix.avg(m)",
      "var float __obs_min = na",
      "__obs_min := matrix.min(m)",
      "var float __obs_max = na",
      "__obs_max := matrix.max(m)",
      "var float __obs_median = na",
      "__obs_median := matrix.median(m)",
      "var float __obs_mode = na",
      "__obs_mode := matrix.mode(m)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [10], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_sum"]).toBe(50);
    expect(bars[0]!["var:__obs_avg"]).toBeCloseTo(50 / 3, 10);
    expect(bars[0]!["var:__obs_min"]).toBe(10);
    expect(bars[0]!["var:__obs_max"]).toBe(30);
    // sorted valid = [10, 10, 30], odd count -> middle value.
    expect(bars[0]!["var:__obs_median"]).toBe(10);
    // 10 appears twice, 30 once -> mode is 10.
    expect(bars[0]!["var:__obs_mode"]).toBe(10);
  });

