  it("transpile() end-to-end remembers the last non-na value across na bars (fixnan recall)", () => {
    // sample10.json류 오라클 데이터는 close에 na가 없어 회상(recall) 분기를 검증할 수 없다
    // (pine2py의 fixnan은 Series가 아닌 스칼라 인자를 그대로 통과시켜 오라클로 이 분기를
    // 만들 방법이 없음 — MEMORY.md "오라클 제외" 패턴, oracle/cases/fixnan_basic.pine 주석 참조).
    // 그래서 na가 실제로 섞인 합성 OHLCV 데이터로 손 계산한 기대값과 직접 대조한다.
    const source = ["var float __obs_fixnan = na", "__obs_fixnan := fixnan(close)"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [10, NaN, NaN, 20, NaN, 30, NaN, NaN, NaN, 40];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars.map((b) => b["var:__obs_fixnan"])).toEqual([10, 10, 10, 20, 20, 30, 30, 30, 30, 40]);
  });

  it("transpile() end-to-end returns na from fixnan until the first non-na value appears", () => {
    const source = ["var float __obs_fixnan = na", "__obs_fixnan := fixnan(close)"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [NaN, NaN, 5, NaN];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_fixnan"]).toBeNaN();
    expect(bars[1]!["var:__obs_fixnan"]).toBeNaN();
    expect(bars[2]!["var:__obs_fixnan"]).toBe(5);
    expect(bars[3]!["var:__obs_fixnan"]).toBe(5);
  });

  it("transpile() end-to-end computes nz() default(0)/explicit replacement for a permanently-na var", () => {
    const source = [
      "var float __obs_raw = na",
      "var float __obs_default = na",
      "__obs_default := nz(__obs_raw)",
      "var float __obs_replacement = na",
      "__obs_replacement := nz(__obs_raw, -5.0)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = { open: [1], high: [1], low: [1], close: [1], volume: [1] };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_default"]).toBe(0);
    expect(bars[0]!["var:__obs_replacement"]).toBe(-5);
  });

