// ── UDT 필드 타입 확장: 2단계 이상 중첩 제네릭 컨테이너 필드(C127) — genUdtFieldDefault/
// udtGenericFieldBase는 첫 '<' 앞의 base 이름만 보고 분기하므로(analyzer.ts parseGenericFieldType의
// 깊이 무관), 중첩 깊이가 몇 단계든 outer base(array/map)에 따라 그대로 '[]'/'new Map()'을 낸다 —
// 이 describe는 코드 변경이 필요 없었음을 실제로 확인하는 회귀 테스트. ──────────────────────
describe("CodeGen UDT nested generic container fields (array<map<K,V>>/map<K,array<V>>, C127)", () => {
  function moduleSource(source: string): string {
    return generateCode(analyze(parse(source)));
  }

  it("emits '[]' for an array<map<string, float>> field (outer base is array, nesting depth irrelevant)", () => {
    const code = moduleSource(["type Basket", "    array<map<string, float>> grouped"].join("\n"));
    expect(code).toContain("function Basket(p0 = []) {");
  });

  it("emits 'new Map()' for a map<string, array<float>> field (outer base is map, nesting depth irrelevant)", () => {
    const code = moduleSource(["type Basket", "    map<string, array<float>> groups"].join("\n"));
    expect(code).toContain("function Basket(p0 = new Map()) {");
  });

  it("end-to-end: map<string, array<float>> field — map.put an array.new_float() value, then array.push/array.size/array.sum through map.get round-trip", () => {
    const source = [
      "type Basket",
      "    map<string, array<float>> groups",
      "var b = Basket.new()",
      "var int barN = 0",
      "barN := barN + 1",
      'if barN == 1',
      '    map.put(b.groups, "prices", array.new_float(0))',
      'array.push(map.get(b.groups, "prices"), close)',
      "var float __obs_size = na",
      '__obs_size := array.size(map.get(b.groups, "prices"))',
      "var float __obs_sum = na",
      '__obs_sum := array.sum(map.get(b.groups, "prices"))',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [10, 20, 30];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_size"])).toEqual([1, 2, 3]);
    expect(bars.map((b) => b["var:__obs_sum"])).toEqual([10, 30, 60]);
  });

  it("end-to-end: array<map<string, float>> field — array.push a map.new<K,V>() value, then map.put/map.get through array.get round-trip", () => {
    const source = [
      "type Basket",
      "    array<map<string, float>> entries",
      "var b = Basket.new()",
      "var int barN = 0",
      "barN := barN + 1",
      "if barN == 1",
      "    array.push(b.entries, map.new<string, float>())",
      'map.put(array.get(b.entries, 0), "last", close)',
      "var float __obs_tag = na",
      '__obs_tag := map.get(array.get(b.entries, 0), "last")',
      "var float __obs_entries_size = na",
      "__obs_entries_size := array.size(b.entries)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [5, 6, 7];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_tag"])).toEqual([5, 6, 7]);
    expect(bars.map((b) => b["var:__obs_entries_size"])).toEqual([1, 1, 1]);
  });
});

describe("CodeGen enum (literal members only, UDT slice 2)", () => {
  it("emits nothing for the enum declaration itself (pure compile-time construct, unlike the UDT factory)", () => {
    const code = codegenSource(["enum Direction", "    long", "    short", "d = 1"].join("\n"));
    expect(code).toBe("var d = 1;");
  });

  it("lowers 'EnumName.member' to a JSON-quoted qualified string literal, same mechanism as color.*", () => {
    const code = codegenSource(["enum Direction", "    long", "d = Direction.long"].join("\n"));
    expect(code).toBe('var d = "Direction.long";');
  });

  it("lowers an equality comparison between an enum-typed var and a member access to a plain '===' string compare", () => {
    const code = codegenSource(
      ["enum Direction", "    long", "var Direction d = Direction.long", "y = d == Direction.long"].join("\n"),
    );
    expect(code).toContain('rt.pineEq($.vars[0], "Direction.long")');
  });

  it("lowers 'var Direction d = na' to 'null', not the generic 'NaN' (reference-type na, same as string/UDT)", () => {
    const code = codegenSource(["enum Direction", "    long", "var Direction d = na"].join("\n"));
    expect(code).toContain("if ($.vars[0] === undefined) { $.vars[0] = null; }");
  });

  it("keeps two different enums' same-named members as distinct qualified strings in emitted code", () => {
    const code = codegenSource(
      ["enum Direction", "    long", "enum Signal", "    long", "a = Direction.long", "b = Signal.long"].join("\n"),
    );
    expect(code).toContain('var a = "Direction.long";');
    expect(code).toContain('var b = "Signal.long";');
  });

  it("end-to-end: an enum-typed var starts na, gets assigned a member on bar 1, and reads back equal to that member thereafter", () => {
    const source = [
      "enum Direction",
      "    long",
      "    short",
      "var Direction d = na",
      "if d == na",
      "    d := Direction.long",
      "var bool __obs_is_long = na",
      "__obs_is_long := d == Direction.long",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_is_long"])).toEqual([true, true, true]);
  });

  it("end-to-end: a switch over an enum-typed var dispatches on the matching member case", () => {
    const source = [
      "enum Direction",
      "    long",
      "    short",
      "var Direction d = Direction.short",
      "var float __obs_label = na",
      "switch d",
      "    Direction.long =>",
      "        __obs_label := 1.0",
      "    Direction.short =>",
      "        __obs_label := 2.0",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_label"])).toEqual([2, 2]);
  });
});

// ── enum 멤버 title 문자열 할당(C136) — title은 순수 표시 메타데이터라 codegen 출력에 아무
// 영향도 주지 않아야 한다(analyzer가 값 폴딩에 title을 아예 참조하지 않음, ast.ts EnumMember 주석).
describe("CodeGen enum member titles (C136)", () => {
  it("emits nothing for the enum declaration itself, titled members included", () => {
    const code = codegenSource(["enum Direction", '    long = "Long Position"', "d = 1"].join("\n"));
    expect(code).toBe("var d = 1;");
  });

  it("lowers a titled member access identically to a bare member access (title does not appear in codegen output)", () => {
    const withTitle = codegenSource(["enum Direction", '    long = "Long Position"', "d = Direction.long"].join("\n"));
    const bare = codegenSource(["enum Direction", "    long", "d = Direction.long"].join("\n"));
    expect(withTitle).toBe('var d = "Direction.long";');
    expect(withTitle).toBe(bare);
  });

  it("end-to-end: equality/switch behavior is unaffected by whether the matching member has a title", () => {
    const source = [
      "enum Direction",
      '    long = "Long Position"',
      "    short",
      "var Direction d = Direction.short",
      "var float __obs_label = na",
      "switch d",
      "    Direction.long =>",
      "        __obs_label := 1.0",
      "    Direction.short =>",
      "        __obs_label := 2.0",
      "var bool __obs_is_short = na",
      "__obs_is_short := d == Direction.short",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_label"])).toEqual([2, 2]);
    expect(bars.map((b) => b["var:__obs_is_short"])).toEqual([true, true]);
  });
});

describe("CodeGen method (UDT slice 4)", () => {
  function moduleSource(source: string): string {
    return generateCode(analyze(parse(source)));
  }

  const POINT = ["type Point", "    float x = 0.0", "    float y = 0.0"].join("\n");

  it("emits a method declaration as a mangled top-level function 'TypeName$methodName'", () => {
    const code = moduleSource([POINT, "method area(Point p) => p.x"].join("\n"));
    expect(code).toContain("function Point$area(__slotBase, p) {\nreturn p.x;\n}");
  });

  it("lowers 'obj.method(args)' to a call of the mangled function with the object spliced in as the first argument after slotBase", () => {
    const code = codegenSource([POINT, "method translate(Point p, float dx) =>", "    p.x := p.x + dx", "var pt = Point.new()", "pt.translate(2.0)"].join("\n"));
    expect(code).toContain("Point$translate(0, $.vars[0], 2.0);");
  });

  it("lowers field read/write on the method's first parameter to a plain JS property access (not a var slot)", () => {
    const code = moduleSource([POINT, "method bump(Point p) =>", "    p.x := p.x + 1.0", "    p.x"].join("\n"));
    expect(code).toContain("function Point$bump(__slotBase, p) {\np.x = (p.x + 1.0);\nreturn p.x;\n}");
  });

  it("emits two distinct mangled functions for the same method name declared on two different UDTs (no flat-namespace collision)", () => {
    const code = moduleSource(
      ["type Rect", "    float w = 0.0", POINT, "method area(Rect r) => r.w", "method area(Point p) => p.x"].join("\n"),
    );
    expect(code).toContain("function Rect$area(__slotBase, r) {\nreturn r.w;\n}");
    expect(code).toContain("function Point$area(__slotBase, p) {\nreturn p.x;\n}");
  });

  it("emits a purely stateless method (no var/varip) with slotBase 0 at every call site", () => {
    const code = codegenSource([POINT, "method area(Point p) => p.x", "var p1 = Point.new()", "var p2 = Point.new()", "p1.area()", "p2.area()"].join("\n"));
    expect(code).toContain("Point$area(0, $.vars[0]);");
    expect(code).toContain("Point$area(0, $.vars[1]);");
  });

  it("gives two call sites of a stateful method (with an internal var) independent, non-overlapping fnVars slot bases", () => {
    const code = codegenSource(
      [
        POINT,
        "method tick(Point p) =>",
        "    var float n = 0.0",
        "    n := n + 1.0",
        "    n",
        "var p1 = Point.new()",
        "var p2 = Point.new()",
        "p1.tick()",
        "p2.tick()",
      ].join("\n"),
    );
    expect(code).toContain("Point$tick(0, $.vars[0]);");
    expect(code).toContain("Point$tick(1, $.vars[1]);");
  });

  it("hoists a var-stateful method call in a ternary lazy branch, same as a var-stateful UDF call (C197 — isVarStatefulUdfCall only checked Identifier callees, silently skipping DotAccess method calls)", () => {
    const code = codegenSource(
      [
        "type Counter",
        "    float dummy = 0.0",
        "method next(Counter c) =>",
        "    var int state = 0",
        "    state := state + 1",
        "    state",
        "var obj = Counter.new()",
        "x = close > open ? obj.next() : -1.0",
      ].join("\n"),
    );
    expect(code).toContain(
      "function Counter$next(__slotBase, c) {\n" +
        "if ($.fnVars[__slotBase + 0] === undefined) { $.fnVars[__slotBase + 0] = 0; }\n" +
        "$.fnVars[__slotBase + 0] = ($.fnVars[__slotBase + 0] + 1);\n" +
        "return $.fnVars[__slotBase + 0];\n" +
        "}",
    );
    expect(code).toContain(
      "let __lazy0 = Counter$next(0, $.vars[0]);\n" +
        "var x = (rt.pineGt($.close.get(0), $.open.get(0)) ? __lazy0 : (-1.0));",
    );
  });

  it("transpile() end-to-end: a var-stateful method's state advances every bar even on bars where the ternary picks the other branch (lazy-hoisting parity with UDF calls)", () => {
    const source = [
      "type Counter",
      "    float dummy = 0.0",
      "method next(Counter c) =>",
      "    var int state = 0",
      "    state := state + 1",
      "    state",
      "var obj = Counter.new()",
      "var float __obs_x = na",
      "__obs_x := close > open ? obj.next() : -1.0",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    // condition (close > open) alternates true/false/true/false/true across 5 bars.
    const open = [0, 1, 0, 1, 0];
    const close = [1, 0, 1, 0, 1];
    const data: OHLCVData = { open, high: close, low: open, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    // state increments every bar regardless of branch (1,2,3,4,5) — observed x is state's value on
    // true bars (1,_,3,_,5) and -1.0 on false bars. Without hoisting, state would only advance on
    // true bars, producing [1,-1,2,-1,3] instead (call is skipped by JS's lazy '?:' on false bars).
    expect(bars.map((b) => b["var:__obs_x"])).toEqual([1, -1, 3, -1, 5]);
  });

  it("end-to-end: a method mutates the object's field via ':=', and the mutation is visible to the caller afterward (reference semantics)", () => {
    const source = [
      POINT,
      "method translate(Point p, float dx, float dy) =>",
      "    p.x := p.x + dx",
      "    p.y := p.y + dy",
      "var pt = Point.new(1.0, 1.0)",
      "pt.translate(2.0, 3.0)",
      "var float __obs_x = na",
      "var float __obs_y = na",
      "__obs_x := pt.x",
      "__obs_y := pt.y",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    // translate() runs every bar (unconditional top-level statement), so on the only bar here
    // pt.x/pt.y move from their constructor values (1.0, 1.0) by (dx=2.0, dy=3.0) exactly once.
    expect(bars[0]!["var:__obs_x"]).toBe(3);
    expect(bars[0]!["var:__obs_y"]).toBe(4);
  });

  it("end-to-end: a method with an implicit return value (last expression) can be used directly in an assignment", () => {
    const source = [POINT, "var pt = Point.new(3.0, 4.0)", "method magnitude(Point p) => math.sqrt(p.x * p.x + p.y * p.y)", "var float __obs_mag = na", "__obs_mag := pt.magnitude()"].join(
      "\n",
    );
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_mag"]).toBe(5);
  });

  it("end-to-end: two different UDTs with the same method name dispatch to their own type's implementation (diverges from pine2py's flat-namespace collision, LIMITATIONS.md)", () => {
    const source = [
      "type Rect",
      "    float w = 10.0",
      POINT,
      "method area(Rect r) => r.w",
      "method area(Point p) => p.x",
      "var rect = Rect.new()",
      "var pt = Point.new(7.0, 0.0)",
      "var float __obs_rect_area = na",
      "var float __obs_pt_area = na",
      "__obs_rect_area := rect.area()",
      "__obs_pt_area := pt.area()",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_rect_area"]).toBe(10);
    expect(bars[0]!["var:__obs_pt_area"]).toBe(7);
  });
});

// ── UDT method 호출 키워드 인자(C408) — UDF 호출 kwargs(C396, 위)와 완전히 동일한 원리: 함수
// 선언(genMethodDecl)은 변경 없이 여전히 JS 네이티브 default parameter를 쓰고, 호출부만 값이
// 실제로 지정된 가장 뒤쪽 슬롯까지 채우며 그 범위 안에서 건너뛴 슬롯을 리터럴 "undefined"로
// 채운다. receiver(objCode)는 kwargs 이름 공간/슬롯 계산 어느 쪽에도 안 들어간다. ─────────────
describe("CodeGen UDT method call keyword arguments (C408)", () => {
  const POINT = ["type Point", "    float x = 0.0", "    float y = 0.0"].join("\n");

  it("lowers an all-keyword UDT method call to positional slots in parameter-declaration order", () => {
    const code = codegenSource(
      [POINT, "method move(Point p, float dx, float dy) =>", "    p.x := p.x + dx", "    p.y := p.y + dy", "var pt = Point.new()", "pt.move(dy = 2.0, dx = 1.0)"].join(
        "\n",
      ),
    );
    expect(code).toContain("Point$move(0, $.vars[0], 1.0, 2.0);");
  });

  it("fills a skipped optional middle slot with a literal 'undefined' token so JS default params apply", () => {
    const code = codegenSource(
      [
        POINT,
        "method scale(Point p, float mult = 2.0, float offset = 0.0) =>",
        "    p.x := p.x * mult + offset",
        "var pt = Point.new()",
        "pt.scale(offset = 3.0)",
      ].join("\n"),
    );
    expect(code).toContain("Point$scale(0, $.vars[0], undefined, 3.0);");
  });

  it("leaves an existing kwargs-free UDT method call site byte-for-byte unchanged (regression, C129 'no undefined tokens for pure positional calls' principle)", () => {
    const code = codegenSource(
      [POINT, "method translate(Point p, float dx) =>", "    p.x := p.x + dx", "var pt = Point.new()", "pt.translate(2.0)"].join("\n"),
    );
    expect(code).toContain("Point$translate(0, $.vars[0], 2.0);");
  });

  it("end-to-end: an all-keyword UDT method call (out of declaration order) resolves each parameter by name, not by write order", () => {
    const source = [
      POINT,
      "method move(Point p, float dx, float dy) =>",
      "    p.x := p.x + dx",
      "    p.y := p.y + dy",
      "var pt = Point.new(1.0, 1.0)",
      "pt.move(dy = 3.0, dx = 2.0)",
      "var float __obs_x = na",
      "var float __obs_y = na",
      "__obs_x := pt.x",
      "__obs_y := pt.y",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_x"]).toBe(3);
    expect(bars[0]!["var:__obs_y"]).toBe(4);
  });

  it("end-to-end: a keyword argument for a later optional parameter leaves an earlier skipped optional parameter at its own default", () => {
    const source = [
      POINT,
      "method scale(Point p, float mult = 2.0, float offset = 0.0) =>",
      "    p.x := p.x * mult + offset",
      "var pt = Point.new(5.0, 0.0)",
      "pt.scale(offset = 3.0)",
      "var float __obs_x = na",
      "__obs_x := pt.x",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    // mult keeps its own default (2.0) since only offset was specified by keyword: 5.0*2.0+3.0=13.
    expect(bars[0]!["var:__obs_x"]).toBe(13);
  });
});

// ── bare method(receiver, ...) call form (C267, corpus 1624ff60e8a0.pine `isPositive(ind)`) ────
describe("CodeGen bare method(receiver, ...) call (C267)", () => {
  const POINT = ["type Point", "    float x = 0.0", "    float y = 0.0"].join("\n");

  it("lowers a bare 'methodName(obj, args)' call to the mangled function, passing expr.args through unchanged (no object-splicing needed — the receiver is already args[0])", () => {
    const code = codegenSource([POINT, "method translate(Point p, float dx) =>", "    p.x := p.x + dx", "var pt = Point.new()", "translate(pt, 2.0)"].join("\n"));
    expect(code).toContain("Point$translate(0, $.vars[0], 2.0);");
  });

  it("emits the exact same call code for the bare form and the dot-call form of the same call site (both resolve to the same mangled function)", () => {
    const bare = codegenSource([POINT, "method area(Point p) => p.x", "var pt = Point.new()", "area(pt)"].join("\n"));
    const dot = codegenSource([POINT, "method area(Point p) => p.x", "var pt = Point.new()", "pt.area()"].join("\n"));
    expect(bare).toContain("Point$area(0, $.vars[0]);");
    expect(dot).toContain("Point$area(0, $.vars[0]);");
  });

  it("hoists a var-stateful method call reached via the bare form in a ternary lazy branch (mirrors the C197 dot-call fix — isVarStatefulUdfCall must resolve the mangled name via udtMethodCallTypes for Identifier callees too)", () => {
    const code = codegenSource(
      [
        "type Counter",
        "    float dummy = 0.0",
        "method next(Counter c) =>",
        "    var int state = 0",
        "    state := state + 1",
        "    state",
        "var obj = Counter.new()",
        "x = close > open ? next(obj) : -1.0",
      ].join("\n"),
    );
    expect(code).toContain(
      "let __lazy0 = Counter$next(0, $.vars[0]);\n" +
        "var x = (rt.pineGt($.close.get(0), $.open.get(0)) ? __lazy0 : (-1.0));",
    );
  });

  it("end-to-end: a var-stateful method reached via the bare form advances state every bar even on bars where the ternary picks the other branch", () => {
    const source = [
      "type Counter",
      "    float dummy = 0.0",
      "method next(Counter c) =>",
      "    var int state = 0",
      "    state := state + 1",
      "    state",
      "var obj = Counter.new()",
      "var float __obs_x = na",
      "__obs_x := close > open ? next(obj) : -1.0",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const open = [0, 1, 0, 1, 0];
    const close = [1, 0, 1, 0, 1];
    const data: OHLCVData = { open, high: close, low: open, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_x"])).toEqual([1, -1, 3, -1, 5]);
  });

  it("end-to-end: a method mutates the object's field via ':=' when called through the bare form, and the mutation is visible to the caller afterward", () => {
    const source = [
      POINT,
      "method translate(Point p, float dx, float dy) =>",
      "    p.x := p.x + dx",
      "    p.y := p.y + dy",
      "var pt = Point.new(1.0, 1.0)",
      "translate(pt, 2.0, 3.0)",
      "var float __obs_x = na",
      "var float __obs_y = na",
      "__obs_x := pt.x",
      "__obs_y := pt.y",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_x"]).toBe(3);
    expect(bars[0]!["var:__obs_y"]).toBe(4);
  });
});

// ── JS 예약어와 충돌하는 Pine 로컬 이름(C271, corpus_scan `new Function` 미탐지 38건 -- method
// receiver 매개변수명이 `this`인 경우 codegen이 그 이름을 literal JS 파라미터로 방출해
// "Unexpected token 'this'" SyntaxError를 냈다). program.locals(UDF/method 매개변수, '=' 로컬,
// for/for-in 루프 변수, 튜플 디스트럭처링 대상)에 속하는 이름이 JS 예약어(strict-mode 전용 제약
// 단어 제외 -- 이 코드는 'use strict' 없음)와 겹치면 safeLocalName이 접미사 `_`를 붙여 방출한다
// (pine2py의 `open_` 관행과 동일 원칙). Pine 자신의 키워드(if/var/switch 등)와 겹치는 JS 예약어는
// 애초에 Pine IDENTIFIER로 토큰화될 수 없어 대상에서 제외됨(tokens.ts KEYWORDS 참조).
describe("CodeGen JS-reserved-word local names (C271)", () => {
  it("renames a method receiver parameter named 'this' (the exact corpus 1624ff60e8a0-class pattern) in both the signature and body references", () => {
    const code = codegenSource(
      [
        "type Box",
        "    float lo = 0.0",
        "    float hi = 0.0",
        "method contains(Box this, float val) =>",
        "    val >= this.lo and val <= this.hi",
        "b = Box.new(0.0, 100.0)",
        "x = b.contains(close)",
      ].join("\n"),
    );
    expect(code).toContain("function Box$contains(__slotBase, this_, val) {");
    expect(code).toContain("rt.pineAnd(rt.pineGe(val, this_.lo), rt.pineLe(val, this_.hi));");
  });

  it("renames a UDF parameter named 'new' in both the signature and body references", () => {
    const code = codegenSource(["f(float new) =>", "    new + 1.0", "x = f(close)"].join("\n"));
    expect(code).toContain("function f(__slotBase, new_) {");
    expect(code).toContain("return (new_ + 1.0);");
  });

  it("renames a top-level '=' local named 'class' at both declaration and read sites", () => {
    const code = codegenSource(["class = close + 1.0", "x = class"].join("\n"));
    expect(code).toContain("var class_ = ($.close.get(0) + 1.0);");
    expect(code).toContain("var x = class_;");
  });

  it("renames a nested (UDF-body) '=' local named 'delete' to a 'let' binding", () => {
    const code = codegenSource(["f(float src) =>", "    delete = src + 1.0", "    delete", "x = f(close)"].join("\n"));
    expect(code).toContain("let delete_ = (src + 1.0);");
    expect(code).toContain("return delete_;");
  });

  it("renames a for-loop variable named 'in' throughout the header and body", () => {
    const code = codegenSource(["sum = 0.0", "for in = 0 to 3", "    sum := sum + in", "x = sum"].join("\n"));
    expect(code).toContain(
      "for (let in_ = __forStart; (__forFwd ? in_ <= __forEnd : in_ >= __forEnd) && __forLimit > 0; in_ += __forDelta) {",
    );
    expect(code).toContain("sum = (sum + in_);");
  });

  it("renames a for-in array loop variable named 'class'", () => {
    const code = codegenSource(
      ["arr = array.from(1.0, 2.0, 3.0)", "sum = 0.0", "for class in arr", "    sum := sum + class", "x = sum"].join("\n"),
    );
    expect(code).toContain("let class_ = __forInArr[__forInIdx];");
    expect(code).toContain("sum = (sum + class_);");
  });

  it("renames a for-in array loop index name ('new') separately from an unreserved value name", () => {
    const code = codegenSource(
      [
        "arr = array.from(1.0, 2.0, 3.0)",
        "sum = 0.0",
        "for [new, v] in arr",
        "    sum := sum + new + v",
        "x = sum",
      ].join("\n"),
    );
    expect(code).toContain("for (let new_ = 0; __forInArr !== null && new_ < __forInArr.length; new_++) {");
    expect(code).toContain("let v = __forInArr[new_];");
    expect(code).toContain("sum = ((sum + new_) + v);");
  });

  it("renames a tuple destructuring target named 'typeof'", () => {
    const code = codegenSource(["f() =>", "    [1.0, 2.0]", "[typeof, b] = f()", "x = typeof + b"].join("\n"));
    expect(code).toContain("var [typeof_, b] = f(0);");
    expect(code).toContain("var x = (typeof_ + b);");
  });

  it("end-to-end: a method whose receiver is named 'this' produces JS that actually parses and computes the correct value", () => {
    const source = [
      "type Box",
      "    float lo = 0.0",
      "    float hi = 0.0",
      "method contains(Box this, float val) =>",
      "    val >= this.lo and val <= this.hi",
      "b = Box.new(0.0, 100.0)",
      "var bool __obs_x = na",
      "__obs_x := b.contains(close)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(() => new Function("$", "rt", result.code)).not.toThrow();

    const close = [50, 150];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars.map((b) => b["var:__obs_x"])).toEqual([true, false]);
  });

  it("end-to-end: a for-loop variable named 'in' still accumulates the correct sum", () => {
    const source = ["var float __obs_x = na", "sum = 0.0", "for in = 0 to 3", "    sum := sum + in", "__obs_x := sum"].join(
      "\n",
    );
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_x"]).toBe(6); // 0+1+2+3
  });
});

describe("CodeGen copy (UDT slice 5, C125, DIVERGENCES.md #57)", () => {
  const POINT = ["type Point", "    float x = 0.0", "    float y = 0.0"].join("\n");

  it("lowers 'obj.copy()' to the rt.udtCopy runtime helper (no mangled function, no slotBase)", () => {
    const code = codegenSource([POINT, "var p = Point.new()", "p.copy()"].join("\n"));
    expect(code).toContain("rt.udtCopy($.vars[0]);");
  });

  it("still dispatches to a user-declared 'copy' method (mangled call, not rt.udtCopy) when one exists", () => {
    const code = codegenSource([POINT, "method copy(Point p) => p.x", "var pt = Point.new()", "pt.copy()"].join("\n"));
    expect(code).toContain("Point$copy(0, $.vars[0]);");
    expect(code).not.toContain("rt.udtCopy");
  });

  it("end-to-end: mutating a scalar field on the copy leaves the original untouched (true independence for primitive fields)", () => {
    const source = [
      POINT,
      "var Point orig = Point.new(1.0, 2.0)",
      "var Point dup = Point.new()",
      "dup := orig.copy()",
      "dup.x := 999.0",
      "var float __obs_orig_x = na",
      "var float __obs_dup_x = na",
      "__obs_orig_x := orig.x",
      "__obs_dup_x := dup.x",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_orig_x"]).toBe(1);
    expect(bars[0]!["var:__obs_dup_x"]).toBe(999);
  });

  it("end-to-end: mutating a NESTED UDT field on the copy also changes the original — true shallow copy shares the nested reference (diverges from pine2py's crashing point-call, DIVERGENCES.md #57)", () => {
    const source = [
      "type Inner",
      "    float x = 1.0",
      "type Outer",
      "    Inner inner = Inner.new()",
      "var Outer orig = Outer.new()",
      "var Outer dup = Outer.new()",
      "dup := orig.copy()",
      "dup.inner.x := 999.0",
      "var float __obs_orig_inner_x = na",
      "var float __obs_dup_inner_x = na",
      "__obs_orig_inner_x := orig.inner.x",
      "__obs_dup_inner_x := dup.inner.x",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    // Shared nested reference: mutating dup.inner.x also mutates orig.inner.x.
    expect(bars[0]!["var:__obs_orig_inner_x"]).toBe(999);
    expect(bars[0]!["var:__obs_dup_inner_x"]).toBe(999);
  });
});

// ── TypeName.copy(instance) static-call sugar (C645) — same rt.udtCopy runtime helper as the
// dot-call form, but the instance to copy is expr.args[0] rather than callee.obj.
describe("CodeGen copy static form (TypeName.copy(instance), C645)", () => {
  const POINT_S = ["type Point", "    float x = 0.0", "    float y = 0.0"].join("\n");

  it("lowers 'TypeName.copy(instance)' to the rt.udtCopy runtime helper using args[0], not callee.obj", () => {
    const code = codegenSource([POINT_S, "var Point p = Point.new()", "Point.copy(p)"].join("\n"));
    expect(code).toContain("rt.udtCopy($.vars[0]);");
  });

  it("end-to-end: static-form copy produces an independent object (mutating the copy leaves the source untouched)", () => {
    const source = [
      POINT_S,
      "var Point orig = Point.new(1.0, 2.0)",
      "var Point dup = Point.new()",
      "dup := Point.copy(orig)",
      "dup.x := 999.0",
      "var float __obs_orig_x = na",
      "var float __obs_dup_x = na",
      "__obs_orig_x := orig.x",
      "__obs_dup_x := dup.x",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_orig_x"]).toBe(1);
    expect(bars[0]!["var:__obs_dup_x"]).toBe(999);
  });

  it("passes the copy directly as a call argument (matches wild corpus pattern: array.set(arr, i, TypeName.copy(x)))", () => {
    const source = [
      POINT_S,
      "var arr = array.new<Point>(1, Point.new())",
      "var Point src = Point.new(5.0, 6.0)",
      "array.set(arr, 0, Point.copy(src))",
      "var float __obs_x = na",
      "__obs_x := array.get(arr, 0).x",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_x"]).toBe(5);
  });
});

