// ── UDF 반환값이 UDT 인스턴스일 때 그 반환값을 받는 '=' 로컬의 필드 접근(C253) — analyzer가
// udtFieldAccessTypes/udtKindHints를 이미 채워둔 뒤라 codegen 자체는 위 C224/C225 field 읽기/쓰기
// 분기를 그대로 재사용한다(신규 codegen 분기 0줄) — 여기서는 그 사실(출력이 기존 '=' 로컬 UDT
// field 읽기와 정확히 같은 모양임)만 확인한다. ─────────────────────────────────────
describe("CodeGen UDF-returned UDT instance field access (C253)", () => {
  it("lowers a field read on a '=' local assigned from a UDF call to the same plain JS property access as a direct constructor call", () => {
    const code = codegenSource(
      ["type Signal", "    float value = 0.0", "calcSignal(src) =>", "    Signal.new(src)", "sig = calcSignal(close)", "y = sig.value"].join(
        "\n",
      ),
    );
    expect(code).toContain("var y = sig.value;");
  });
});

// ── C636: 삼항 양쪽 분기가 새 생성자 콜이 아니라 이미 UDT로 확정된 bare Identifier를 그대로
// 참조하는 형태(wild `plan1 = cond ? planRaw : defaultPlan`) — analyzer가 scope.udtKindHints를
// resolveUdtObjectType 폴백으로 채워둔 뒤라 codegen은 기존 UDT field 읽기 분기를 그대로 재사용한다
// (신규 codegen 분기 0줄, C253/C264와 동일 원칙). ─────────────────────────────────────
describe("CodeGen ternary-of-bare-identifier-UDT-references field access (C636)", () => {
  it("lowers a field read on a '=' local whose RHS is a ternary between two already-known UDT identifiers to plain JS property access", () => {
    const code = codegenSource(
      [
        "type Plan",
        "    float now = na",
        "var defaultPlan = Plan.new(0.0)",
        "planRaw = Plan.new(1.0)",
        "plan1 = close > open ? planRaw : defaultPlan",
        "y = plan1.now",
      ].join("\n"),
    );
    expect(code).toContain("var y = plan1.now;");
  });

  it("end-to-end: the ternary selects the correct branch's instance and its field reads back correctly on both sides", () => {
    const source = [
      "type Plan",
      "    float now = na",
      "var defaultPlan = Plan.new(0.0)",
      "planRaw = Plan.new(1.0)",
      "plan1 = close > open ? planRaw : defaultPlan",
      "var float __obs_now = na",
      "__obs_now := plan1.now",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const open = [1, 2];
    const close = [2, 1];
    const data: OHLCVData = { open, high: close, low: open, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_now"]).toBe(1); // close(2) > open(1) -> planRaw.now
    expect(bars[1]!["var:__obs_now"]).toBe(0); // close(1) > open(2) is false -> defaultPlan.now
  });
});

// ── UDF가 튜플로 반환한 UDT 원소를 담은 top-level 튜플 디스트럭처 대상의 필드 접근(C387, wild
// `[top, btm] = swings(length)`) — analyzer가 scope.udtKindHints를 원소별로 채워둔 뒤라 codegen은
// C253과 마찬가지로 기존 UDT field 읽기 분기를 그대로 재사용한다(신규 codegen 분기 0줄). ──────
describe("CodeGen UDF tuple-returned UDT instance field access (C387)", () => {
  it("lowers a field read on both tuple-destructured names to plain JS property access", () => {
    const code = codegenSource(
      [
        "type Swing",
        "    float y = na",
        "swings(len) =>",
        "    var Swing top = Swing.new(na)",
        "    var Swing btm = Swing.new(na)",
        "    [top, btm]",
        "[top, btm] = swings(3)",
        "y = top.y + btm.y",
      ].join("\n"),
    );
    expect(code).toContain("var y = (top.y + btm.y);");
  });

  // C454: analyzer 쪽 갭(resolveTupleElemUdtType의 role==="var" 분기가 명시 typeHint 없이 생성자
  // 콜만으로 추론된 UDT는 못 잡던 것)만 수정 — codegen은 여기서도 신규 분기 0줄, 위와 동일 검증.
  it("lowers a field read on a tuple element inferred purely from its constructor call (no explicit typeHint)", () => {
    const code = codegenSource(
      [
        "type Fvg",
        "    float max = na",
        "detect() =>",
        "    var new_fvg = Fvg.new(na)",
        "    [true, new_fvg]",
        "[bull, new_fvg] = detect()",
        "y = new_fvg.max",
      ].join("\n"),
    );
    expect(code).toContain("var y = new_fvg.max;");
  });
});

// ── UDF가 튜플로 반환한 array 원소를 담은 top-level 튜플 디스트럭처 대상의 method-call sugar
// (C649, analyzer FuncInfo.tupleElemContainerKinds 신설 — wild `[fvgDn, ...] = fvg(-3)`류가 depth>0
// if 블록 안에서도 `.size()`/`.get()` 수신자로 정적 판별됨). analyzer가 scope.containerKindHints를
// 원소별로 채워둔 뒤라 codegen은 기존 array method-call sugar 분기(analyzeArrayCall +
// methodCallReceivers)를 그대로 재사용한다(신규 codegen 분기 0줄). ──────────────────────────
describe("CodeGen UDF tuple-returned array container method-call sugar (C649)", () => {
  it("lowers .size() on a tuple-destructured array element nested inside an if block to rt.array.size(name)", () => {
    const code = codegenSource(
      [
        "fvg(direction) =>",
        "    var fvgDrawings = array.new_box(0)",
        "    var fvgMidLines = array.new_line(0)",
        "    [fvgDrawings, fvgMidLines]",
        "show = true",
        "if show",
        "    [fvgDn, fvgDnLines] = fvg(-3)",
        "    y = fvgDn.size()",
      ].join("\n"),
    );
    expect(code).toContain("rt.array.size(fvgDn)");
  });

  it("end-to-end: pushing into the UDF-internal array before the tuple return is visible via .size()/.get() at the call site", () => {
    const source = [
      "mk() =>",
      "    var arr = array.new_float(0)",
      "    if bar_index == 1",
      "        array.push(arr, 42.0)",
      "    [arr, 1]",
      "show = true",
      "if show",
      "    [got, other] = mk()",
      "    var float __obs_size = na",
      "    __obs_size := got.size()",
      "    var float __obs_first = na",
      "    if got.size() > 0",
      "        __obs_first := got.get(0)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize);
    expect(bars[0]!["var:__obs_size"]).toBe(0);
    expect(bars[1]!["var:__obs_size"]).toBe(1);
    expect(bars[1]!["var:__obs_first"]).toBe(42);
    expect(bars[2]!["var:__obs_size"]).toBe(1);
  });
});

describe("CodeGen input.* (first slice: int/float/bool/string, C131 — implicit $.inputs injection)", () => {
  it("prepends '$.inputs' as an implicit first argument (Pine source has no such argument — same splice technique as ta.vwma's volume injection)", () => {
    const code = codegenSource('x = input.int(14, "Length")');
    expect(code).toContain('rt.input.int($.inputs, 14, "Length")');
  });

  it("prepends '$.inputs' for input.float/bool/string too", () => {
    expect(codegenSource('x = input.float(2.5, "Multiplier")')).toContain('rt.input.float($.inputs, 2.5, "Multiplier")');
    expect(codegenSource('x = input.bool(true, "Use Filter")')).toContain('rt.input.bool($.inputs, true, "Use Filter")');
    expect(codegenSource('x = input.string("hi", "Label")')).toContain('rt.input.string($.inputs, "hi", "Label")');
  });

  it("end-to-end: with no override supplied, each input.* returns its defval (matches pine2py's only reachable path)", () => {
    const source = [
      'len = input.int(14, "Length")',
      'mult = input.float(2.5, "Multiplier")',
      'flag = input.bool(true, "Use Filter")',
      'label = input.string("hello", "Label")',
      "var int __obs_len = na",
      "__obs_len := len",
      "var float __obs_mult = na",
      "__obs_mult := mult",
      "var bool __obs_flag = na",
      "__obs_flag := flag",
      "var string __obs_label = na",
      "__obs_label := label",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize);
    expect(bars[0]!["var:__obs_len"]).toBe(14);
    expect(bars[0]!["var:__obs_mult"]).toBe(2.5);
    expect(bars[0]!["var:__obs_flag"]).toBe(true);
    expect(bars[0]!["var:__obs_label"]).toBe("hello");
  });

  it("end-to-end: an override dict keyed by title takes priority over defval (pine2js-exclusive feature — pine2py has no such path, DIVERGENCES.md)", () => {
    const source = ['len = input.int(14, "Length")', "var int __obs_len = na", "__obs_len := len"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      { Length: 200 },
    );
    expect(bars[0]!["var:__obs_len"]).toBe(200);
  });

  it("end-to-end: an override under an unrelated title doesn't affect an input whose title doesn't match", () => {
    const source = ['len = input.int(14, "Length")', "var int __obs_len = na", "__obs_len := len"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      { SomeOtherTitle: 999 },
    );
    expect(bars[0]!["var:__obs_len"]).toBe(14);
  });

  it("end-to-end: two different input.* calls with distinct titles resolve independently against the same override dict", () => {
    const source = [
      'a = input.int(1, "A")',
      'b = input.int(2, "B")',
      "var int __obs_a = na",
      "var int __obs_b = na",
      "__obs_a := a",
      "__obs_b := b",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      { B: 20 },
    );
    expect(bars[0]!["var:__obs_a"]).toBe(1);
    expect(bars[0]!["var:__obs_b"]).toBe(20);
  });
});

// ── input.* 키워드 인자(title=/minval=/maxval=/step=, C132) — UDT `.new()` kwargs(C129, "CodeGen
