// ── UI-metadata kwargs (C283) — wild 코퍼스 1위 클러스터 해소분의 codegen 검증: metadata kwarg는
// paramNames 슬롯이 아니라 codegen 방출 루프가 아예 조회하지 않아 최종 JS에 실리지 않는다(값
// discard). analyzer 수용 검증은 analyzer.test.ts C283 describe 참조. ────────────────────────────
describe("CodeGen UI-metadata kwargs are dropped from emission (C283)", () => {
  it("drops group/tooltip/inline/confirm from the emitted input.int call", () => {
    const code = codegenSource('x = input.int(14, "Len", group="G", tooltip="tt", inline="a", confirm=true)');
    expect(code).toBe('var x = rt.input.int($.inputs, 14, "Len");');
  });

  it("drops active= (C348) from the emitted input.int call", () => {
    const code = codegenSource('x = input.int(14, "Len", active=true)');
    expect(code).toBe('var x = rt.input.int($.inputs, 14, "Len");');
  });

  it("drops display= (namespace-constant value) from the emitted input.int call", () => {
    const code = codegenSource("x = input.int(14, display=display.data_window)");
    expect(code).toBe("var x = rt.input.int($.inputs, 14);");
  });

  it("drops options=[...] from the emitted input.int call (widened beyond string, same skip path)", () => {
    const code = codegenSource('x = input.int(14, "Len", options=[7, 14, 21])');
    expect(code).toBe('var x = rt.input.int($.inputs, 14, "Len");');
  });

  it("keeps real positional slots (minval/maxval/step) intact when metadata kwargs follow them", () => {
    const code = codegenSource('x = input.int(14, "Len", 1, 100, 1, group="G")');
    expect(code).toBe('var x = rt.input.int($.inputs, 14, "Len", 1, 100, 1);');
  });

  it("drops metadata kwargs from the emitted bare input() call", () => {
    const code = codegenSource('x = input(42, "T", group="G", tooltip="tt")');
    expect(code).toBe('var x = rt.input.any($.inputs, 42, "T");');
  });

  it("drops minval=/maxval=/step= (C349) from the emitted input.bool call (no positional slot for these on bool, pure kwarg discard)", () => {
    const code = codegenSource('x = input.bool(true, "T", minval=0, maxval=1, step=1)');
    expect(code).toBe('var x = rt.input.bool($.inputs, true, "T");');
  });

  it("drops minval=/maxval= (C349) from the emitted bare input() call (wild idiom: input(3, title=..., minval=1, maxval=100))", () => {
    const code = codegenSource('x = input(3, title="[ST] Factor", minval=1, maxval=100)');
    expect(code).toBe('var x = rt.input.any($.inputs, 3, "[ST] Factor");');
  });

  it("end-to-end: active= referencing another declared input still emits and evaluates both inputs normally (real-world conditional-display idiom)", () => {
    const source = [
      'showEma = input.bool(true, "Show EMA")',
      'len = input.int(14, "Len", active=showEma)',
      "var float __obs_len = na",
      "__obs_len := len",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.code).not.toContain("active");

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const plain = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize);
    expect(plain.bars[0]!["var:__obs_len"]).toBe(14);
  });

  it("end-to-end: input.int with full metadata kwargs still returns its defval and honors a title-keyed override", () => {
    const source = ['n = input.int(14, "Len", group="G", tooltip="tt", confirm=true)', "var float __obs_n = na", "__obs_n := n"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const plain = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize);
    expect(plain.bars[0]!["var:__obs_n"]).toBe(14);
    const overridden = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      { Len: 21 },
    );
    expect(overridden.bars[0]!["var:__obs_n"]).toBe(21);
  });

  it("transpiles plot transp= / indicator dynamic_requests= to the same output as without them (pure discard)", () => {
    const withMeta = codegenSource('plot(close, "T", color.red, transp=20)');
    const without = codegenSource('plot(close, "T", color.red)');
    expect(withMeta).toBe(without);
    const indWith = codegenSource('indicator("t", dynamic_requests=true, max_tables_count=2)\nplot(close)');
    const indWithout = codegenSource('indicator("t")\nplot(close)');
    expect(indWith).toBe(indWithout);
  });

  it("transpiles strategy behind_chart= / indicator linktoseries= to the same output as without them (C560, pure discard)", () => {
    const stratWith = codegenSource('strategy("t", behind_chart=false)\nplot(close)');
    const stratWithout = codegenSource('strategy("t")\nplot(close)');
    expect(stratWith).toBe(stratWithout);
    const indWith = codegenSource('indicator("t", linktoseries=true)\nplot(close)');
    const indWithout = codegenSource('indicator("t")\nplot(close)');
    expect(indWith).toBe(indWithout);
  });
});

// ── plot() collection channel (PlotCollector, C135) — pine2py has no working implementation to
// port from (context.plots is a dead stub, see analyzer.ts plot branch comment), so this is a
// pine2js-original design per GOAL.md "plot은 Float64Array 수집 채널". Oracle-incomparable (the
// py_oracle bridge never touches context.plots either) — hand-verified only, same class as
// input.* override paths (C131 DIVERGENCES #60). ──────────────────────────────────────────
describe("CodeGen plot() collection channel (C135)", () => {
  it("emits '$.plots[N].record(seriesValue)', dropping the title argument entirely", () => {
    const code = codegenSource('plot(close, "RSI")');
    expect(code).toBe('$.plots[0].record($.close.get(0));');
  });

  it("emits the same record() call with no title argument at all", () => {
    const code = codegenSource("plot(close)");
    expect(code).toBe("$.plots[0].record($.close.get(0));");
  });

  it("assigns sequential slot indices to multiple plot() calls in source order", () => {
    const code = codegenSource('plot(open, "O")\nplot(close, "C")');
    expect(code).toBe('$.plots[0].record($.open.get(0));\n$.plots[1].record($.close.get(0));');
  });

  it("lowers a computed series expression, not just a bare identifier", () => {
    const code = codegenSource("plot(close + 1.0)");
    expect(code).toBe("$.plots[0].record(($.close.get(0) + 1.0));");
  });

  // C313: 'series=' 키워드 인자로 온 series 값도 위치 인자와 exact-string 동일 출력을 내야 한다
  // (analyzer가 title처럼 순수 메타데이터로 소비하지 않고 codegen이 실제 record()해야 하는 유일한
  // 렌더링-외 값이라 여기서만 kwarg-vs-positional 분기가 실제 출력에 영향).
  it("emits the same record() call when the series is given as a 'series=' keyword argument", () => {
    const code = codegenSource('plot(series=close, title="RSI")');
    expect(code).toBe("$.plots[0].record($.close.get(0));");
  });

  it("lowers a computed 'series=' keyword expression identically to the positional form", () => {
    const code = codegenSource("plot(series=close + 1.0)");
    expect(code).toBe("$.plots[0].record(($.close.get(0) + 1.0));");
  });

  it("end-to-end: collects the series value across every bar into RunResult.plots", () => {
    const source = 'plot(close, "C")';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const closeData = [10, 20, 30];
    const data: OHLCVData = { open: closeData, high: closeData, low: closeData, close: closeData, volume: closeData };
    const { plots } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize, {}, result.plotTitles);
    expect(plots).toEqual([{ title: "C", values: [10, 20, 30] }]);
  });

  it("end-to-end: multiple plot() calls collect independent value arrays", () => {
    const source = 'plot(close, "C")\nplot(close * 2, "Double")';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const closeData = [1, 2, 3];
    const data: OHLCVData = { open: closeData, high: closeData, low: closeData, close: closeData, volume: closeData };
    const { plots } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize, {}, result.plotTitles);
    expect(plots).toEqual([
      { title: "C", values: [1, 2, 3] },
      { title: "Double", values: [2, 4, 6] },
    ]);
  });

  it("end-to-end: an untitled plot() gets the default 'Plot N' title", () => {
    const source = "plot(close)";
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const closeData = [5];
    const data: OHLCVData = { open: closeData, high: closeData, low: closeData, close: closeData, volume: closeData };
    const { plots } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize, {}, result.plotTitles);
    expect(plots).toEqual([{ title: "Plot 0", values: [5] }]);
  });

  it("end-to-end: RunResult.plots is an empty array for a script with no plot() calls (backward compatible default)", () => {
    const source = "var float acc = 0.0";
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const closeData = [1];
    const data: OHLCVData = { open: closeData, high: closeData, low: closeData, close: closeData, volume: closeData };
    const { plots } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(plots).toEqual([]);
  });
});

// ── request.security 첫 슬라이스(C176, ROADMAP P2 [hard->분할]) — pine2py의 SecurityManager는
// 오라클 대조가 불가능하다(DIVERGENCES.md 신규 항목: Runtime.execute()의 push_bar 점진 로드 +
// ctx.security의 lazy-singleton 캐시가 겹쳐, 스크립트의 첫 request.security() 호출 시점(항상 bar 0)
// 에 아직 한 바만 채워진 상태로 집계를 영구 캐싱해버려 이후 모든 바가 오염된 스냅샷을 본다 — 이는
// "htf_idx===0 lookahead 누출"과는 별개의, 훨씬 더 심각한 pine2py 자체 latent 버그다). pine2js는
// Context 생성 시 전체 배열을 이미 쥔 채 1회 정석 집계를 수행하므로(GOAL.md 배치 리플레이 철학)
// 이 latent 버그와 구조적으로 무관 — 전부 hand-verified(런타임은 tests/unit/security.test.ts). ──
describe("CodeGen request.security() (C176 first slice + C177 second slice)", () => {
  it("emits 'rt.security.get($.securityCache[N], $.idx, \"field\", gaps, lookahead)', dropping the symbol/timeframe arguments entirely and defaulting gaps/lookahead to false when omitted", () => {
    const code = codegenSource('x = request.security("", "D", close)');
    expect(code).toBe('var x = rt.security.get($.securityCache[0], $.idx, "close", false, false);');
  });

  it("emits the correct field literal for each BAR_SERIES_NAMES identifier", () => {
    for (const field of ["open", "high", "low", "close", "volume"]) {
      const code = codegenSource(`x = request.security("", "D", ${field})`);
      expect(code).toBe(`var x = rt.security.get($.securityCache[0], $.idx, "${field}", false, false);`);
    }
  });

  it("emits literal true/false for gaps=/lookahead= kwargs (including barmerge.* constants folded at analyze-time)", () => {
    expect(codegenSource('x = request.security("", "D", close, gaps=true)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", true, false);',
    );
    expect(codegenSource('x = request.security("", "D", close, lookahead=true)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", false, true);',
    );
    expect(codegenSource('x = request.security("", "D", close, gaps=true, lookahead=true)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", true, true);',
    );
    expect(codegenSource('x = request.security("", "D", close, gaps=barmerge.gaps_on, lookahead=barmerge.lookahead_off)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", true, false);',
    );
  });

  it("emits identical output for gaps/lookahead passed positionally (C249) as for the equivalent kwargs form", () => {
    expect(codegenSource('x = request.security("", "D", close, true)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", true, false);',
    );
    expect(codegenSource('x = request.security("", "D", close, true, true)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", true, true);',
    );
    expect(codegenSource('x = request.security(syminfo.tickerid, "D", close, barmerge.gaps_off, barmerge.lookahead_off)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", false, false);',
    );
  });

  it("discards ignore_invalid_symbol=/currency= entirely (C376) — output is byte-identical to the call without them", () => {
    const withoutKwargs = codegenSource('x = request.security("", "D", close, gaps=true)');
    const withKwargs = codegenSource(
      'x = request.security("", "D", close, gaps=true, ignore_invalid_symbol=true, currency=currency.USD)',
    );
    expect(withKwargs).toBe(withoutKwargs);
    expect(withKwargs).toBe('var x = rt.security.get($.securityCache[0], $.idx, "close", true, false);');
  });

  it("emits identical output for timeframe.period/main_period as for the equivalent 'D' string literal (C307 — both fold to the same compile-time 'D' constant, so codegen never sees the difference)", () => {
    expect(codegenSource('x = request.security("", timeframe.period, close)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", false, false);',
    );
    expect(codegenSource('x = request.security("", timeframe.main_period, close)')).toBe(
      'var x = rt.security.get($.securityCache[0], $.idx, "close", false, false);',
    );
    const result = transpile('var float x = na\nx := request.security("", timeframe.period, close)');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual(["D"]);
  });

  it("assigns sequential $.securityCache slot indices to multiple call sites in source order", () => {
    const code = codegenSource(['a = request.security("", "D", close)', 'b = request.security("", "60", high)'].join("\n"));
    expect(code).toBe(
      [
        'var a = rt.security.get($.securityCache[0], $.idx, "close", false, false);',
        'var b = rt.security.get($.securityCache[1], $.idx, "high", false, false);',
      ].join("\n"),
    );
  });

  it("end-to-end: pipeline threads securityTfs through to Context, producing na for the still-forming first HTF period and the aggregated value once htf_idx advances", () => {
    // day1=idx0-2, day2=idx3-5, day3=idx6-8, day4=idx9 (tests/unit/security.test.ts와 동일 설계).
    // var로 선언해야 오라클 var-state 스냅샷 채널(var:x)에 잡힌다 — 순수 '=' 로컬은 매 바 JS
    // 지역변수로만 존재해 이 채널에 노출되지 않는다(plot() 테스트가 __obs_x 없이 plots 채널을 쓰는
    // 것과 마찬가지로, request.security는 자체 채널이 없어 var 미러가 필요).
    const source = 'var float x = na\nx := request.security("", "D", close)';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual(["D"]);

    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(bars.map((b) => b["var:x"])).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
  });

  it("end-to-end: lookahead=true drops the htf_idx===0 na exception and returns the still-forming period's full aggregate immediately (C177 second slice)", () => {
    // 동일 데이터셋(tests/unit/security.test.ts와 동일 설계) — lookahead=off라면 idx0-2는 na지만,
    // lookahead=on은 그 예외가 없어 day1의 완성 close=103을 idx0부터 그대로 본다(의도적 미래 누출).
    const source = 'var float x = na\nx := request.security("", "D", close, lookahead=true)';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual(["D"]);

    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(bars.map((b) => b["var:x"])).toEqual([103, 103, 103, 109, 109, 109, 114, 114, 114, 116]);
  });

  it("end-to-end: gaps=true returns na except on the first bar of each new HTF period (lookahead=off, C177 second slice)", () => {
    // 동일 데이터셋 — security.test.ts "gaps=on(lookahead=off)" 유닛 테스트와 동일 기대값
    // (bar_map[idx-1]이 이번 바가 보고할 htf_idx와 같으면 na, security.py:139-143 literal port).
    const source = 'var float x = na\nx := request.security("", "D", close, gaps=true)';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual(["D"]);

    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(bars.map((b) => b["var:x"])).toEqual([NaN, NaN, NaN, NaN, 103, 103, NaN, 109, 109, NaN]);
  });

  it("end-to-end: RunResult is unaffected for a script with no request.security() calls (backward compatible default)", () => {
    const source = "var float acc = 0.0";
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual([]);

    const closeData = [1];
    const data: OHLCVData = { open: closeData, high: closeData, low: closeData, close: closeData, volume: closeData };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:acc"]).toBe(0.0);
  });
});

// ── request.security symbol=/timeframe=/expression= kwargs(C409, wild 47건) — codegen은
// prog.securityCallSlots 등을 CallExpr 노드 자체로 키잉해 인자가 위치/키워드 중 어느 쪽에서
// 왔는지 무관(analyzer/call-expr.ts resolveSecurityLeadArgs 참조, codegen 변경 0줄) — 이 describe는
// 그 계약을 exact-string 동치성으로 고정한다. ──
describe("CodeGen request.security symbol=/timeframe=/expression= kwargs (C409, third slice widening)", () => {
  it("emits byte-identical output for a fully-keyword call vs. the equivalent positional call", () => {
    const positional = codegenSource('x = request.security("", "D", close)');
    const keyword = codegenSource('x = request.security(symbol="", timeframe="D", expression=close)');
    expect(keyword).toBe(positional);
    expect(keyword).toBe('var x = rt.security.get($.securityCache[0], $.idx, "close", false, false);');
  });

  it("emits byte-identical output regardless of kwarg order", () => {
    const a = codegenSource('x = request.security(symbol="", timeframe="D", expression=close)');
    const b = codegenSource('x = request.security(expression=close, symbol="", timeframe="D")');
    expect(b).toBe(a);
  });

  it("emits byte-identical output for a fully-keyword call with trailing lookahead= vs. the equivalent positional+kwarg mix", () => {
    const withLead = codegenSource('x = request.security(symbol="", timeframe="D", expression=close, lookahead=true)');
    const positional = codegenSource('x = request.security("", "D", close, lookahead=true)');
    expect(withLead).toBe(positional);
  });

  it("emits byte-identical output for a mixed form — positional symbol/timeframe + keyword expression", () => {
    const mixed = codegenSource('x = request.security("", "D", expression=close)');
    const positional = codegenSource('x = request.security("", "D", close)');
    expect(mixed).toBe(positional);
  });

  it("emits the same ta.* state-slot codegen for a fully-keyword expression call site as the positional form", () => {
    const keyword = codegenSource('x = request.security(symbol="", timeframe="D", expression=ta.sma(close, 5))');
    const positional = codegenSource('x = request.security("", "D", ta.sma(close, 5))');
    expect(keyword).toBe(positional);
  });
});

// ── request.security tf 상수 전파(C366, wild 1위 클러스터) — `tf = input.timeframe("60")` 후
// tf 인자로 전달하는 관용구. 분석기 상수 폴딩은 analyzer.test.ts C366 describe가 검증하고, 여기는
// (1) input 출처 상수의 프리앰블 오버라이드 가드 exact-string, (2) 리터럴 출처의 가드 비방출,
// (3) hand-verified E2E(리터럴 폼과의 실행값 완전 동등 + 오버라이드 시 즉시 throw)를 검증한다.
// request.security는 오라클 구조적 불가(MEMORY.md C176)라 전부 hand-verified. ──
describe("CodeGen request.security tf 상수 전파 (C366)", () => {
  it("emits a ctx-once preamble guard re-evaluating the input call for an input-sourced tf const", () => {
    const code = codegenSource('tf = input.timeframe("60", "Res")\nx = request.security("", tf, close)');
    expect(code).toContain(
      'if (rt.input.timeframe($.inputs, "60", "Res") !== "60") throw new Error(',
    );
    // 가드는 프리앰블(return function 위)에 있어야 한다 — 원본 2-layer 출력에서 위치로 검증.
    const raw = generateCode(analyze(parse('tf = input.timeframe("60", "Res")\nx = request.security("", tf, close)')));
    const guardIdx = raw.indexOf("rt.input.timeframe($.inputs");
    const barFnIdx = raw.indexOf("return function () {");
    expect(guardIdx).toBeGreaterThanOrEqual(0);
    expect(guardIdx).toBeLessThan(barFnIdx);
  });

  it("emits no guard for a literal-sourced or timeframe.period-sourced tf const (런타임에 변할 수 없음)", () => {
    const litCode = codegenSource('tf = "60"\nx = request.security("", tf, close)');
    expect(litCode).not.toContain("throw new Error");
    const propCode = codegenSource('tf = timeframe.period\nx = request.security("", tf, close)');
    expect(propCode).not.toContain("throw new Error");
  });

  it("emits the guard once per input name even with multiple consuming call sites", () => {
    const code = codegenSource(
      ['tf = input.timeframe("60", "Res")', 'a = request.security("", tf, close)', 'b = request.security("", tf, high)'].join("\n"),
    );
    const matches = code.split('rt.input.timeframe($.inputs, "60", "Res") !== "60"').length - 1;
    expect(matches).toBe(1);
  });

  it("lowers the security call itself identically to the literal form (상수 전파는 securityTfs에만 반영, per-bar 코드 불변)", () => {
    const constForm = codegenSource('tf = input.timeframe("D")\nx = request.security("", tf, close)');
    const litForm = codegenSource('x = request.security("", "D", close)');
    // 리터럴 폼의 유일한 문장(rt.security.get 호출)이 상수 폼에도 그대로 있어야 한다.
    expect(constForm).toContain(litForm.split("\n").find((l) => l.includes("rt.security.get"))!);
  });

  it("hand-verified E2E: input-const tf produces bar-for-bar identical output to the literal tf form", () => {
    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const runOf = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      expect(result.securityTfs).toEqual(["D"]);
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).bars.map((b) => b["var:x"]);
    };
    const constBars = runOf('tf = input.timeframe("D", "Res")\nvar float x = na\nx := request.security("", tf, close)');
    const litBars = runOf('var float x = na\nx := request.security("", "D", close)');
    // 기존 end-to-end 테스트(C176)와 동일 데이터셋의 검증된 기대값 — 두 폼 모두 정확히 일치해야 한다.
    expect(litBars).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
    expect(constBars).toEqual(litBars);
  });

  it("hand-verified E2E: overriding the tf input with the SAME value runs, a DIFFERENT value throws at ctx setup", () => {
    const data: OHLCVData = {
      open: [100, 102, 101],
      high: [103, 105, 102],
      low: [99, 100, 100],
      close: [102, 101, 103],
      volume: [1000, 1100, 1050],
      time: [1704067200000, 1704096000000, 1704124800000],
    };
    const source = 'tf = input.timeframe("D", "Res")\nvar float x = na\nx := request.security("", tf, close)';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const runWith = (inputs: Record<string, unknown>) =>
      run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        inputs,
        result.plotTitles,
        result.securityTfs,
      );
    expect(() => runWith({})).not.toThrow();
    expect(() => runWith({ Res: "D" })).not.toThrow();
    // HTF 집계 캐시는 트랜스파일 시점 "D"로 이미 고정 — 다른 tf 오버라이드는 조용한 오답 대신 즉시 throw.
    expect(() => runWith({ Res: "60" })).toThrow(/timeframe 입력 'tf'|고정됨/);
  });
});

// ── request.security 배치31 슬라이스 (a, C597) — tf 인자가 "직접" input.*(...) 콜(변수 경유 아님)이라
// 컴파일타임 리터럴로 안 접힐 때, 하드 에러 대신 codegen 프리앰블(바 루프 시작 전, ctx당 1회)에서 그
// 식을 evaluate해 $.rebuildSecurityCache(slot, tf)로 HTF 캐시를 런타임 1회 확정한다(analyzer.ts
// securityRuntimeTfSlots/runtime/context.ts rebuildSecurityCache 참조). 분석기 등록은 analyzer.test.ts
// C597 describe가 검증하고, 여기는 (1) 프리앰블 방출 형태, (2) 리터럴 폼과의 실행값 완전 동등(ok-Set
// 등가성), (3) input 오버라이드가 C366 가드(불일치 시 throw)와 달리 실제로 반영됨을 검증한다.
// request.security는 오라클 구조적 불가(MEMORY.md C176)라 전부 hand-verified.
describe("CodeGen request.security tf 배치31 런타임 tf (C597, direct input.*(...) call)", () => {
  it("emits a ctx-once preamble line rebuilding the security cache from the evaluated input call, before the bar loop", () => {
    const raw = generateCode(analyze(parse('x = request.security("", input.timeframe("60", "Res"), close)')));
    const rebuildIdx = raw.indexOf('$.rebuildSecurityCache(0, rt.input.timeframe($.inputs, "60", "Res"));');
    const barFnIdx = raw.indexOf("return function () {");
    expect(rebuildIdx).toBeGreaterThanOrEqual(0);
    expect(rebuildIdx).toBeLessThan(barFnIdx);
  });

  it("lowers the security call itself identically to the literal form (read-side codegen is untouched by the runtime-tf path)", () => {
    const runtimeForm = codegenSource('x = request.security("", input.timeframe("D"), close)');
    const litForm = codegenSource('x = request.security("", "D", close)');
    expect(runtimeForm).toContain(litForm.split("\n").find((l) => l.includes("rt.security.get"))!);
  });

  it("emits no securityTfConstGuards throw guard for the direct-call path (C366 가드는 변수 경유 상수 전파 전용, 이 경로는 항상 재평가라 불일치 자체가 없음)", () => {
    const code = codegenSource('x = request.security("", input.timeframe("60"), close)');
    expect(code).not.toContain("throw new Error");
  });

  it("hand-verified E2E: direct input.timeframe(...) tf produces bar-for-bar identical output to the literal tf form", () => {
    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const runOf = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).bars.map((b) => b["var:x"]);
    };
    const runtimeBars = runOf('var float x = na\nx := request.security("", input.timeframe("D"), close)');
    const litBars = runOf('var float x = na\nx := request.security("", "D", close)');
    // C366 describe의 동일 데이터셋 검증된 기대값과 바이트 단위로 동일해야 한다(literal/const-propagated/
    // direct-runtime 세 경로 모두 같은 HTF 캐시로 수렴).
    expect(litBars).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
    expect(runtimeBars).toEqual(litBars);
  });

  it("hand-verified E2E: unlike the C366 const-propagation guard (which throws on override mismatch), the direct-call path actually HONORS an input override (re-evaluated every ctx setup, not frozen at transpile time)", () => {
    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const source = 'var float x = na\nx := request.security("", input.timeframe("D", "Res"), close)';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const runWith = (inputs: Record<string, unknown>) =>
      run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        inputs,
        result.plotTitles,
        result.securityTfs,
      ).bars.map((b) => b["var:x"]);
    const defaultBars = runWith({});
    // "60"(분단위) 오버라이드는 naive-count 폴백(ratio=60) 집계로 떨어져 "D" 집계와 값이 달라야
    // 한다 — throw 없이 실제로 다른 HTF 캐시가 재빌드됐다는 직접 증거.
    const overriddenBars = runWith({ Res: "60" });
    expect(() => runWith({ Res: "60" })).not.toThrow();
    expect(defaultBars).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
    expect(overriddenBars).not.toEqual(defaultBars);
  });
});

// ── request.security 배치31 슬라이스 (a)-2 (C598) — 변수 경유("재대입 0회")/삼항/문자열 ==·!=
// 비교 tf를 정의식 재귀 치환으로 프리앰블 자기완결 트리(Identifier 전부 소거, 리프는 리터럴/
// 방출-슬롯 리터럴 input.* 콜/timeframe.* 폴딩)로 빌드해 C597의 rebuildSecurityCache 경로에
// 태운다. 분석기 등록/거부 경계는 analyzer.test.ts C598 describe가 검증하고, 여기는 (1) 치환
// 트리의 방출 형태(합성 TernaryOp/BinOp가 네이티브 (c?a:b)/===로 나오는지), (2) freeze 가드
// 롤백(실패한 폴딩 시도의 가드가 안 남는지), (3) 리터럴 폼과의 실행값 완전 동등 + branch/cond
// 양쪽 input 오버라이드가 실제로 반영되는지(hand-verified — request.security는 오라클 구조적
// 불가, MEMORY.md C176)를 계약으로 굳힌다. ──
describe("CodeGen request.security tf 배치31 (a)-2 런타임 tf (C598, 변수 경유/삼항/문자열 비교)", () => {
  const TERN_SOURCE = [
    'useX = input.bool(true, "UseX")',
    'tf = useX ? input.timeframe("60", "Alt") : "D"',
    "var float x = na",
    'x := request.security("", tf, close)',
  ].join("\n");
  const CMP_SOURCE = [
    'manual = "60"',
    'tf = input.string("Auto", "Mode") == "Auto" ? "D" : manual',
    "var float x = na",
    'x := request.security("", tf, close)',
  ].join("\n");
  const DATA: OHLCVData = {
    open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
    high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
    low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
    close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
    volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
    time: [
      1704067200000, 1704096000000, 1704124800000,
      1704153600000, 1704182400000, 1704211200000,
      1704240000000, 1704268800000, 1704297600000,
      1704326400000,
    ],
  };
  const runBars = (source: string, inputs: Record<string, unknown>): number[] => {
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) throw new Error("unreachable");
    return run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      DATA,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      inputs,
      result.plotTitles,
      result.securityTfs,
    ).bars.map((b) => b["var:x"]!);
  };

  it("emits the substituted self-contained ternary preamble line (Identifier 전부 소거, 네이티브 (c?a:b)) before the bar loop", () => {
    const raw = generateCode(analyze(parse(TERN_SOURCE)));
    const rebuildIdx = raw.indexOf(
      '$.rebuildSecurityCache(0, (rt.input.bool($.inputs, true, "UseX") ? rt.input.timeframe($.inputs, "60", "Alt") : "D"));',
    );
    const barFnIdx = raw.indexOf("return function () {");
    expect(rebuildIdx).toBeGreaterThanOrEqual(0);
    expect(rebuildIdx).toBeLessThan(barFnIdx);
  });

  it("emits the ==/!= comparison cond as native strict equality with substituted leaves (합성 BinOp — genEquality 경로)", () => {
    const raw = generateCode(analyze(parse(CMP_SOURCE)));
    expect(raw).toContain(
      '$.rebuildSecurityCache(0, (rt.pineEq(rt.input.string($.inputs, "Auto", "Mode"), "Auto") ? "D" : "60"));',
    );
  });

  it("emits no freeze guard for the absorbed call site (실패한 폴딩 시도의 cond 가드가 롤백됨 — throw 라인 0)", () => {
    const code = codegenSource(TERN_SOURCE);
    expect(code).not.toContain("throw new Error");
  });

  it("hand-verified E2E: variable-routed ternary tf equals the literal-tf run on the default branch (60분 집계)", () => {
    const dynBars = runBars(TERN_SOURCE, {});
    const litBars = runBars('var float x = na\nx := request.security("", "60", close)', {});
    expect(dynBars).toEqual(litBars);
  });

  it("hand-verified E2E: overriding the BRANCH input (Alt='D') rebuilds the cache — equals the literal 'D' run byte-for-byte", () => {
    const overridden = runBars(TERN_SOURCE, { Alt: "D" });
    // C366/C597 describe들이 같은 데이터셋으로 검증해 둔 "D" 집계 기대값과 동일해야 한다.
    expect(overridden).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
    expect(overridden).toEqual(runBars('var float x = na\nx := request.security("", "D", close)', {}));
  });

  it("hand-verified E2E: overriding the COND input (UseX=false)도 throw 없이 반영된다 (freeze 가드 롤백의 실행 증거)", () => {
    const overridden = runBars(TERN_SOURCE, { UseX: false });
    expect(overridden).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
  });

  it("hand-verified E2E: comparison-cond form — default('Auto'→D)과 override(Mode≠'Auto'→60) 모두 리터럴 폼과 완전 동등", () => {
    expect(runBars(CMP_SOURCE, {})).toEqual([NaN, NaN, NaN, 103, 103, 103, 109, 109, 109, 114]);
    expect(runBars(CMP_SOURCE, { Mode: "Manual" })).toEqual(
      runBars('var float x = na\nx := request.security("", "60", close)', {}),
    );
  });
});

// ── request.security 배치31 슬라이스 (b)-1 (C599) — 런타임 tf 슬롯의 expression/passthrough
// 콜사이트 확장. 분석기 등록/거부 경계는 analyzer.test.ts C599 describe가 검증하고, 여기는 (1)
// rebuild 방출이 __secExpr 프리패스보다 앞서는 순서 계약, (2) 리터럴 폼과의 실행값 완전 동등 +
// input 오버라이드 반영, (3) passthrough의 tf 완전 discard 실행 증거를 hand-verified로 굳힌다
// (request.security는 오라클 구조적 불가, MEMORY.md C176). ──
describe("CodeGen request.security tf 배치31 (b)-1 런타임 tf 확장 (C599, expression/passthrough 콜사이트)", () => {
  const RT_TF = ['u = input.bool(true, "U")', 'tf = u ? input.timeframe("60", "A") : "D"'].join("\n");
  const DATA: OHLCVData = {
    open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
    high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
    low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
    close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
    volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
    time: [
      1704067200000, 1704096000000, 1704124800000,
      1704153600000, 1704182400000, 1704211200000,
      1704240000000, 1704268800000, 1704297600000,
      1704326400000,
    ],
  };
  const runVars = (source: string, inputs: Record<string, unknown>, names: string[]): number[][] => {
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) throw new Error("unreachable");
    const bars = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      DATA,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      inputs,
      result.plotTitles,
      result.securityTfs,
    ).bars;
    return names.map((n) => bars.map((b) => b[`var:${n}`]!));
  };
  const expectSame = (a: number[][], b: number[][]): void => {
    expect(a.length).toBe(b.length);
    for (let i = 0; i < a.length; i++) {
      expect(a[i]!.map((v) => (Number.isNaN(v) ? "NaN" : v))).toEqual(b[i]!.map((v) => (Number.isNaN(v) ? "NaN" : v)));
    }
  };

  it("emits the rebuildSecurityCache line BEFORE the __secExpr prepass function (프리패스가 항상 최종 캐시 위에서 도는 순서 계약)", () => {
    const raw = generateCode(analyze(parse([RT_TF, "var float x = na", 'x := request.security("", tf, ta.sma(close, 5))'].join("\n"))));
    const rebuildIdx = raw.indexOf("$.rebuildSecurityCache(0,");
    const prepassIdx = raw.indexOf("function __secExpr0()");
    expect(rebuildIdx).toBeGreaterThanOrEqual(0);
    expect(prepassIdx).toBeGreaterThan(rebuildIdx);
  });

  it("hand-verified E2E: runtime-tf ta.sma expression equals the literal-tf run bar-for-bar (60분 집계)", () => {
    const dyn = runVars([RT_TF, "var float x = na", 'x := request.security("", tf, ta.sma(close, 3))'].join("\n"), {}, ["x"]);
    const lit = runVars('var float x = na\nx := request.security("", "60", ta.sma(close, 3))', {}, ["x"]);
    expectSame(dyn, lit);
  });

  it("hand-verified E2E: overriding the BRANCH input (A='D') rebuilds the expression cache — equals the literal 'D' run", () => {
    const dyn = runVars([RT_TF, "var float x = na", 'x := request.security("", tf, ta.sma(close, 3))'].join("\n"), { A: "D" }, ["x"]);
    const lit = runVars('var float x = na\nx := request.security("", "D", ta.sma(close, 3))', {}, ["x"]);
    expectSame(dyn, lit);
  });

  it("hand-verified E2E: runtime-tf history expression (close[1]) equals the literal-tf run", () => {
    const dyn = runVars([RT_TF, "var float x = na", 'x := request.security("", tf, close[1])'].join("\n"), {}, ["x"]);
    const lit = runVars('var float x = na\nx := request.security("", "60", close[1])', {}, ["x"]);
    expectSame(dyn, lit);
  });

  it("hand-verified E2E: runtime-tf mixed tuple ([bare, ta.ema expr]) equals the literal-tf run on both elements", () => {
    const TUP = ['[a, b] = request.security("", tf, [close, ta.ema(close, 2)])', "var float xa = na", "var float xb = na", "xa := a", "xb := b"];
    const dyn = runVars([RT_TF, ...TUP].join("\n"), {}, ["xa", "xb"]);
    const lit = runVars(
      ['[a, b] = request.security("", "60", [close, ta.ema(close, 2)])', "var float xa = na", "var float xb = na", "xa := a", "xb := b"].join("\n"),
      {},
      ["xa", "xb"],
    );
    expectSame(dyn, lit);
  });

  it("hand-verified E2E: scalar bare-UDF passthrough with a fully dynamic tf equals the direct UDF call (tf 완전 discard의 실행 증거)", () => {
    const F = ["g(x) =>", "    x * 2 + 1", 'tfv = "60"', 'tfv := close > open ? "240" : "60"'];
    const dyn = runVars([...F, "var float x = na", 'x := request.security("", tfv, g(close))'].join("\n"), {}, ["x"]);
    const direct = runVars([...F, "var float x = na", "x := g(close)"].join("\n"), {}, ["x"]);
    expectSame(dyn, direct);
  });
});

// ── request.security 배치31 슬라이스 (b)-2 (C600) — tf-param(래퍼 매개변수) 콜사이트별
// 리터럴×런타임 혼합. 분석기 등록/거부/가드 경계는 analyzer.test.ts C600 describe가 검증하고,
// 여기는 (1) 런타임 사이트 슬롯만 rebuildSecurityCache가 방출되는 프리앰블 형태, (2) 리터럴 폼과의
// 실행값 완전 동등(bare/exprMatch/pending secParam), (3) 사이트 단위 가드 정밀성의 실행 증거 —
// 런타임 사이트 input 오버라이드는 반영(no throw), 리터럴 폴딩 사이트 오버라이드는 기존 C366
// freeze throw 유지 — 를 hand-verified로 굳힌다(request.security는 오라클 구조적 불가, C176). ──
describe("CodeGen request.security tf 배치31 (b)-2 (C600, tf-param 콜사이트별 리터럴×런타임 혼합)", () => {
  const DATA: OHLCVData = {
    open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
    high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
    low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
    close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
    volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
    time: [
      1704067200000, 1704096000000, 1704124800000,
      1704153600000, 1704182400000, 1704211200000,
      1704240000000, 1704268800000, 1704297600000,
      1704326400000,
    ],
  };
  const runVars = (source: string, inputs: Record<string, unknown>, names: string[]): number[][] => {
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) throw new Error("unreachable");
    const bars = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      DATA,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      inputs,
      result.plotTitles,
      result.securityTfs,
    ).bars;
    return names.map((n) => bars.map((b) => b[`var:${n}`]!));
  };
  const expectSame = (a: number[][], b: number[][]): void => {
    expect(a.length).toBe(b.length);
    for (let i = 0; i < a.length; i++) {
      expect(a[i]!.map((v) => (Number.isNaN(v) ? "NaN" : v))).toEqual(b[i]!.map((v) => (Number.isNaN(v) ? "NaN" : v)));
    }
  };
  const MIXED_BARE = [
    "getS(tf) =>",
    '    request.security("", tf, close)',
    "var float a = na",
    "var float b = na",
    'a := getS("D")',
    'b := getS(input.timeframe("60", "Res"))',
  ].join("\n");
  const LIT_BARE = [
    "var float a = na",
    "var float b = na",
    'a := request.security("", "D", close)',
    'b := request.security("", "60", close)',
  ].join("\n");

  it("emits exactly one rebuildSecurityCache line — the runtime site's slot (1) only, before the bar loop; the literal site slot stays constructor-built", () => {
    const raw = generateCode(analyze(parse(MIXED_BARE)));
    const rebuildIdx = raw.indexOf('$.rebuildSecurityCache(1, rt.input.timeframe($.inputs, "60", "Res"));');
    const barFnIdx = raw.indexOf("return function () {");
    expect(rebuildIdx).toBeGreaterThanOrEqual(0);
    expect(rebuildIdx).toBeLessThan(barFnIdx);
    expect(raw).not.toContain("$.rebuildSecurityCache(0,");
  });

  it("hand-verified E2E: mixed literal(D)+runtime(60) sites equal the two-literal reference bar-for-bar on both slots", () => {
    expectSame(runVars(MIXED_BARE, {}, ["a", "b"]), runVars(LIT_BARE, {}, ["a", "b"]));
  });

  it("hand-verified E2E: overriding the runtime site's input (Res='D') is HONORED without any freeze throw — both sites then read the 'D' aggregation", () => {
    const [a, b] = runVars(MIXED_BARE, { Res: "D" }, ["a", "b"]);
    expectSame([b!], [a!]);
  });

  it("hand-verified E2E: site-level guard precision — the literal-folded input-const site still freezes (override throws) while the runtime site's input override is honored", () => {
    const SRC = [
      'cres = input.timeframe("60", "CRes")',
      "tfv = cres",
      'dres = input.bool(true, "U") ? input.timeframe("240", "DRes") : "D"',
      "getS(tf) =>",
      '    request.security("", tf, close)',
      "var float a = na",
      "var float b = na",
      "a := getS(tfv)",
      "b := getS(dres)",
    ].join("\n");
    expect(() => runVars(SRC, { DRes: "D" }, ["a", "b"])).not.toThrow();
    expect(() => runVars(SRC, { CRes: "D" }, ["a", "b"])).toThrow(/트랜스파일 시점에 '60'로 고정됨/);
  });

  it("hand-verified E2E: mixed sites on an exprMatch (ta.sma) call site equal the two-literal reference (per-site prepasses on rebuilt caches)", () => {
    const dyn = runVars(
      [
        "getS(tf) =>",
        '    request.security("", tf, ta.sma(close, 3))',
        "var float a = na",
        "var float b = na",
        'a := getS("D")',
        'b := getS(input.timeframe("60", "Res"))',
      ].join("\n"),
      {},
      ["a", "b"],
    );
    const lit = runVars(
      [
        "var float a = na",
        "var float b = na",
        'a := request.security("", "D", ta.sma(close, 3))',
        'b := request.security("", "60", ta.sma(close, 3))',
      ].join("\n"),
      {},
      ["a", "b"],
    );
    expectSame(dyn, lit);
  });

  it("hand-verified E2E: mixed sites through the pending secParamMultiSiteGeneric path (expression references a param) equal the two-literal reference", () => {
    const dyn = runVars(
      [
        "getS(tf, src) =>",
        '    request.security("", tf, ta.sma(src, 3))',
        "var float a = na",
        "var float b = na",
        'a := getS("D", close)',
        'b := getS(input.timeframe("60", "Res"), open)',
      ].join("\n"),
      {},
      ["a", "b"],
    );
    const lit = runVars(
      [
        "var float a = na",
        "var float b = na",
        'a := request.security("", "D", ta.sma(close, 3))',
        'b := request.security("", "60", ta.sma(open, 3))',
      ].join("\n"),
      {},
      ["a", "b"],
    );
    expectSame(dyn, lit);
  });

  it("hand-verified E2E: mixed sites on a tuple call site equal the two-literal reference on all elements", () => {
    const dyn = runVars(
      [
        "getS(tf) =>",
        '    [o, s] = request.security("", tf, [open, ta.ema(close, 2)])',
        "    o + s",
        "var float a = na",
        "var float b = na",
        'a := getS("D")',
        'b := getS(input.timeframe("60", "Res"))',
      ].join("\n"),
      {},
      ["a", "b"],
    );
    const lit = runVars(
      [
        'litOf(tf) =>\n    [o, s] = request.security("", tf, [open, ta.ema(close, 2)])\n    o + s',
        "var float a = na",
        "var float b = na",
        'a := litOf("D")',
        'b := litOf("60")',
      ].join("\n"),
      {},
      ["a", "b"],
    );
    expectSame(dyn, lit);
  });
});

// ── C730 (배치37 (2) 3차): tf 런타임 트리 str.tostring 조합자 방출 — 합성 CallExpr가
// builtinCalls("tostring")+tostringIntArgCalls(isInt=true)로 등록돼 프리앰블 rebuildSecurityCache에
// rt.tostring(<Identifier-소거 숫자 서브트리>, undefined, true)로 방출되는지, 삼항 조건 컴파일타임
// 폴딩 프루닝('###M' auto-HTF 관용구)이 죽은 분기 없이 선택 분기만 싣는지 검증. 분석기 수용/거부
// 경계는 analyzer.test.ts C730 describe가 검증한다. ──
describe("CodeGen request.security tf str.tostring 조합자 (C730, 배치37 (2))", () => {
  it("emits rt.tostring(<input leaf>, undefined, true) in the preamble rebuild line (isInt=true — '120.0' 오염 방지)", () => {
    const raw = generateCode(
      analyze(
        parse(
          ['mins = input.int(120, "M")', "tfStr = str.tostring(mins)", "var float x = na", 'x := request.security("", tfStr, close)'].join(
            "\n",
          ),
        ),
      ),
    );
    expect(raw).toContain('$.rebuildSecurityCache(0, rt.tostring(rt.input.int($.inputs, 120, "M"), undefined, true));');
  });

  it("emits the pruned '###D' branch only (is* 삼항 폴딩 — 죽은 '###M' 분기가 rebuild 라인에 없음)", () => {
    const raw = generateCode(
      analyze(
        parse(
          [
            'mult = input.int(8, "Mult")',
            "tfStr = timeframe.ismonthly ? str.tostring(timeframe.multiplier * mult, '###M') : str.tostring(timeframe.multiplier * mult, '###D')",
            "var float x = na",
            'x := request.security("", tfStr, close)',
          ].join("\n"),
        ),
      ),
    );
    expect(raw).toContain('$.rebuildSecurityCache(0, rt.tostring((1 * rt.input.int($.inputs, 8, "Mult")), "###D", true));');
    const rebuildLine = raw.split("\n").find((l) => l.includes("rebuildSecurityCache"))!;
    expect(rebuildLine).not.toContain("###M");
  });

  it("honors a runtime input override through the tostring tree (프리앰블 런타임 평가 — 폴딩이었다면 불가능한 성질)", () => {
    const DATA: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
      time: [
        1704067200000, 1704096000000, 1704124800000,
        1704153600000, 1704182400000, 1704211200000,
        1704240000000, 1704268800000, 1704297600000,
        1704326400000,
      ],
    };
    const runTf = (source: string, inputs: Record<string, unknown>): number[] => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(result.code, result.varSlots, result.taSlotCount, DATA, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize, inputs, result.plotTitles, result.securityTfs).bars.map((b) => b["var:x"]!);
    };
    const SOURCE = ['mins = input.int(60, "M")', "tfStr = str.tostring(mins)", "var float x = na", 'x := request.security("", tfStr, close)'].join(
      "\n",
    );
    // 기본값 60 → 리터럴 "60" 런과 완전 동등, 오버라이드 1440 → 리터럴 "1440" 런과 완전 동등
    // (그리고 두 집계는 이 데이터셋에서 서로 다르다 — C598 describe의 "60" vs "D" 대비와 동일).
    const litOf = (tf: string) => runTf(`var float x = na\nx := request.security("", "${tf}", close)`, {});
    expect(runTf(SOURCE, {})).toEqual(litOf("60"));
    const overridden = runTf(SOURCE, { M: 1440 });
    expect(overridden).toEqual(litOf("1440"));
    expect(overridden).not.toEqual(litOf("60"));
  });
});

// ── for-in(array) 루프 변수의 본문 직속 '=' 재선언(C599 발견 기존 버그) — `for tf in arr` +
// `tf = str.trim(tf)`가 같은 블록 `let` 이중 선언 invalid JS(SyntaxError)를 방출하던 것을
// genBlock seedNames(C319 매개변수 seedNames의 for-in판)로 맨몸 재대입으로 내린다. pine2py는
// Python 평면 재대입이라 시맨틱 동일(루프 헤드가 매 반복 __forInArr[idx]를 다시 읽어 다음 반복
// 오염 없음). wild 96697dead2f9 실측 invalid_js로 발견. ──
describe("CodeGen for-in loop variable body '=' redeclaration (C599 버그 수정)", () => {
  const SRC = ["var float acc = 0.0", "arr = array.from(1.0, 2.0)", "for v in arr", "    v = v + 1.0", "    acc := acc + v"].join("\n");

  it("emits valid JS (new Function이 SyntaxError 없이 컴파일) with a bare reassignment instead of a second let", () => {
    const result = transpile(SRC);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(() => new Function("$", "rt", result.code)).not.toThrow();
    expect(result.code).toContain("v = (v + 1.0);");
    expect(result.code).not.toContain("let v = (v + 1.0);");
  });

  it("hand-verified E2E: rebound loop variable accumulates the incremented values ((1+1)+(2+1)=5 매 바)", () => {
    const result = transpile(SRC);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const data: OHLCVData = {
      open: [100, 102],
      high: [103, 105],
      low: [99, 100],
      close: [102, 101],
      volume: [1000, 1100],
      time: [1704067200000, 1704096000000],
    };
    const bars = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount,
      result.historySlotCount, result.taScratchSize, {}, result.plotTitles, result.securityTfs).bars;
    expect(bars.map((b) => b["var:acc"])).toEqual([5, 10]);
  });

  it("keeps the legal shadow `let` for a deeper nested block '=' (다른 스코프 — seedNames는 본문 직속만 대상)", () => {
    const NESTED = ["var float acc = 0.0", "arr = array.from(1.0, 2.0)", "for v in arr", "    if v > 1.0", "        v2 = v + 10.0", "        acc := acc + v2"].join("\n");
    const result = transpile(NESTED);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(() => new Function("$", "rt", result.code)).not.toThrow();
  });
});

// ── request.security tf 삼항 조건 UDF 콜 폴딩(C513)의 input.bool 가드 — 분석기 폴딩은
// analyzer.test.ts C513 describe가 검증하고, 여기는 boolean 리터럴 가드의 방출 형태(JSON.stringify가
// true/false를 그대로 내는지)와 hand-verified E2E(오버라이드 불일치 시 즉시 throw)만 계약으로 굳힌다.
// request.security는 오라클 구조적 불가(MEMORY.md C176)라 hand-verified. ──
describe("CodeGen request.security tf 조건 input.bool 가드 (C513)", () => {
  const SOURCE = [
    'en = input.bool(true, "UseHTF")',
    "gate(e, tf) => e and timeframe.in_seconds() <= timeframe.in_seconds(tf)",
    'var float x = na',
    'x := request.security("", gate(en, "D") ? "D" : "W", close)',
  ].join("\n");

  it("emits a strict !== true preamble guard for the folded input.bool constant", () => {
    const code = codegenSource(SOURCE);
    expect(code).toContain('if (rt.input.bool($.inputs, true, "UseHTF") !== true) throw new Error(');
  });

  it("hand-verified E2E: same-value bool override runs, different value throws at ctx setup", () => {
    const data: OHLCVData = {
      open: [100, 102, 101],
      high: [103, 105, 102],
      low: [99, 100, 100],
      close: [102, 101, 103],
      volume: [1000, 1100, 1050],
      time: [1704067200000, 1704096000000, 1704124800000],
    };
    const result = transpile(SOURCE);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const runWith = (inputs: Record<string, unknown>) =>
      run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        inputs,
        result.plotTitles,
        result.securityTfs,
      );
    expect(() => runWith({})).not.toThrow();
    expect(() => runWith({ UseHTF: true })).not.toThrow();
    expect(() => runWith({ UseHTF: false })).toThrow(/timeframe 입력 'en'|고정됨/);
  });
});

// ── request.security tf 삼항 조건 bare input(bool) 가드 (C537) — 분석기 폴딩은 analyzer.test.ts
// C537 describe가 검증하고, 여기는 bare input(rt.input.any 방출)의 가드 exact-string과
