// ── C532: distinct-tf × 튜플 — C529 __secIdx 연속 슬롯 블록의 튜플판. multiSite면 genCallExpr의
// securityTupleCall 분기가 bare 공유 슬롯과 expr 필드 슬롯 양쪽에 __secIdx를 더해 읽고, expr 필드
// 프리패스는 사이트별 슬롯으로 __secExpr{slot}이 독립 방출된다(securityParamExprPrepasses 재사용 —
// generateSecurityExprPreamble 변경 0줄, analyzer.test.ts C532 블록 참조). ──
describe("CodeGen request.security distinct-tf tuple slot blocks (C532)", () => {
  it("emits __secIdx-relative securityCache reads inside the taScratch comma-expression + ordinal literals at call sites", () => {
    const code = codegenSource(
      'f(tf) =>\n    request.security(syminfo.tickerid, tf, [close, open])\n[a, b] = f("60")\n[c, d] = f("240")',
    );
    expect(code).toContain("function f(__slotBase, __secIdx, tf) {");
    expect(code).toContain('($.taScratch[0] = rt.security.get($.securityCache[0 + __secIdx], $.idx, "close", false, false), $.taScratch[1] = rt.security.get($.securityCache[0 + __secIdx], $.idx, "open", false, false));');
    expect(code).toContain("return [$.taScratch[0], $.taScratch[1]];");
    expect(code).toContain('var [a, b] = f(0, 0, "60");');
    expect(code).toContain('var [c, d] = f(0, 1, "240");');
  });

  it("emits one __secExpr prepass per (expr element × call site) at block-relative slots and reads them via base+__secIdx getFromArray", () => {
    const code = codegenSource(
      'f(tf) =>\n    request.security(syminfo.tickerid, tf, [close, high - low])\n[a, b] = f("60")\n[c, d] = f("240")',
    );
    // bare 공유 블록 [0..1] + expr 원소 블록 [2..3] — 프리패스는 사이트별 슬롯으로 독립 방출.
    expect(code).toContain("function __secExpr2()");
    expect(code).toContain("function __secExpr3()");
    expect(code).toContain("rt.security.getFromArray($.securityExprCache[2 + __secIdx], $.securityCache[2 + __secIdx], $.idx, false, false)");
    expect(code).toContain('rt.security.get($.securityCache[0 + __secIdx], $.idx, "close", false, false)');
  });

  it("hand-verified E2E: distinct-tf tuple wrapper values equal direct fixed-tf tuple destructures (bare / expr+history / 3-site input.timeframe vars / lookahead kwarg)", () => {
    // 20바, 8시간 간격(3바 = 1일) — "D"와 "480"이 서로 다른 집계를 내는 데이터(C529/C530 E2E와 동일).
    const bases = Array.from({ length: 20 }, (_, i) => 100 + Math.sin(i * 1.3) * 10 + i * 0.5);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b) => b + 1),
      volume: bases.map((_, i) => 1000 + i * 7),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const cases: [string, string][] = [
      [
        [
          "f(tf) =>",
          "    request.security(syminfo.tickerid, tf, [close, open])",
          '[a, b] = f("D")',
          '[c, d] = f("480")',
          "plot(a)",
          "plot(b)",
          "plot(c)",
          "plot(d)",
        ].join("\n"),
        [
          '[a, b] = request.security(syminfo.tickerid, "D", [close, open])',
          '[c, d] = request.security(syminfo.tickerid, "480", [close, open])',
          "plot(a)",
          "plot(b)",
          "plot(c)",
          "plot(d)",
        ].join("\n"),
      ],
      [
        [
          "f(tf) =>",
          "    [o, r] = request.security(syminfo.tickerid, tf, [open, (high - low) + close[1]])",
          '[a, b] = f("D")',
          '[c, d] = f("480")',
          "plot(a)",
          "plot(b)",
          "plot(c)",
          "plot(d)",
        ].join("\n"),
        [
          '[a, b] = request.security(syminfo.tickerid, "D", [open, (high - low) + close[1]])',
          '[c, d] = request.security(syminfo.tickerid, "480", [open, (high - low) + close[1]])',
          "plot(a)",
          "plot(b)",
          "plot(c)",
          "plot(d)",
        ].join("\n"),
      ],
      [
        [
          'tf1 = input.timeframe("D")',
          'tf2 = input.timeframe("480")',
          'tf3 = input.timeframe("960")',
          "f(tf) =>",
          "    request.security(syminfo.tickerid, tf, [close, volume])",
          "[a, b] = f(tf1)",
          "[c, d] = f(tf2)",
          "[e, g] = f(tf3)",
          "plot(a + c + e)",
          "plot(b + d + g)",
        ].join("\n"),
        [
          '[a, b] = request.security(syminfo.tickerid, "D", [close, volume])',
          '[c, d] = request.security(syminfo.tickerid, "480", [close, volume])',
          '[e, g] = request.security(syminfo.tickerid, "960", [close, volume])',
          "plot(a + c + e)",
          "plot(b + d + g)",
        ].join("\n"),
      ],
      [
        [
          "f(tf) =>",
          "    [o, c] = request.security(syminfo.tickerid, tf, [open, close], lookahead = barmerge.lookahead_on)",
          '[a, b] = f("D")',
          '[c, d] = f("480")',
          "plot(a + c)",
          "plot(b + d)",
        ].join("\n"),
        [
          '[a, b] = request.security(syminfo.tickerid, "D", [open, close], lookahead = barmerge.lookahead_on)',
          '[c, d] = request.security(syminfo.tickerid, "480", [open, close], lookahead = barmerge.lookahead_on)',
          "plot(a + c)",
          "plot(b + d)",
        ].join("\n"),
      ],
    ];
    for (const [wrapped, direct] of cases) {
      const w = runOne(wrapped);
      const d = runOne(direct);
      for (let p = 0; p < w.length; p++) {
        expect(Array.from(w[p]!.values)).toEqual(Array.from(d[p]!.values));
      }
    }
  });
});

// ── C611: UDF 암시 반환 꼬리의 튜플 UDF 콜 전파 — (a) 마지막 문장이 request.security(sym, tf,
// tupleUdf(...)) bare UDF 콜이면 genFuncBody가 외부 security 노드를 완전히 무시하고 내부 콜을 곧장
// return한다(genTupleDestructure C432와 동일 passthrough — HTF 슬롯/프리패스/taScratch 산출물 0,
// 내부 콜 자신이 "UDF 튜플 반환 = 배열 리터럴" 계약의 배열을 반환). (b) 직접 튜플 UDF 콜 꼬리는
// genImplicitReturn 일반 ExprStmt 분기(`return <콜>`)가 같은 계약을 공짜로 충족해 codegen 변경 0줄
// — analyzer가 FuncInfo 튜플 메타만 승계한다(analyzer.test.ts C611 블록 참조). ──
describe("CodeGen tuple-UDF tail-call return propagation (C611)", () => {
  it("emits a direct inner-call return for the security bare-UDF wrapper tail — outer security node fully discarded", () => {
    const code = codegenSource(
      'inner() =>\n    [close, open]\nwrap() => request.security(syminfo.tickerid, "60", inner())\n[a, b] = wrap()',
    );
    expect(code).toContain("return inner(0);");
    expect(code).toContain("var [a, b] = wrap(0);");
    expect(code).not.toContain("securityCache");
    expect(code).not.toContain("taScratch");
  });

  it("emits a plain call return for the direct tuple-UDF chain tail (genImplicitReturn 일반 분기 재사용)", () => {
    const code = codegenSource("inner(x) =>\n    [x + 1.0, x * 2.0]\nouter(y) => inner(y)\n[a, b] = outer(close)");
    expect(code).toContain("return inner(0, y);");
    expect(code).toContain("var [a, b] = outer(0, $.close.get(0));");
  });

  it("hand-verified E2E: security bare-UDF wrapper values equal the direct destructure of the same inner call (stateful inner 포함)", () => {
    const bases = Array.from({ length: 20 }, (_, i) => 100 + Math.sin(i * 1.3) * 10 + i * 0.5);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b) => b + 1),
      volume: bases.map((_, i) => 1000 + i * 7),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const cases: [string, string][] = [
      [
        [
          "inner() =>",
          "    s = ta.sma(close, 3)",
          "    [s, s + 1.0]",
          'wrap() => request.security(syminfo.tickerid, "D", inner())',
          "[a, b] = wrap()",
          "plot(a)",
          "plot(b)",
        ].join("\n"),
        [
          "inner() =>",
          "    s = ta.sma(close, 3)",
          "    [s, s + 1.0]",
          '[a, b] = request.security(syminfo.tickerid, "D", inner())',
          "plot(a)",
          "plot(b)",
        ].join("\n"),
      ],
      [
        [
          "inner(x, y) =>",
          "    [x + 1, y + 2]",
          "wrap(tf) => request.security(syminfo.tickerid, tf, inner(high, low))",
          '[a, b] = wrap("480")',
          "plot(a)",
          "plot(b)",
        ].join("\n"),
        ["inner(x, y) =>", "    [x + 1, y + 2]", "[a, b] = inner(high, low)", "plot(a)", "plot(b)"].join("\n"),
      ],
    ];
    for (const [wrapped, direct] of cases) {
      const w = runOne(wrapped);
      const d = runOne(direct);
      for (let p = 0; p < w.length; p++) {
        expect(Array.from(w[p]!.values)).toEqual(Array.from(d[p]!.values));
      }
    }
  });

  it("hand-verified E2E: direct tuple-UDF chain equals the un-chained call bar-by-bar", () => {
    const bases = Array.from({ length: 12 }, (_, i) => 50 + i * 2);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b) => b + 1),
      volume: bases.map(() => 1000),
      time: bases.map((_, i) => 1704067200000 + i * 3600000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const chained = runOne(
      "inner(x) =>\n    [x + 1.0, x * 2.0]\nouter(y) => inner(y)\n[a, b] = outer(close)\nplot(a)\nplot(b)",
    );
    const direct = runOne("inner(x) =>\n    [x + 1.0, x * 2.0]\n[a, b] = inner(close)\nplot(a)\nplot(b)");
    for (let p = 0; p < chained.length; p++) {
      expect(Array.from(chained[p]!.values)).toEqual(Array.from(direct[p]!.values));
    }
  });
});

