// ── C631: `[a, b] = [e1, e2]` 직접 튜플 리터럴 값(analyzer resolveTupleValueBranch TupleExpr
// 케이스가 이미 검증) — genExpr는 TupleExpr를 codegen 못 하므로(값 위치 하드 에러 케이스) 새
// genTupleDestructure 분기를 추가해 원소별로 직접 genExpr한 뒤 네이티브 배열 구조분해 대입
// (`[names] = [elemCodes]`)으로 내린다. RHS 배열 리터럴이 원자적으로 먼저 평가되므로(Python 튜플
// 언팩과 동형) 스왑 관용구(`[x, y] = [y, x]`)까지 순차 대입 없이 안전하다. ──
describe("CodeGen direct tuple literal destructure value (C631)", () => {
  it("emits a native array-destructure assignment for a direct tuple literal value", () => {
    const code = codegenSource(["[a, b] = [close + 1, high * 2]", "plot(a)"].join("\n"));
    expect(code).toContain("var [a, b] = [($.close.get(0) + 1), ($.high.get(0) * 2)];");
  });

  it("emits the RHS array literal atomically for a swap idiom (no sequential-assignment corruption)", () => {
    const code = codegenSource(["x = close", "y = open", "[x, y] = [y, x]", "plot(x)"].join("\n"));
    expect(code).toContain("var [x, y] = [y, x];");
  });

  it("hand-verified E2E: direct tuple literal value equals the equivalent two-statement assignment bar-by-bar", () => {
    const bases = Array.from({ length: 20 }, (_, i) => 100 + Math.sin(i * 1.3) * 10 + i * 0.5);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b) => b + 1),
      volume: bases.map((_, i) => 1000 + i * 7),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const viaLiteral = runOne(
      ["[a, b] = [close + 1, high * 2]", "plot(a)", "plot(b)"].join("\n"),
    );
    const viaAssignments = runOne(["a = close + 1", "b = high * 2", "plot(a)", "plot(b)"].join("\n"));
    for (let p = 0; p < viaLiteral.length; p++) {
      expect(Array.from(viaLiteral[p]!.values)).toEqual(Array.from(viaAssignments[p]!.values));
    }
  });

  it("hand-verified E2E: swap idiom equals a manual temp-variable swap bar-by-bar", () => {
    const bases = Array.from({ length: 20 }, (_, i) => 100 + Math.sin(i * 1.7) * 8 + i * 0.3);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 2),
      low: bases.map((b) => b - 1),
      close: bases.map((b) => b + 0.5),
      volume: bases.map((_, i) => 1000 + i * 5),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const viaSwapLiteral = runOne(["x = close", "y = open", "[x, y] = [y, x]", "plot(x)", "plot(y)"].join("\n"));
    const viaManualSwap = runOne(
      ["x = close", "y = open", "tmp = x", "x := y", "y := tmp", "plot(x)", "plot(y)"].join("\n"),
    );
    for (let p = 0; p < viaSwapLiteral.length; p++) {
      expect(Array.from(viaSwapLiteral[p]!.values)).toEqual(Array.from(viaManualSwap[p]!.values));
    }
  });
});

// ── C612: 분기 꼬리(if/switch/삼항)의 security 튜플/튜플 UDF 콜 전파 — genImplicitReturn에
// (a) security 튜플 리터럴 콜(comma-식 실행 후 $.taScratch 배열 return), (b) security bare-UDF
// passthrough(내부 콜 직접 return), (c) 튜플 삼항 꼬리(__cfr 임시 스캐폴드 + 배열 return) 분기를
// 추가하고, genTupleValueLines(디스트럭처 값 위치 공유 스캐폴드)에도 TernaryOp/bare-UDF 리프를
// 대칭 추가. genReturnIf/SwitchStmt의 else-없음 NaN 폴백도 새 리프를 배열 폴백으로 판별한다. ──
describe("CodeGen tuple branch-tail forms (C612)", () => {
  const SEC_IF_SRC = [
    "getTF(sel) =>",
    "    if sel",
    '        request.security(syminfo.tickerid, "D", [high, low])',
    "    else",
    '        request.security(syminfo.tickerid, "W", [high, low])',
    "[h1, l1] = getTF(close > open)",
    "plot(h1)",
    "plot(l1)",
  ].join("\n");

  it("emits a scratch-fill statement + array return for a security tuple-literal branch tail", () => {
    const code = codegenSource(SEC_IF_SRC);
    expect(code).toContain("($.taScratch[0] = rt.security.get(");
    expect(code).toContain("return [$.taScratch[0], $.taScratch[1]];");
  });

  it("emits a direct inner-call return for a security bare-UDF branch tail — outer security node fully discarded", () => {
    const code = codegenSource(
      [
        "inner() =>",
        "    [close, open]",
        "f3(useSec) =>",
        "    if useSec",
        '        request.security(syminfo.tickerid, "D", inner())',
        "    else",
        "        inner()",
        "[s1, s2] = f3(close > open)",
        "plot(s1)",
        "plot(s2)",
      ].join("\n"),
    );
    expect(code).toContain("return inner(0);");
    expect(code).not.toContain("securityCache"); // passthrough — HTF 캐시 산출물 0
  });

  it("emits the __cfr temp scaffold + array return for a tuple ternary tail", () => {
    const code = codegenSource(
      `f2(c) =>\n    c ? [close, open] : request.security(syminfo.tickerid, "D", [close, open])\n[t1, t2] = f2(close > open)\nplot(t1)\nplot(t2)`,
    );
    expect(code).toContain("let __cfr0_0 = NaN, __cfr0_1 = NaN;");
    expect(code).toContain("return [__cfr0_0, __cfr0_1];");
  });

  it("falls back to an array [NaN,NaN] (not bare NaN) for an else-less if tail with a security tuple leaf", () => {
    const code = codegenSource(
      [
        "g(sel) =>",
        "    if sel",
        '        request.security(syminfo.tickerid, "D", [high, low])',
        "[n1, n2] = g(close > open)",
        "plot(n1)",
        "plot(n2)",
      ].join("\n"),
    );
    expect(code).toContain("else { return [NaN, NaN]; }");
    expect(code).not.toContain("else { return NaN; }");
  });

  it("falls back to an array [NaN,NaN] for a default-less switch tail whose cases are tuple-UDF calls", () => {
    const code = codegenSource(
      [
        "calc2(x) =>",
        "    [x + 1.0, x * 2.0]",
        "pick(t) =>",
        "    switch",
        '        t == "A" => calc2(close)',
        '        t == "B" => calc2(open)',
        '[x1, y1] = pick("C")',
        "plot(x1)",
        "plot(y1)",
      ].join("\n"),
    );
    expect(code).toContain("else { return [NaN, NaN]; }");
  });

  it("emits a destructuring assignment into __cfr temps for a bare-UDF leaf in destructure-if value position", () => {
    const code = codegenSource(
      [
        "inner() =>",
        "    [close, open]",
        "[a, b] = if close > open",
        '    request.security(syminfo.tickerid, "D", inner())',
        "else",
        "    inner()",
        "plot(a)",
        "plot(b)",
      ].join("\n"),
    );
    expect(code).toContain("[__cfr0_0, __cfr0_1] = inner(0);");
    expect(code).not.toContain("securityCache");
  });

  const mkData = (): OHLCVData => {
    const bases = Array.from({ length: 18 }, (_, i) => 100 + Math.sin(i * 1.3) * 10 + i * 0.5);
    return {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b, i) => b + (i % 2 === 0 ? 1 : -1)),
      volume: bases.map((_, i) => 1000 + i * 7),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
  };
  const runPlots = (source: string, data: OHLCVData) => {
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) throw new Error("unreachable");
    return run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    ).plots;
  };

  it("hand-verified E2E: an if tail with security tuple branches equals the destructure-if form (C508 기지원 참조 폼)", () => {
    const data = mkData();
    const tail = runPlots(SEC_IF_SRC, data);
    const reference = runPlots(
      [
        "[h1, l1] = if close > open",
        '    request.security(syminfo.tickerid, "D", [high, low])',
        "else",
        '    request.security(syminfo.tickerid, "W", [high, low])',
        "plot(h1)",
        "plot(l1)",
      ].join("\n"),
      data,
    );
    for (let p = 0; p < tail.length; p++) {
      expect(Array.from(tail[p]!.values)).toEqual(Array.from(reference[p]!.values));
    }
  });

  it("hand-verified E2E: a tuple ternary tail equals the destructure-ternary form (C416 기지원 참조 폼)", () => {
    const data = mkData();
    const tail = runPlots(
      `f2(c) =>\n    c ? [close, open] : request.security(syminfo.tickerid, "D", [close, open])\n[t1, t2] = f2(close > open)\nplot(t1)\nplot(t2)`,
      data,
    );
    const reference = runPlots(
      `[t1, t2] = close > open ? [close, open] : request.security(syminfo.tickerid, "D", [close, open])\nplot(t1)\nplot(t2)`,
      data,
    );
    for (let p = 0; p < tail.length; p++) {
      expect(Array.from(tail[p]!.values)).toEqual(Array.from(reference[p]!.values));
    }
  });

  it("hand-verified E2E: a subject-less switch tail with tuple-UDF cases picks branches bar-by-bar", () => {
    const data: OHLCVData = {
      open: [1, 2, 5],
      high: [3, 3, 5],
      low: [1, 4, 5],
      close: [2, 1, 5],
      volume: [1, 1, 1],
    };
    const source = [
      "calc2(x) =>",
      "    [x + 1.0, x * 2.0]",
      "pick(sel) =>",
      "    switch",
      "        sel => calc2(close)",
      "        => [low, low]",
      "[x1, y1] = pick(close > open)",
      "var float __obs_x = na",
      "__obs_x := x1",
      "var float __obs_y = na",
      "__obs_y := y1",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
    );
    expect(bars[0]!["var:__obs_x"]).toBe(3.0); // close(2)>open(1): calc2(2) = [3, 4]
    expect(bars[0]!["var:__obs_y"]).toBe(4.0);
    expect(bars[1]!["var:__obs_x"]).toBe(4.0); // close(1)<open(2): default [low, low] = [4, 4]
    expect(bars[1]!["var:__obs_y"]).toBe(4.0);
    expect(bars[2]!["var:__obs_x"]).toBe(5.0); // close===open: default [5, 5]
    expect(bars[2]!["var:__obs_y"]).toBe(5.0);
  });

  it("hand-verified E2E: an else-less if tail with a security tuple leaf yields [NaN,NaN] when the condition is false (no crash)", () => {
    const data = mkData();
    const source = [
      "g(sel) =>",
      "    if sel",
      '        request.security(syminfo.tickerid, "D", [high, low])',
      "[n1, n2] = g(close < open - 1000)",
      "plot(n1)",
      "plot(n2)",
    ].join("\n");
    const plots = runPlots(source, data);
    for (const p of plots) {
      for (const v of p.values) expect(v).toBeNaN();
    }
  });
});

// ── C613: 분기 꼬리(if/switch/삼항) 위치의 UDT method/컨테이너 method/스칼라 확장 method 튜플
// 반환 — analyzer resolveTupleValueBranch가 새로 인정하는 리프. codegen은 변경 0줄(UDT method
// 콜은 이미 일반 배열 반환 함수라 genTupleValueLines/genImplicitReturn의 기존 범용 폴백이 그대로
// 맞아떨어짐) — 이 describe는 그 무변경 주장을 실행으로 증명한다. ──
describe("CodeGen tuple branch-tail forms — UDT method dispatch (C613)", () => {
  const UDT_IF_SRC = [
    "type Box",
    "    float v",
    "method f(Box this) =>",
    "    [this.v, this.v * 2]",
    "var Box b = Box.new(1.0)",
    "[a, c] = if close > open",
    "    b.f()",
    "else",
    "    [0.0, 0.0]",
  ].join("\n");

  it("emits a native array-destructure into the if-tail's __cfr temps for a UDT method call (existing genIfTupleDestructure scaffold, no new codegen)", () => {
    const code = codegenSource(UDT_IF_SRC);
    expect(code).toContain("[__cfr0_0, __cfr0_1] = Box$f(0, $.vars[0]);");
    expect(code).toContain("var a = __cfr0_0, c = __cfr0_1;");
  });

  it("transpile() end-to-end: an if-tail UDT method call destructures correctly bar-by-bar", () => {
    const data: OHLCVData = { open: [1, 2], high: [1, 2], low: [1, 2], close: [4, 1], volume: [1, 1] };
    const source = [UDT_IF_SRC, "var float __obs_a = na", "__obs_a := a", "var float __obs_c = na", "__obs_c := c"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_a"]).toBe(1.0); // close(4)>open(1): b.f() = [1.0, 2.0]
    expect(bars[0]!["var:__obs_c"]).toBe(2.0);
    expect(bars[1]!["var:__obs_a"]).toBe(0.0); // close(1)<open(2): else [0.0, 0.0]
    expect(bars[1]!["var:__obs_c"]).toBe(0.0);
  });

  it("transpile() end-to-end: a subject-less switch tail with a UDT method case destructures correctly bar-by-bar", () => {
    const data: OHLCVData = { open: [1, 2], high: [1, 2], low: [1, 2], close: [4, 1], volume: [1, 1] };
    const source = [
      "type Box",
      "    float v",
      "method f(Box this) =>",
      "    [this.v, this.v * 2]",
      "var Box b = Box.new(1.0)",
      "[a, c] = switch",
      "    close > open => b.f()",
      "    => [0.0, 0.0]",
      "var float __obs_a = na",
      "__obs_a := a",
      "var float __obs_c = na",
      "__obs_c := c",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[0]!["var:__obs_a"]).toBe(1.0);
    expect(bars[0]!["var:__obs_c"]).toBe(2.0);
    expect(bars[1]!["var:__obs_a"]).toBe(0.0);
    expect(bars[1]!["var:__obs_c"]).toBe(0.0);
  });
});

// ── C533: ta.* 콜 포함 security expression의 UDF/method 본문 지원 (C367 게이트 해제) ──
// 클론 ta 콜은 전역 taSlots 풀에 배정되므로 프리패스(__secExprN — top-level 방출)가 $.taSlots[k]를
// 직접 참조하고 __taBase(함수-상대, UDF 콜사이트 인자로만 존재)는 절대 남지 않는다. UDF 본문의
// 읽기는 고정 tf면 securityExprCallSlots 고정 슬롯, distinct tf면 base + __secIdx — 기존 경로 그대로.
describe("CodeGen request.security ta-in-UDF expression (C533)", () => {
  it("emits a top-level __secExpr prepass with a global $.taSlots reference (no __taBase) for a fixed-tf UDF form", () => {
    const code = codegenSource('f() =>\n    request.security(syminfo.tickerid, "D", ta.sma(close, 3))\nx = f()\nplot(x)');
    expect(code).toContain("function __secExpr0()");
    expect(code).toContain("rt.ta.sma($.taSlots[0], close, 3)");
    expect(code).not.toContain("__taBase");
    // UDF 본문 읽기는 고정 슬롯 getFromArray(콜사이트 서수 무관 순수 읽기)
    expect(code).toContain("rt.security.getFromArray($.securityExprCache[0], $.securityCache[0], $.idx, false, false)");
  });

  it("emits per-site prepasses each with its own global ta slot for a distinct-tf UDF form", () => {
    const code = codegenSource(
      'f(tf) =>\n    request.security(syminfo.tickerid, tf, ta.sma(close, 3))\nx = f("D")\ny = f("480")\nplot(x)\nplot(y)',
    );
    expect(code).toContain("function __secExpr0()");
    expect(code).toContain("function __secExpr1()");
    expect(code).toContain("rt.ta.sma($.taSlots[0], close, 3)");
    expect(code).toContain("rt.ta.sma($.taSlots[1], close, 3)"); // 사이트별 독립 클론 슬롯
    expect(code).not.toContain("__taBase");
    // 읽기는 C453 경로 그대로 base + __secIdx
    expect(code).toContain("$.securityExprCache[0 + __secIdx]");
  });

  it("hand-verified E2E: fixed-tf scalar/tuple ta forms inside a UDF equal the direct top-level forms", () => {
    // 20바, 8시간 간격(3바 = 1일) — "D"와 "480"이 서로 다른 집계를 내는 데이터(C529/C530 E2E와 동일).
    const bases = Array.from({ length: 20 }, (_, i) => 100 + Math.sin(i * 1.3) * 10 + i * 0.5);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b) => b + 1),
      volume: bases.map((_, i) => 1000 + i * 7),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const cases: [string, string][] = [
      [
        'f() =>\n    request.security(syminfo.tickerid, "D", ta.sma(close, 3))\nx = f()\ny = f()\nplot(x)\nplot(y)',
        'x = request.security(syminfo.tickerid, "D", ta.sma(close, 3))\ny = request.security(syminfo.tickerid, "D", ta.sma(close, 3))\nplot(x)\nplot(y)',
      ],
      [
        'f() =>\n    request.security(syminfo.tickerid, "D", [ta.sma(close, 3) + 1, open])\n[a, b] = f()\nplot(a)\nplot(b)',
        '[a, b] = request.security(syminfo.tickerid, "D", [ta.sma(close, 3) + 1, open])\nplot(a)\nplot(b)',
      ],
      [
        // 다중 ta 콜 + ta 결과 히스토리 읽기(histReads 경로)
        'f() =>\n    request.security(syminfo.tickerid, "D", ta.ema(close, 2) - ta.sma(close, 2)[1])\nx = f()\nplot(x)',
        'x = request.security(syminfo.tickerid, "D", ta.ema(close, 2) - ta.sma(close, 2)[1])\nplot(x)',
      ],
    ];
    for (const [wrapped, direct] of cases) {
      const w = runOne(wrapped);
      const d = runOne(direct);
      for (let p = 0; p < w.length; p++) {
        expect(Array.from(w[p]!.values)).toEqual(Array.from(d[p]!.values));
      }
    }
  });

  it("hand-verified E2E: distinct-tf scalar/tuple ta forms equal the direct per-tf top-level forms (사이트별 클론 상태 격리)", () => {
    const bases = Array.from({ length: 20 }, (_, i) => 100 + Math.sin(i * 1.3) * 10 + i * 0.5);
    const data: OHLCVData = {
      open: bases,
      high: bases.map((b) => b + 3),
      low: bases.map((b) => b - 2),
      close: bases.map((b) => b + 1),
      volume: bases.map((_, i) => 1000 + i * 7),
      time: bases.map((_, i) => 1704067200000 + i * 28800000),
    };
    const runOne = (source: string) => {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("unreachable");
      return run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      ).plots;
    };
    const cases: [string, string][] = [
      [
        'f(tf) =>\n    request.security(syminfo.tickerid, tf, ta.sma(close, 3))\nx = f("D")\ny = f("480")\nplot(x)\nplot(y)',
        'x = request.security(syminfo.tickerid, "D", ta.sma(close, 3))\ny = request.security(syminfo.tickerid, "480", ta.sma(close, 3))\nplot(x)\nplot(y)',
      ],
      [
        'f(tf) =>\n    request.security(syminfo.tickerid, tf, [ta.sma(close, 3), open])\n[a, b] = f("D")\n[c, d] = f("480")\nplot(a + c)\nplot(b + d)',
        '[a, b] = request.security(syminfo.tickerid, "D", [ta.sma(close, 3), open])\n[c, d] = request.security(syminfo.tickerid, "480", [ta.sma(close, 3), open])\nplot(a + c)\nplot(b + d)',
      ],
    ];
    for (const [wrapped, direct] of cases) {
      const w = runOne(wrapped);
      const d = runOne(direct);
      for (let p = 0; p < w.length; p++) {
        expect(Array.from(w[p]!.values)).toEqual(Array.from(d[p]!.values));
      }
    }
  });
});

// ── request.security expression 안 ta.* 콜의 kwargs 폼(C443, wild ta-call:* 재프로브 결과 —
// matchSecurityExprTaCall의 blanket kwargs 거부가 일반 non-security 콜사이트(C400/C402,
// TA_REGISTRY.kwargParamNames)보다 뒤처져 있던 갭). buildSecurityExprNode가 resolveTaKwargPositions로
// kwargs를 위치 배열로 접어 넣은 뒤 각 위치를 그대로 재귀 빌드하므로, 최종 클론은 kwargs=[]인 순수
// 위치 인자 CallExpr — codegen은 이미 있던 위치 인자 경로를 그대로 타 변경이 전혀 없다(codegen.ts
// 변경 0줄, analyzer만 수정).
describe("CodeGen request.security expression ta.* call kwargs form (C443)", () => {
  it("exact-string: ta.atr(length=X) emits byte-identical code to the already-supported positional form ta.atr(X)", () => {
    const kwarg = codegenSource('x = request.security("", "D", ta.atr(length = 14))');
    const positional = codegenSource('x = request.security("", "D", ta.atr(14))');
    expect(kwarg).toBe(positional);
    expect(kwarg).toContain("rt.ta.atr($.taSlots[0], high, low, (h > 0 ? cache.close[h - 1] : NaN), 14);");
  });

  it("exact-string: ta.sma(source=,length=) emits byte-identical code to the positional form ta.sma(close,14)", () => {
    const kwarg = codegenSource('x = request.security("", "D", ta.sma(source = close, length = 14))');
    const positional = codegenSource('x = request.security("", "D", ta.sma(close, 14))');
    expect(kwarg).toBe(positional);
  });

  it("exact-string: a mix of positional + kwarg args (ta.sma(close, length=14)) is byte-identical to the fully-positional form", () => {
    const mixed = codegenSource('x = request.security("", "D", ta.sma(close, length = 14))');
    const positional = codegenSource('x = request.security("", "D", ta.sma(close, 14))');
    expect(mixed).toBe(positional);
  });

  it("a kwarg value reached only through a top-level '=' var-subst (C440 input.int scalar const) is recursively re-validated/rebuilt through the SAME narrow grammar the kwarg-less positional path already used — the security prepass re-evaluates rt.input.int(...) inline inside the ta.atr call", () => {
    const substituted = codegenSource(
      'atrLength = input.int(14, "Length")\nx = request.security("", "D", ta.atr(length = atrLength))',
    );
    expect(substituted).toContain(
      'rt.ta.atr($.taSlots[0], high, low, (h > 0 ? cache.close[h - 1] : NaN), rt.input.int($.inputs, 14, "Length"));',
    );
    // 치환된 값이 kwarg 경유가 아니라 위치 인자로 직접 왔을 때(C438 선례)와 완전히 동일한 방식으로
    // 재귀 검증/방출됐는지 대조 — 두 경로가 서로 다른 코드를 만들면 kwarg 해석이 별도 버그를 숨긴 것.
    const positionalSubstituted = codegenSource(
      'atrLength = input.int(14, "Length")\nx = request.security("", "D", ta.atr(atrLength))',
    );
    expect(substituted).toBe(positionalSubstituted);
  });

  it("hand-verified E2E: ta.atr(length=X) kwarg form matches the positional form bar-by-bar (regression guard against the resolvedArgs 'hole' path silently misordering args)", () => {
    const kwargSource = ['x = request.security("", "D", ta.atr(length = 5))', "plot(x)"].join("\n");
    const positionalSource = ['x = request.security("", "D", ta.atr(5))', "plot(x)"].join("\n");
    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110],
      high: [103, 105, 102, 108, 110, 108, 112],
      low: [99, 100, 100, 103, 106, 104, 108],
      close: [102, 101, 103, 106, 107, 109, 111],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250],
    };
    function runPlots(source: string) {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("transpile failed");
      const { plots } = run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      );
      return plots;
    }
    const kwargPlots = runPlots(kwargSource);
    const positionalPlots = runPlots(positionalSource);
    expect(Array.from(kwargPlots[0]!.values)).toEqual(Array.from(positionalPlots[0]!.values));
  });
});

// ── request.security bare 다중 반환 ta.* 콜 expression(C433, wild bareTaMultiReturn 서브클러스터,
// next_hint(C432)) — `[a,b,...] = request.security(sym, tf, ta.macd(...))`에서 expression 인자가
// 브래킷 없이 그대로 다중 반환 ta.* 콜(macd/bb/kc/supertrend/dmi/vwap 3-인자)인 폼.
// bareUdfCall(C432)의 자매 메커니즘 — pine2py 직접 실행(오라클) 재검증 결과 동일한 literal
// passthrough 시맨틱(HTF 재계산 0). genTupleDestructure가 securityBareTaCallSlots로 등록된 내부
// ta.* CallExpr에서 곧장 genExpr하며, 그 콜이 stateCallSlots에 표준 등록돼 있어 기존 다중반환
// taScratch 패턴(genCallExpr의 "$.taScratch" 트레일링 인자)이 자동으로 적용된다.
describe("CodeGen request.security() bare multi-return ta.* call expression (C433)", () => {
  it("emits the exact same code as a plain (non-security) ta.macd tuple destructure — the request.security wrapper (symbol/tf/gaps/lookahead) is fully discarded", () => {
    const withSecurity = codegenSource('[m, s, h] = request.security(syminfo.tickerid, "D", ta.macd(close, 12, 26, 9))');
    const plain = codegenSource("[m, s, h] = ta.macd(close, 12, 26, 9)");
    expect(withSecurity).toBe(plain);
  });

  it("exact-string: writes to $.taScratch and reads back via indexed assignment, no rt.security.* reference anywhere", () => {
    const code = codegenSource('[m, s, h] = request.security(syminfo.tickerid, "D", ta.macd(close, 12, 26, 9))');
    expect(code).toContain("rt.ta.macd($.taSlots[0], $.close.get(0), 12, 26, 9, $.taScratch);");
    expect(code).toContain("var m = $.taScratch[0], s = $.taScratch[1], h = $.taScratch[2];");
    expect(code).not.toContain("rt.security");
  });

  it("discards gaps=/lookahead= kwargs with no codegen change (still byte-identical to the wrapper-free form)", () => {
    const withKwargs = codegenSource(
      '[m, s, h] = request.security(syminfo.tickerid, "D", ta.macd(close, 12, 26, 9), gaps=true, lookahead=true)',
    );
    const withoutKwargs = codegenSource(
      '[m, s, h] = request.security(syminfo.tickerid, "D", ta.macd(close, 12, 26, 9))',
    );
    expect(withKwargs).toBe(withoutKwargs);
  });

  it("emits byte-identical code for the fully-keyword form vs the positional form", () => {
    const positional = codegenSource('[m, s, h] = request.security(syminfo.tickerid, "D", ta.macd(close, 12, 26, 9))');
    const keyword = codegenSource(
      '[m, s, h] = request.security(symbol=syminfo.tickerid, timeframe="D", expression=ta.macd(close, 12, 26, 9))',
    );
    expect(keyword).toBe(positional);
  });

  it("also works for the other multi-return ta.* functions (bb/kc/supertrend/dmi) — same wrapper-discard, byte-identical to the plain form", () => {
    for (const [call, names] of [
      ["ta.bb(close, 20, 2)", "b, u, l"],
      ["ta.kc(close, 20, 2)", "b, u, l"],
      ["ta.supertrend(3, 10)", "v, dir"],
      ["ta.dmi(14, 14)", "p, m, a"],
    ] as const) {
      const withSecurity = codegenSource(`[${names}] = request.security(syminfo.tickerid, "D", ${call})`);
      const plain = codegenSource(`[${names}] = ${call}`);
      expect(withSecurity).toBe(plain);
    }
  });

  it("hand-verified E2E: ta.macd re-executes on every bar at the current (chart) timeframe — matches a plain (non-security) ta.macd(...) plot output bar-by-bar (pine2py oracle behavior, python-verified — literal port, not real HTF re-execution)", () => {
    const withSecuritySource = [
      '[m, s, h] = request.security(syminfo.tickerid, "D", ta.macd(close, 12, 26, 9))',
      "plot(m)",
      "plot(s)",
      "plot(h)",
    ].join("\n");
    const plainSource = ["[m, s, h] = ta.macd(close, 12, 26, 9)", "plot(m)", "plot(s)", "plot(h)"].join("\n");
    const data: OHLCVData = {
      open: [100, 102, 101, 105, 108, 106, 110, 113, 111, 115],
      high: [103, 105, 102, 108, 110, 108, 112, 115, 113, 117],
      low: [99, 100, 100, 103, 106, 104, 108, 111, 109, 113],
      close: [102, 101, 103, 106, 107, 109, 111, 112, 114, 116],
      volume: [1000, 1100, 1050, 1200, 1150, 1300, 1250, 1400, 1350, 1500],
    };
    function runPlots(source: string) {
      const result = transpile(source);
      expect(result.ok).toBe(true);
      if (!result.ok) throw new Error("transpile failed");
      const { plots } = run(
        result.code,
        result.varSlots,
        result.taSlotCount,
        data,
        result.fnVarSlotCount,
        result.historySlotCount,
        result.taScratchSize,
        {},
        result.plotTitles,
        result.securityTfs,
      );
      return plots;
    }
    const withSecurityPlots = runPlots(withSecuritySource);
    const plainPlots = runPlots(plainSource);
    expect(Array.from(withSecurityPlots[0]!.values)).toEqual(Array.from(plainPlots[0]!.values));
    expect(Array.from(withSecurityPlots[1]!.values)).toEqual(Array.from(plainPlots[1]!.values));
    expect(Array.from(withSecurityPlots[2]!.values)).toEqual(Array.from(plainPlots[2]!.values));
  });
});

// ── request.security_lower_tf 튜플 디스트럭처(C434, wild next_hint(C433) 클러스터① 서브축 (1)
// security-wrapped 잔여 — TupleExpr 리터럴/bare UDF 콜 두 폼). request.security(C432/C433)와 달리
// pine2py request_security_lower_tf() 스텁은 expression 하나를 그대로 `[expression]`(원소 1개짜리
// 배열)으로 감싸는 순수 스텁이라 튜플 expression 자체에서 크래시한다(python 직접 실행 확인:
// `a,b,c = wa.request_security_lower_tf(...)`가 ValueError로 죽음 — 오라클 구조적 불가, C267[part2]/
// C340과 동일 급). 기존 스칼라 케이스(C310)가 이미 오라클 검증까지 마친 "값 1개를 원소 1개짜리
// 배열로 감싼다"는 규칙을 원소별로 그대로 확장한 hand-verified 설계(TV 미검증 가설, DIVERGENCES 등재).
describe("CodeGen request.security_lower_tf() tuple destructure (C434)", () => {
  it("exact-string: TupleExpr literal form wraps each element in its own 1-element array literal, symbol/timeframe fully discarded", () => {
    const code = codegenSource('[aH, aL] = request.security_lower_tf(syminfo.tickerid, "1", [high, low])');
    expect(code).toContain("var aH = [$.high.get(0)], aL = [$.low.get(0)];");
    expect(code).not.toContain("rt.security");
    expect(code).not.toContain("rt.request.security_lower_tf");
  });

  it("exact-string: bare UDF call form invokes the UDF exactly once into a temp, then wraps each returned element individually", () => {
    const SRC_MYFUNC = "myFunc(x, y) =>\n    a = x + 1\n    b = y + 2\n    [a, b]\n";
    const code = codegenSource(SRC_MYFUNC + '[hi, lo] = request.security_lower_tf(syminfo.tickerid, "D", myFunc(high, low))');
    expect(code).toContain("let __secLtf0 = myFunc(0, $.high.get(0), $.low.get(0));");
    expect(code).toContain("var hi = [__secLtf0[0]], lo = [__secLtf0[1]];");
    expect(code).not.toContain("rt.security");
    expect(code).not.toContain("rt.request.security_lower_tf");
  });

  it("discards ignore_invalid_symbol=/calc_bars_count= kwargs with no codegen change (still byte-identical to the wrapper-free form)", () => {
    const withKwargs = codegenSource(
      '[aH, aL] = request.security_lower_tf(syminfo.tickerid, "1", [high, low], ignore_invalid_symbol=true, calc_bars_count=10)',
    );
    const withoutKwargs = codegenSource('[aH, aL] = request.security_lower_tf(syminfo.tickerid, "1", [high, low])');
    expect(withKwargs).toBe(withoutKwargs);
  });

  it("does not regress the pre-existing scalar (non-tuple) form — still routes through rt.request.security_lower_tf", () => {
    const code = codegenSource('x = request.security_lower_tf(syminfo.tickerid, "1", close)');
    expect(code).toContain("rt.request.security_lower_tf(");
  });

  it("hand-verified E2E: TupleExpr literal form — each destructured name holds a fresh 1-element array of the tuple element's current-bar value (matches the already-oracle-verified scalar-case wrapping rule, C310, applied per element)", () => {
    const source = [
      '[aH, aL] = request.security_lower_tf(syminfo.tickerid, "1", [high, low])',
      "plot(array.get(aH, 0))",
      "plot(array.get(aL, 0))",
      "plot(array.size(aH))",
    ].join("\n");
    const data: OHLCVData = {
      open: [100, 102, 101],
      high: [103, 105, 102],
      low: [99, 100, 100],
      close: [102, 101, 103],
      volume: [1000, 1100, 1050],
      time: [1704067200000, 1704096000000, 1704124800000],
    };
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(Array.from(plots[0]!.values)).toEqual(Array.from(data.high));
    expect(Array.from(plots[1]!.values)).toEqual(Array.from(data.low));
    expect(Array.from(plots[2]!.values)).toEqual([1, 1, 1]);
  });

  it("hand-verified E2E: bare UDF call form — the UDF re-executes on every bar at the current (chart) timeframe (symbol/timeframe discarded, same literal-passthrough precedent as C432), each returned element wrapped independently", () => {
    const source = [
      "nestedFn(sym) =>\n    a = 1.0\n    b = close\n    [a, b]",
      '[x1, x2] = request.security_lower_tf(syminfo.tickerid, "D", nestedFn(syminfo.tickerid))',
      "plot(array.get(x1, 0))",
      "plot(array.get(x2, 0))",
    ].join("\n");
    const data: OHLCVData = {
      open: [100, 102, 101],
      high: [103, 105, 102],
      low: [99, 100, 100],
      close: [102, 101, 103],
      volume: [1000, 1100, 1050],
      time: [1704067200000, 1704096000000, 1704124800000],
    };
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(Array.from(plots[0]!.values)).toEqual([1, 1, 1]);
    expect(Array.from(plots[1]!.values)).toEqual(Array.from(data.close));
  });
});

// ── request.security_lower_tf 튜플 디스트럭처 대상을 for-in 이터러블로 직결하는 관용구(C493,
// next_hint(C492) LIMITATIONS 잔여 축 — wild atr_ar류 6건, `[atr_ar, ...] = request.security_lower_tf(...)`
// 뒤 곧바로 `for a in atr_ar`). 값은 항상 원소 1개짜리 배열(C434)이라 for-in은 그 하나뿐인 원소를
// 그대로 순회해 스칼라로 꺼내는 관용구다. 이 describe는 analyzer.ts의 scope.containerKindHints
// 등록(analyzeTupleDestructure)만 새로 추가됐고 codegen(genForInStmt)은 기존 "array" 분기를 그대로
// 재사용한다는 것을 확인 — codegen 신규 코드 0줄.
describe("CodeGen for-in over a request.security_lower_tf tuple-destructured name (C493)", () => {
  it("exact-string: for-in over a top-level TupleExpr-literal-destructured name compiles through the ordinary array for-in codegen path", () => {
    const code = codegenSource(
      [
        '[aH, aL] = request.security_lower_tf(syminfo.tickerid, "1", [high, low])',
        "var float total = 0.0",
        "for a in aH",
        "    total := a",
      ].join("\n"),
    );
    expect(code).toContain("let __forInArr = aH;");
    expect(code).toContain("let a = __forInArr[__forInIdx];");
  });

  it("hand-verified E2E: top-level for-in over a TupleExpr-destructured name recovers the single wrapped element on every bar", () => {
    const source = [
      '[aH, aL] = request.security_lower_tf(syminfo.tickerid, "1", [high, low])',
      "var float total = 0.0",
      "for a in aH",
      "    total := a",
      "plot(total)",
    ].join("\n");
    const data: OHLCVData = {
      open: [100, 102, 101],
      high: [103, 105, 102],
      low: [99, 100, 100],
      close: [102, 101, 103],
      volume: [1000, 1100, 1050],
      time: [1704067200000, 1704096000000, 1704124800000],
    };
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(Array.from(plots[0]!.values)).toEqual(Array.from(data.high));
  });

  it("hand-verified E2E: for-in over a name destructured inside a UDF body (wild atr_ar shape — destructure and for-in share the same function scope, not top-level)", () => {
    const source = [
      "getAtr(symb) =>\n    a = close + 1\n    b = close - 1\n    [a, b]",
      "executeStrategy(symb) =>",
      '    [atrAr, atrMAr] = request.security_lower_tf(symb, "15", getAtr(symb))',
      "    float atr = 0.0",
      "    for a in atrAr",
      "        atr := a",
      "    atr",
      "plot(executeStrategy(syminfo.tickerid))",
    ].join("\n");
    const data: OHLCVData = {
      open: [100, 102, 101],
      high: [103, 105, 102],
      low: [99, 100, 100],
      close: [102, 101, 103],
      volume: [1000, 1100, 1050],
      time: [1704067200000, 1704096000000, 1704124800000],
    };
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(Array.from(plots[0]!.values)).toEqual(Array.from(data.close).map((c) => c + 1));
  });
});

// ── request.security 튜플 리터럴 expression의 ta.* 콜 혼합 원소(C349b, wild "튜플 리터럴 ... 원소
// 전부가 bare"의 최다빈도 클러스터, 68건 — corpus_scan.mjs top-15 재확인) — C306(all-bare)이 다루지
// 않던 원소별 'ta.*' 콜(스칼라 expression 경로의 exprMatch, C180~C182와 동일 narrow 문법)을 튜플
// 원소로도 허용한다. 원소마다 자신만의 securityCache/securityExprCache slot을 받아(HTF 캐시를
// 원소 수만큼 중복 fetch, GOAL.md "바 루프 안 할당 제로"는 이 1회성 프리앰블 비용과 무관) 기존
// 프리패스(generateSecurityExprPreamble)/getFromArray 메커니즘을 그대로 재사용한다 — 새 런타임
// 함수 0개. bare 원소는 C306과 동일하게 공유 slot 하나로 rt.security.get을 재사용.
describe("CodeGen request.security() tuple literal expression — mixed bare + ta.* elements (C349b)", () => {
  it("emits a HTF prepass preamble for the ta.* element + a comma-sequence mixing rt.security.get(bare)/getFromArray(expr)", () => {
    const code = codegenSource('[o, s] = request.security("", "D", [open, ta.sma(close, 2)])');
    expect(code).toBe(
      [
        "function __secExpr1() {",
        "const cache = $.securityCache[1];",
        "const out = new Float64Array(cache.close.length);",
        "for (let h = 0; h < out.length; h++) {",
        "const open = cache.open[h], high = cache.high[h], low = cache.low[h], close = cache.close[h], volume = cache.volume[h];",
        "out[h] = rt.ta.sma($.taSlots[0], close, 2);",
        "}",
        "return out;",
        "}",
        "$.securityExprCache[1] = __secExpr1();",
        '($.taScratch[0] = rt.security.get($.securityCache[0], $.idx, "open", false, false), $.taScratch[1] = rt.security.getFromArray($.securityExprCache[1], $.securityCache[1], $.idx, false, false));',
        "var o = $.taScratch[0], s = $.taScratch[1];",
      ].join("\n"),
    );
  });

  it("supports a tuple with every element a ta.* call (no bare elements), giving each its own slot and preamble", () => {
    const code = codegenSource(
      '[ph, pl] = request.security("", "D", [ta.pivothigh(high, 2, 2), ta.pivotlow(low, 2, 2)])',
    );
    expect(code).toContain("function __secExpr1() {");
    expect(code).toContain("$.securityExprCache[1] = __secExpr1();");
    expect(code).toContain("function __secExpr2() {");
    expect(code).toContain("$.securityExprCache[2] = __secExpr2();");
    expect(code).toContain(
      '$.taScratch[0] = rt.security.getFromArray($.securityExprCache[1], $.securityCache[1], $.idx, false, false)',
    );
    expect(code).toContain(
      '$.taScratch[1] = rt.security.getFromArray($.securityExprCache[2], $.securityCache[2], $.idx, false, false)',
    );
  });

  it("emits literal true/false for gaps=/lookahead= kwargs on the ta.* element's getFromArray call too", () => {
    const code = codegenSource('[o, s] = request.security("", "D", [open, ta.sma(close, 2)], lookahead=true)');
    expect(code).toContain(
      "$.taScratch[1] = rt.security.getFromArray($.securityExprCache[1], $.securityCache[1], $.idx, false, true)",
    );
  });

  it("end-to-end: [c, s] = request.security(sym, '2', [close, ta.sma(close, 2)]) — bare element reads the raw HTF close, ta.* element re-executes ta.sma over the HTF-native sequence, same shared cache", () => {
    // 동일 데이터셋/tf(6바, "2" naive-count 폴백, ratio=2)를 재사용하는 3c E2E 테스트와 동일한
    // barMap=[0,0,1,1,2,2]/HTF close(cache.close)=[11,21,31] 유도 — bare close는 cache.close를
    // htf_idx로 직접 lookup, ta.sma(length=2)는 h=0 워밍업 NaN, h=1 (11+21)/2=16.
    const source = [
      '[c, s] = request.security("", "2", [close, ta.sma(close, 2)])',
      "var float __obs_c = na",
      "var float __obs_s = na",
      "__obs_c := c",
      "__obs_s := s",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual(["2", "2"]);

    const priceData = [10, 11, 20, 21, 30, 31];
    const data: OHLCVData = {
      open: priceData,
      high: priceData,
      low: priceData,
      close: priceData,
      volume: [1, 1, 1, 1, 1, 1],
    };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    expect(bars.map((b) => b["var:__obs_c"])).toEqual([NaN, NaN, 11, 11, 21, 21]);
    expect(bars.map((b) => b["var:__obs_s"])).toEqual([NaN, NaN, NaN, NaN, 16, 16]);
  });
});

// ── request.security 셋째 슬라이스 서브슬라이스 3b(C181, ROADMAP [hard->분할]) — securityExprCallSlots
// (3a, C180)에 등록된 콜사이트마다 HTF 프리패스 함수(__secExprN)를 프리앰블에 생성한다. 이
// describe는 generateCode() 전체가 아니라 export된 generateSecurityExprPreamble(program)만
// 독립적으로 검증한다(작성 당시 3c 미완성으로 codegenSource/transpile이 이 패턴에서 던졌기 때문 —
// 3c 완료(C182) 이후로도 이 프리패스 생성 자체를 전체 파이프라인 없이 좁게 검증하는 값이 있어
// 그대로 유지. request.security(...) 호출 자신의 codegen(getFromArray 배선)은 아래 3c 전용
// describe가 codegenSource/transpile()+run()으로 검증한다). ──
function analyzeSecuritySource(source: string) {
  return analyze(parse(source));
}

describe("CodeGen generateSecurityExprPreamble() (C181, request.security third slice sub-slice 3b)", () => {
  it("emits a __secExprN prepass function + $.securityExprCache[N] assignment for a single bare ta.* expression call site", () => {
    const program = analyzeSecuritySource('x = request.security("", "D", ta.sma(close, 2))');
    expect(program.errors).toEqual([]);
    const lines = generateSecurityExprPreamble(program);
    expect(lines.join("\n")).toBe(
      [
        "function __secExpr0() {",
        "const cache = $.securityCache[0];",
        "const out = new Float64Array(cache.close.length);",
        "for (let h = 0; h < out.length; h++) {",
        "const open = cache.open[h], high = cache.high[h], low = cache.low[h], close = cache.close[h], volume = cache.volume[h];",
        "out[h] = rt.ta.sma($.taSlots[0], close, 2);",
        "}",
        "return out;",
        "}",
        "$.securityExprCache[0] = __secExpr0();",
      ].join("\n"),
    );
  });

  it("reuses the ta.* call's own $.taSlots slot from 3a (analyzeStatefulCall registration, not a separate offset)", () => {
    const program = analyzeSecuritySource('x = request.security("", "D", ta.rsi(close, 14))');
    const stmt = program.script.body[0] as Assignment;
    const secCall = stmt.value as CallExpr;
    // C367부터 등록되는 ta 콜은 빌드된 클론 노드(securityExprCallSlots의 bodyExpr) — 원본
    // args[2]는 의도적으로 미등록(공유 꼬리 재귀 이중 소비의 구조적 차단, buildSecurityExpr 주석).
    const info = program.securityExprCallSlots.get(secCall)!;
    const taSlot = program.stateCallSlots.get(info.bodyExpr as CallExpr);
    expect(taSlot).toEqual({ fn: "rsi", slot: 0 });
    expect(program.stateCallSlots.has(secCall.args[2] as unknown as CallExpr)).toBe(false);
    const lines = generateSecurityExprPreamble(program);
    expect(lines.join("\n")).toContain(`out[h] = rt.ta.rsi($.taSlots[${taSlot!.slot}], close, 14);`);
  });

  it("codegens bare series identifiers wrapping the ta.* call as HTF prepass loop locals (not $.field.get(0))", () => {
    const program = analyzeSecuritySource('x = request.security("", "D", ta.sma(close, 3) + open)');
    const lines = generateSecurityExprPreamble(program);
    expect(lines.join("\n")).toContain("out[h] = (rt.ta.sma($.taSlots[0], close, 3) + open);");
    expect(lines.join("\n")).not.toContain("$.open.get(0)");
    expect(lines.join("\n")).not.toContain("$.close.get(0)");
  });

  it("translates a function's offset-1 implicit series injection (e.g. ta.tr's prevClose) into a guarded previous-HTF-row cache lookup", () => {
    const program = analyzeSecuritySource('x = request.security("", "D", ta.tr())');
    const lines = generateSecurityExprPreamble(program);
    expect(lines.join("\n")).toContain(
      "out[h] = rt.ta.tr($.taSlots[0], high, low, (h > 0 ? cache.close[h - 1] : NaN));",
    );
  });

  it("assigns sequential slots and generates one __secExprN per expression call site, in source order", () => {
    const program = analyzeSecuritySource(
      ['a = request.security("", "D", ta.sma(close, 2))', 'b = request.security("", "60", ta.ema(close, 3))'].join("\n"),
    );
    const lines = generateSecurityExprPreamble(program);
    const code = lines.join("\n");
    expect(code).toContain("function __secExpr0() {");
    expect(code).toContain("const cache = $.securityCache[0];");
    expect(code).toContain("$.securityExprCache[0] = __secExpr0();");
    expect(code).toContain("function __secExpr1() {");
    expect(code).toContain("const cache = $.securityCache[1];");
    expect(code).toContain("$.securityExprCache[1] = __secExpr1();");
  });

  it("returns an empty array for scripts with no request.security expression call sites (no preamble emitted, no output change)", () => {
    const program = analyzeSecuritySource("var float acc = 0.0");
    expect(generateSecurityExprPreamble(program)).toEqual([]);
  });

  it("does not change the $.field.get(offset) output for the pre-existing (non-security) main-timeframe codegen path (genBarRef regression check)", () => {
    // secCtx===null(기본값)일 때 genBarRef가 기존 출력을 한 글자도 안 바꾼다는 것을 tr/atr/wpr류
    // 암묵 series 캐스케이드로 직접 확인 — 전체 vitest 스위트(3746건)가 이미 회귀 없음을 증명하지만,
    // 이 describe가 건드린 genCallExpr 캐스케이드 자체를 좁게 재확인해둔다.
    expect(codegenSource("x = ta.tr()")).toBe("var x = rt.ta.tr($.taSlots[0], $.high.get(0), $.low.get(0), $.close.get(1));");
    expect(codegenSource("x = ta.atr(14)")).toBe(
      "var x = rt.ta.atr($.taSlots[0], $.high.get(0), $.low.get(0), $.close.get(1), 14);",
    );
  });

  it("hand-verified execution: the generated prepass function computes ta.sma over the HTF close sequence (naive count fallback, ratio 2)", () => {
    const program = analyzeSecuritySource('x = request.security("", "2", ta.sma(close, 2))');
    expect(program.errors).toEqual([]);
    const code = generateSecurityExprPreamble(program).join("\n");
    const factory = new Function("$", "rt", code) as ($: Context, rtArg: typeof rt) => void;

    // 4바, ratio=2(naive count, time 채널 없음) -> HTF 2행: group1=[10,20](close 마지막값 20),
    // group2=[15,25](close 마지막값 25) — security.ts accumulate()의 "close=마지막 값" 규칙.
    const data: OHLCVData = {
      open: [10, 20, 15, 25],
      high: [10, 20, 15, 25],
      low: [10, 20, 15, 25],
      close: [10, 20, 15, 25],
      volume: [1, 1, 1, 1],
    };
    const ctx = new Context(data, 0, program.taSlotCount, 0, 0, 0, {}, 0, program.securityTfs);
    factory(ctx, rt);
    expect(ctx.securityCache[0]!.close).toEqual(new Float64Array([20, 25]));
    // length=2 SMA: 첫 HTF 행은 버퍼가 안 차 NaN, 둘째 행부터 (20+25)/2=22.5.
    expect(ctx.securityExprCache[0]).toEqual(new Float64Array([NaN, 22.5]));
  });

  it("hand-verified execution: ta.tr()'s prevClose correctly reads the *previous HTF row's* close, not the chart timeframe's", () => {
    const program = analyzeSecuritySource('x = request.security("", "2", ta.tr())');
    expect(program.errors).toEqual([]);
    const code = generateSecurityExprPreamble(program).join("\n");
    const factory = new Function("$", "rt", code) as ($: Context, rtArg: typeof rt) => void;

    // 4바, ratio=2: group1(bars0-1)=high max(10,12)=12/low min(5,6)=5/close 마지막=9,
    // group2(bars2-3)=high max(20,22)=22/low min(15,16)=15/close 마지막=19.
    const data: OHLCVData = {
      open: [10, 12, 20, 22],
      high: [10, 12, 20, 22],
      low: [5, 6, 15, 16],
      close: [8, 9, 18, 19],
      volume: [1, 1, 1, 1],
    };
    const ctx = new Context(data, 0, program.taSlotCount, 0, 0, 0, {}, 0, program.securityTfs);
    factory(ctx, rt);
    expect(ctx.securityCache[0]!.high).toEqual(new Float64Array([12, 22]));
    expect(ctx.securityCache[0]!.low).toEqual(new Float64Array([5, 15]));
    expect(ctx.securityCache[0]!.close).toEqual(new Float64Array([9, 19]));
    // h=0: prevClose=NaN(첫 HTF 행) -> tr=high-low=12-5=7. h=1: prevClose=cache.close[0]=9(직전
    // *HTF* 바, 차트 타임프레임의 이전 값이 아님) -> tr=max(22-15=7, |22-9|=13, |15-9|=6)=13.
    expect(ctx.securityExprCache[0]).toEqual(new Float64Array([7, 13]));
  });
});

// ── request.security 셋째 슬라이스 서브슬라이스 3c(C182, ROADMAP [hard->분할]) — security.ts
// getFromArray(resolveHtfIndex 공유) + genCallExpr의 securityExprCallSlots 조회 분기. 이 시점부터
// request.security(...) 표현식 콜사이트 호출 자신이 처음으로 값을 반환한다(3b까지는 genCallExpr
// 맨 끝 안전장치 throw가 걸렸다) — 그래서 아래는 generateSecurityExprPreamble을 독립 호출하지 않고
// codegenSource()/transpile()+run()으로 전체 파이프라인을 직접 태운다(3a/3b describe와 다른 지점).
describe("CodeGen request.security() expression call sites (C182, request.security third slice sub-slice 3c)", () => {
  it("emits the HTF prepass preamble followed by rt.security.getFromArray($.securityExprCache[N], $.securityCache[N], $.idx, gaps, lookahead)", () => {
    const code = codegenSource('x = request.security("", "D", ta.sma(close, 2))');
    expect(code).toBe(
      [
        "function __secExpr0() {",
        "const cache = $.securityCache[0];",
        "const out = new Float64Array(cache.close.length);",
        "for (let h = 0; h < out.length; h++) {",
        "const open = cache.open[h], high = cache.high[h], low = cache.low[h], close = cache.close[h], volume = cache.volume[h];",
        "out[h] = rt.ta.sma($.taSlots[0], close, 2);",
        "}",
        "return out;",
        "}",
        "$.securityExprCache[0] = __secExpr0();",
        "var x = rt.security.getFromArray($.securityExprCache[0], $.securityCache[0], $.idx, false, false);",
      ].join("\n"),
    );
  });

  it("emits literal true/false for gaps=/lookahead= kwargs on expression call sites, same as bare-series call sites", () => {
    const code = codegenSource('x = request.security("", "D", ta.sma(close, 2), gaps=true, lookahead=true)');
    expect(code).toContain(
      "var x = rt.security.getFromArray($.securityExprCache[0], $.securityCache[0], $.idx, true, true);",
    );
  });

  it("assigns independent sequential slots to bare-series and expression call sites sharing the same slot pool", () => {
    const code = codegenSource(
      ['a = request.security("", "D", close)', 'b = request.security("", "60", ta.ema(close, 3))'].join("\n"),
    );
    expect(code).toContain('var a = rt.security.get($.securityCache[0], $.idx, "close", false, false);');
    expect(code).toContain("$.securityExprCache[1] = __secExpr1();");
    expect(code).toContain(
      "var b = rt.security.getFromArray($.securityExprCache[1], $.securityCache[1], $.idx, false, false);",
    );
  });

  it("end-to-end: request.security(symbol, tf, ta.sma(close, 2)) re-executes ta.sma over the HTF-native close sequence, not the chart timeframe's", () => {
    // 6바, tf="2"(naive count 폴백, ratio=2) -> barMap=[0,0,1,1,2,2], HTF close(cache.close)=
    // [11,21,31](각 쌍의 마지막 값). HTF-네이티브 sma(length=2): h=0 워밍업 NaN, h=1
    // (11+21)/2=16, h=2 (21+31)/2=26 (tests/unit/codegen.test.ts 3b describe의 hand-verified
    // 실행 테스트와 동일 산식 재사용, 여기선 값만 6바로 확장).
    const source = 'var float x = na\nx := request.security("", "2", ta.sma(close, 2))';
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.securityTfs).toEqual(["2"]);

    const priceData = [10, 11, 20, 21, 30, 31];
    const data: OHLCVData = {
      open: priceData,
      high: priceData,
      low: priceData,
      close: priceData,
      volume: [1, 1, 1, 1, 1, 1],
    };
    const { bars } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
      result.securityTfs,
    );
    // idx0-1: htf_idx<=0(day1 여전히 미확정) -> na. idx2-3: htf_idx=0(day1 확정, sma 워밍업 NaN)
    // -> na. idx4-5: htf_idx=1(day2 확정, sma=16) -> 16.
    expect(bars.map((b) => b["var:x"])).toEqual([NaN, NaN, NaN, NaN, 16, 16]);
  });
});

describe("CodeGen string literal escape sequences (C184, ROADMAP.md L1186 WebSearch-blocked fallback / DIVERGENCES #44)", () => {
  // 렉서(readString)는 pine2py와 동일한 raw-passthrough라 백슬래시+다음글자를 그대로 2글자
  // 보존한다(lexer.ts). 이전까지 codegen(genExpr StringLiteral)이 이 raw 값을 그대로
  // JSON.stringify에 넘겨 실제 실행 시 어떤 이스케이프도 디코딩되지 않는 버그가 있었다(node
  // 직접 실행으로 실측 확인 - 코어 이스케이프 시퀀스가 실제 제어문자가 아니라 백슬래시+글자
  // 2글자 그대로 남았음). pine2py 오라클 대조 결과 TV/Python/JS 세 언어가 이견 없는 코어
  // 4종(개행/역슬래시/작은따옴표/큰따옴표)만 명시적으로 디코딩하도록 수정
  // (decodePineStringEscapes) - TV의 실제 확장 이스케이프 집합(탭/백스페이스/hex 등)은
  // WebSearch 권한이 이번에도 거부돼(C62 재확인) 여전히 미확정이므로 raw 보존 유지.

  it("decodes the newline escape to a real newline character", () => {
    const code = codegenSource("x = \"hello\\nworld\"");
    expect(code).toBe("var x = \"hello\\nworld\";");
  });

  it("decodes the backslash escape to a single literal backslash (not two)", () => {
    const code = codegenSource("x = \"a\\\\b\"");
    expect(code).toBe("var x = \"a\\\\b\";");
  });

  it("decodes the escaped single quote to a literal single quote", () => {
    const code = codegenSource("x = \"it\\'s\"");
    expect(code).toBe("var x = \"it's\";");
  });

  it("decodes the escaped double quote to a literal double quote", () => {
    const code = codegenSource("x = \"say \\\"hi\\\"\"");
    expect(code).toBe("var x = \"say \\\"hi\\\"\";");
  });

  it("leaves non-core tab escape raw (2 chars, undecoded) - TV's extended escape set is unconfirmed", () => {
    const code = codegenSource("x = \"a\\tb\"");
    expect(code).toBe("var x = \"a\\\\tb\";");
  });

  it("leaves non-core word-boundary escape raw (2 chars) so str.match regex patterns keep working (DIVERGENCES #44 regression guard)", () => {
    const code = codegenSource("x = \"\\bword\\b\"");
    expect(code).toBe("var x = \"\\\\bword\\\\b\";");
  });

  it("hand-verified E2E: a string mixing all four core escapes decodes to the real runtime characters end to end", () => {
    const source = ["var string __obs = na", "__obs := \"line1\\nline2 back\\\\slash quote\\'d dquote\\\"d\""].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]?.["var:__obs"]).toBe("line1\nline2 back\\slash quote'd dquote\"d");
  });
});

describe("CodeGen str.tostring() static int/float classification (C201, LIMITATIONS.md 'str.tostring int/float 갭' fix)", () => {
  // isStaticIntExpr(analyzer.ts)는 딱 둘만 정적으로 int로 확정한다: 정수 리터럴(부호 포함) +
  // for 루프 카운터 변수. codegen이 그 콜사이트에만 rt.tostring 셋째 인자 isInt=true를 추가로
  // 싣는다 - 그 외(BinOp/일반 '=' 로컬/bar series 등)는 기존 출력과 한 글자도 다르지 않아야 한다
  // (C129 "기존 입력 패턴에서 출력이 안 바뀌는가" 원칙).

  it("emits isInt=true for a positive integer literal argument", () => {
    const code = codegenSource("x = str.tostring(5)");
    expect(code).toBe("var x = rt.tostring(5, undefined, true);");
  });

  it("emits isInt=true for a negative integer literal argument (UnaryOp('-', NumberLiteral))", () => {
    const code = codegenSource("x = str.tostring(-7)");
    expect(code).toBe("var x = rt.tostring((-7), undefined, true);");
  });

  it("does not emit isInt for a decimal-point float literal (existing output unchanged, C129)", () => {
    const code = codegenSource("x = str.tostring(5.0)");
    expect(code).toBe("var x = rt.tostring(5.0);");
  });

  it("does not emit isInt for a bar series argument (existing output unchanged)", () => {
    const code = codegenSource("x = str.tostring(close)");
    expect(code).toBe("var x = rt.tostring($.close.get(0));");
  });

  it("emits isInt=true for a for-loop counter variable used directly", () => {
    const code = codegenSource(["s = \"\"", "for i = 0 to 4", "    s := str.tostring(i)"].join("\n"));
    expect(code).toContain("rt.tostring(i, undefined, true)");
  });

  it("does not emit isInt for a derived expression built from a loop counter (BinOp, conservative scope boundary)", () => {
    const code = codegenSource(["s = \"\"", "for i = 0 to 4", "    s := str.tostring(i + 1)"].join("\n"));
    expect(code).toContain("rt.tostring((i + 1));");
    expect(code).not.toContain("true)");
  });

  it("keeps a user-supplied format_str slot intact and still appends isInt=true after it (integer format branch is unaffected by isInt either way)", () => {
    const code = codegenSource(["s = \"\"", "for i = 0 to 4", "    s := str.tostring(i, \"integer\")"].join("\n"));
    expect(code).toContain('rt.tostring(i, "integer", true)');
  });

  it("does not leak isInt across unrelated identically-named locals in a sibling scope (no cross-loop name collision)", () => {
    // 서로 다른 두 for 루프가 우연히 같은 카운터 이름(i)을 재사용해도 각자 독립적으로 판정되는지
    // 확인(scope 체인 lookup이 이름이 아니라 스코프 위치로 판별함을 검증) - 둘 다 for 루프
    // 카운터라 실제로는 둘 다 isInt=true여야 정상(오탐이 아니라 참양성 재확인).
    const code = codegenSource(
      ["a = \"\"", "for i = 0 to 2", "    a := str.tostring(i)", "b = \"\"", "for i = 0 to 2", "    b := str.tostring(i)"].join("\n"),
    );
    const matches = code.match(/rt\.tostring\(i, undefined, true\)/g);
    expect(matches).toHaveLength(2);
  });

  it("hand-verified E2E: transpile()+run() reproduces the exact corpus regression (079ae781480a) — 'for i=0 to 4: s+=str.tostring(i)' yields \"01234\" (len 5), not the pre-fix \"0.01.02.03.04.0\" (len 15)", () => {
    const source = [
      "var string __obs = na",
      "s = \"\"",
      "for i = 0 to 4",
      "    s += str.tostring(i)",
      "__obs := s",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    for (const bar of bars) {
      expect(bar["var:__obs"]).toBe("01234");
    }
  });
});

describe("CodeGen str.tostring(value=/format=) kwargs (C403, next_hint(C402) 1순위 — wild kwarg 블랑켓 클러스터 최다 서브클러스터)", () => {
  // analyzer/collections.ts STR_KWARG_PARAM_NAMES.tostring = ["value", "format"](analyzeStrCall 참조)
  // — 이미 오라클/hand-verified로 검증된 위치 인자 폼과 바이트 단위로 동일한 런타임 호출을 emit하는지로
  // 대조한다(ta.pivothigh/atr(C402)와 동일한 hand-verified 원칙). 'format=' 자체는 pine2py 내부
  // 파라미터명이 format_str이라 오라클 불가(oracle/cases/str_tostring_kwargs.pine 주석 참조) — 여기서
  // codegen 동치성으로 그 갭을 메운다.

  it("emits str.tostring(value=) identically to the positional form", () => {
    const code = codegenSource("x = str.tostring(value=close)");
    expect(code).toBe(codegenSource("x = str.tostring(close)"));
  });

  it("emits str.tostring(value=, format=) fully-keyword form identically to the positional form (wild corpus shape, 99e6da977b61.pine)", () => {
    const code = codegenSource('x = str.tostring(value=close, format="#.##")');
    expect(code).toBe(codegenSource('x = str.tostring(close, "#.##")'));
  });

  it("emits str.tostring(close, format=) mixed positional+keyword form identically to the positional form (wild corpus shape, ed39d2f54a30.pine)", () => {
    const code = codegenSource('x = str.tostring(close, format="#.##")');
    expect(code).toBe(codegenSource('x = str.tostring(close, "#.##")'));
  });

  it("still applies the C201 isInt=true wiring when value= is a statically-int literal given by keyword", () => {
    const code = codegenSource("x = str.tostring(value=5)");
    expect(code).toBe(codegenSource("x = str.tostring(5)"));
    expect(code).toBe("var x = rt.tostring(5, undefined, true);");
  });

  it("combines isInt=true with a keyword format= slot identically to the positional form", () => {
    const code = codegenSource('x = str.tostring(value=5, format="integer")');
    expect(code).toBe(codegenSource('x = str.tostring(5, "integer")'));
    expect(code).toContain('rt.tostring(5, "integer", true)');
  });
});

describe("CodeGen str.format_time(time=/format=/timezone=) kwargs (C478, next_hint(C477) 1순위 — wild 잔여 '키워드 인자' 블랑켓 최다빈도)", () => {
  // analyzer/collections.ts STR_KWARG_PARAM_NAMES.format_time = ["time", "format", "timezone"] —
  // 'timezone='만 오라클 가능(oracle/cases/str_format_time_kwargs.pine 참조), 'time='/'format='은
  // pine2py 내부 파라미터명이 time_ms/format_str이라 오라클 불가(str.tostring의 'format='과 동일
  // 원칙) — 이미 검증된 위치 인자 폼과 바이트 단위로 동일한 rt.format_time 호출을 emit하는지로
  // 대조한다.

  it("emits str.format_time(time, format, timezone=) identically to the 3-arg positional form", () => {
    const code = codegenSource('x = str.format_time(1705276800000.0, "yyyy-MM-dd", timezone="America/New_York")');
    expect(code).toBe(codegenSource('x = str.format_time(1705276800000.0, "yyyy-MM-dd", "America/New_York")'));
  });

  it("emits str.format_time(time, timezone=) with format_str slot padded as undefined, identically to omitting format_str", () => {
    const code = codegenSource('x = str.format_time(1705276800000.0, timezone="UTC")');
    expect(code).toBe('var x = rt.format_time(1705276800000.0, undefined, "UTC");');
  });

  it("emits str.format_time(time=, format=, timezone=) fully-keyword form identically to the positional form (wild corpus shape, fab0b2ffba07.pine)", () => {
    const code = codegenSource('x = str.format_time(time=1705276800000.0, format="MM/dd/yyyy", timezone="UTC")');
    expect(code).toBe(codegenSource('x = str.format_time(1705276800000.0, "MM/dd/yyyy", "UTC")'));
  });

  it("emits str.format_time(time=, format=) without timezone identically to the 2-arg positional form (wild corpus shape, fab0b2ffba07.pine)", () => {
    const code = codegenSource('x = str.format_time(time=1705276800000.0, format="MM/dd/yyyy")');
    expect(code).toBe(codegenSource('x = str.format_time(1705276800000.0, "MM/dd/yyyy")'));
  });
});

describe("CodeGen math.abs/round/sign(number=/precision=) kwargs (C404, next_hint(C403) — wild가 실제로 kwarg를 직접 받는 math.* 함수는 이 3종뿐)", () => {
  // analyzer/call-expr.ts MATH_KWARG_PARAM_NAMES(abs/sign=["number"], round=["number","precision"]) —
  // 오라클 불가(pine2py가 어떤 kwarg 이름을 줘도 크래시하는 축, MATH_KWARG_PARAM_NAMES 주석 참조)라
  // 이미 검증된 위치 인자 폼과 바이트 단위로 동일한 런타임 호출을 emit하는지로 대조한다
  // (str.tostring/ta.pivothigh·atr, C402/C403과 동일한 hand-verified 원칙).

  it("emits math.abs(number=) identically to the positional form", () => {
    const code = codegenSource("x = math.abs(number=close)");
    expect(code).toBe(codegenSource("x = math.abs(close)"));
    expect(code).toBe("var x = rt.abs($.close.get(0));");
  });

  it("emits math.sign(number=) identically to the positional form", () => {
    const code = codegenSource("x = math.sign(number=close)");
    expect(code).toBe(codegenSource("x = math.sign(close)"));
  });

  it("emits math.round(number=, precision=) fully-keyword form identically to the positional form (wild corpus shape, fab0b2ffba07.pine)", () => {
    const code = codegenSource("x = math.round(number=close, precision=2)");
    expect(code).toBe(codegenSource("x = math.round(close, 2)"));
  });

  it("emits math.round(close, precision=) mixed positional+keyword form identically to the positional form", () => {
    const code = codegenSource("x = math.round(close, precision=2)");
    expect(code).toBe(codegenSource("x = math.round(close, 2)"));
  });

  it("emits math.round(number=) keyword-only form (precision omitted) identically to the single-arg positional form", () => {
    const code = codegenSource("x = math.round(number=close)");
    expect(code).toBe(codegenSource("x = math.round(close)"));
  });
});

