describe("CodeGen str.tostring() static int/float classification — residual scope (4): '=' local propagation (C205, LIMITATIONS.md 'str.tostring 잔여 스코프')", () => {
  // analyzeAssignment의 '=' 신규 로컬 선언 지점에서 isStaticIntExpr(stmt.value)가 true면
  // scope.numTypeHints에 "int"를 등록한다 - 정수 리터럴을 직접 대입받은 로컬과, for 루프 카운터를
  // 경유한 로컬(체이닝 포함)이 대상. isStaticIntExpr의 Identifier 분기가 scope 체인을 그대로
  // 재귀 조회하므로 별도 로직 없이 다단계 대입까지 전파된다.

  it("emits isInt=true for a '=' local directly assigned an integer literal", () => {
    const code = codegenSource(["n = 5", "x = str.tostring(n)"].join("\n"));
    expect(code).toContain("rt.tostring(n, undefined, true)");
  });

  it("emits isInt=true for a '=' local assigned a for-loop counter", () => {
    const code = codegenSource(["s = \"\"", "for i = 0 to 4", "    n = i", "    s := str.tostring(n)"].join("\n"));
    expect(code).toContain("rt.tostring(n, undefined, true)");
  });

  it("emits isInt=true through a two-level chain of '=' locals ('=' local assigned another int-hinted '=' local)", () => {
    const code = codegenSource(
      ["s = \"\"", "for i = 0 to 4", "    n = i", "    m = n", "    s := str.tostring(m)"].join("\n"),
    );
    expect(code).toContain("rt.tostring(m, undefined, true)");
  });

  it("does not emit isInt for a '=' local assigned a float literal (existing output unchanged, conservative boundary)", () => {
    const code = codegenSource(["n = 5.0", "x = str.tostring(n)"].join("\n"));
    expect(code).toBe("var n = 5.0;\nvar x = rt.tostring(n);");
  });

  it("does not emit isInt for a '=' local assigned a BinOp derived from a loop counter (conservative boundary — the intermediate is not itself int-hinted)", () => {
    const code = codegenSource(
      ["s = \"\"", "for i = 0 to 4", "    n = i + 1", "    m = n", "    s := str.tostring(m)"].join("\n"),
    );
    expect(code).toContain("rt.tostring(m);");
    expect(code).not.toContain("rt.tostring(m, undefined, true)");
  });

  it("does not leak an int hint across unrelated '=' locals sharing the same name in a sibling scope", () => {
    const code = codegenSource(
      ["a = \"\"", "for i = 0 to 2", "    n = i", "    a := str.tostring(n)", "b = 1.5", "y = str.tostring(b)"].join(
        "\n",
      ),
    );
    expect(code).toContain("rt.tostring(n, undefined, true)");
    expect(code).toContain("rt.tostring(b);");
  });

  it("hand-verified E2E: transpile()+run() — a '=' local fed by an int literal renders without a decimal point", () => {
    const source = ["var string __obs = na", "n = 5", "__obs := str.tostring(n)"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    for (const bar of bars) {
      expect(bar["var:__obs"]).toBe("5");
    }
  });

  it("hand-verified E2E: transpile()+run() — a '=' local fed by a for-loop counter (chained through a second '=' local) renders without a decimal point", () => {
    const source = [
      "var string __obs = na",
      "s = \"\"",
      "for i = 0 to 4",
      "    n = i",
      "    m = n",
      "    s += str.tostring(m)",
      "__obs := s",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    for (const bar of bars) {
      expect(bar["var:__obs"]).toBe("01234");
    }
  });
});

describe("CodeGen int()/float()/bool()/string() bare type-cast builtins (C207, LIMITATIONS.md 잔여 스코프 (3))", () => {
  it("emits rt.int/rt.float/rt.bool for the bare casts, and reuses rt.tostring for string()", () => {
    const code = codegenSource(
      ["x1 = int(5.7)", "x2 = float(5)", "x3 = bool(0.0)", "x4 = string(5.7)"].join("\n"),
    );
    expect(code).toContain("rt.int(5.7)");
    expect(code).toContain("rt.float(5)");
    expect(code).toContain("rt.bool(0.0)");
    expect(code).toContain("rt.tostring(5.7)");
  });

  it("string(n) with a statically-int argument reuses the C201 isInt=true wiring (same as str.tostring)", () => {
    const code = codegenSource(["n = 5", "x = string(n)"].join("\n"));
    expect(code).toContain("rt.tostring(n, undefined, true)");
  });

  it("errors on int()/float()/bool()/string() called with the wrong argument count", () => {
    for (const call of ["int()", "int(1, 2)", "float()", "bool(1, 2)", "string()", "string(1, 2)"]) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("a user-declared function named 'int'/'float'/'bool'/'string' shadows the builtin cast (same precedence as nz/input/plot)", () => {
    const code = codegenSource(["int(x) =>", "    x + 1", "y = int(5)"].join("\n"));
    expect(code).not.toContain("rt.int(");
  });

  it("hand-verified E2E: transpile()+run() — int()/float()/bool() truncate toward zero, coerce booleans, and pass na through without crashing", () => {
    const source = [
      "var float __obs_trunc = na",
      "__obs_trunc := int(-2.7)",
      "var float __obs_int_bool = na",
      "__obs_int_bool := int(true)",
      "var float __obs_float_bool = na",
      "__obs_float_bool := float(false)",
      "var bool __obs_bool_num = na",
      "__obs_bool_num := bool(3.2)",
      "var float __obs_int_na = na",
      "__obs_int_na := int(close[5])", // 2바 데이터에서 close[5]는 항상 na(범위 밖)
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    const last = bars[bars.length - 1]!;

    expect(last["var:__obs_trunc"]).toBe(-2);
    expect(last["var:__obs_int_bool"]).toBe(1);
    expect(last["var:__obs_float_bool"]).toBe(0);
    expect(last["var:__obs_bool_num"]).toBe(true);
    expect(Number.isNaN(last["var:__obs_int_na"] as number)).toBe(true);
  });

  it("hand-verified E2E: string(true)/string(false) render Python's capitalized bool repr, matching pine2py's str.tostring(bool) (fix discovered while wiring string() through the shared tostring path — previously untested/broken for bool arguments)", () => {
    const source = [
      "var string __obs_true = na",
      "__obs_true := string(true)",
      "var string __obs_false = na",
      "__obs_false := string(false)",
      "var string __obs_fmt = na",
      '__obs_fmt := str.tostring(true, "percent")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_true"]).toBe("True");
    expect(bars[0]!["var:__obs_false"]).toBe("False");
    expect(bars[0]!["var:__obs_fmt"]).toBe("1.00%");
  });

  it("hand-verified: int(Infinity) returns Infinity instead of crashing — pine2py's pine_int raises OverflowError on this input (DIVERGENCES.md #88, GOAL.md '알려진 버그는 따르지 않는다')", () => {
    expect(rt.int(Infinity)).toBe(Infinity);
    expect(rt.int(-Infinity)).toBe(-Infinity);
  });
});

// ── timestamp() bare builtin (C210, PROGRESS next_hint 1순위 — pine2py wavealgo.timestamp(*args)
// 2-오버로드 literal port, oracle/cases/timestamp_basic.pine으로 y/m/d 조합 실측 검증됨). 여기서는
// codegen 방출 형태 + 오라클로 못 덮는 축(인자 개수 에러/na 인자/기본값 경계)만 hand-verified로 보강.
describe("CodeGen timestamp() bare builtin (C210)", () => {
  it("emits rt.timestamp(...) with all positional args passed through unchanged", () => {
    const code = codegenSource(["t = timestamp(2024, 1, 15, 12, 0, 0)"].join("\n"));
    expect(code).toContain("rt.timestamp(2024, 1, 15, 12, 0, 0)");
  });

  it("errors on timestamp() called with fewer than 3 or more than 7 args", () => {
    for (const call of ["timestamp()", "timestamp(2024)", "timestamp(2024, 1)", "timestamp(1, 2, 3, 4, 5, 6, 7, 8)"]) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("does not require top-level statement position — usable inside expressions/conditionals (unlike plot/hline)", () => {
    const prog = analyze(parse(["t = timestamp(2024, 1, 1)", "if close > 0", "    x = timestamp(2024, 1, 1)"].join("\n")));
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified: rt.timestamp(y,m,d) matches the pine2py golden for a plain UTC date (no time-of-day)", () => {
    expect(rt.timestamp(2024, 1, 15)).toBe(1705276800000);
  });

  it("hand-verified: the timezone-string overload ignores tz entirely and always computes as UTC (matches pine2py exactly — tz_str is unpacked but never consumed)", () => {
    expect(rt.timestamp("Asia/Seoul", 2024, 1, 15, 12, 30, 45)).toBe(rt.timestamp(2024, 1, 15, 12, 30, 45));
    expect(rt.timestamp("America/New_York", 2024, 1, 15)).toBe(rt.timestamp(2024, 1, 15));
  });

  it("hand-verified: the tz-string overload defaults day to 1 when omitted, matching pine2py's asymmetric default (plain overload has no such default — day is required there)", () => {
    expect(rt.timestamp("UTC", 2024, 6)).toBe(rt.timestamp(2024, 6, 1));
  });

  it("hand-verified: na (NaN) arguments propagate to NaN instead of crashing — deliberate divergence from pine2py's TypeError on non-int datetime() args, a CPython int-vs-float type-system artifact rather than a real TV semantic (DIVERGENCES.md; not oracle-verifiable, TV 미검증(가설))", () => {
    expect(Number.isNaN(rt.timestamp(NaN, 1, 15))).toBe(true);
    expect(Number.isNaN(rt.timestamp(2024, 1, NaN))).toBe(true);
  });

  it("hand-verified: fewer than 3 total args returns 0, matching pine2py's fallback (unreachable via normal codegen — analyzer rejects <3 args — but rt.timestamp itself mirrors the exact python source)", () => {
    expect(rt.timestamp()).toBe(0);
    expect(rt.timestamp(2024)).toBe(0);
  });
});

// ── timestamp(dateString) 1-인자 오버로드 (C289, wild 최다빈도 클러스터 259건 — pine2py 오라클
// 구조적 불가라 hand-verified 전용, LIMITATIONS.md C269/C289 참조).
describe("CodeGen timestamp(dateString) 1-arg overload (C289)", () => {
  it("accepts a single string-literal argument at analyze time (StringLiteral only)", () => {
    const prog = analyze(parse('x = timestamp("2024-01-01")'));
    expect(prog.errors).toEqual([]);
  });

  it("still rejects a single non-string-literal argument (preserves timestamp(2024) contract)", () => {
    for (const call of ["timestamp(2024)", "timestamp(x)"]) {
      const prog = analyze(parse(`x = 5\ny = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("still rejects 0/2/8-arg calls (dateString exception is exactly 1-arg-string-literal, not a general relaxation)", () => {
    for (const call of ["timestamp()", "timestamp(2024, 1)", "timestamp(1, 2, 3, 4, 5, 6, 7, 8)"]) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("emits rt.timestamp(\"...\") passthrough for a string-literal dateString call", () => {
    const code = codegenSource(['t = timestamp("2024-01-01")'].join("\n"));
    expect(code).toContain('rt.timestamp("2024-01-01")');
  });

  it("hand-verified: ISO date-only string parses as UTC midnight", () => {
    expect(rt.timestamp("2024-01-15")).toBe(rt.timestamp(2024, 1, 15));
  });

  it("hand-verified: ISO datetime with T separator and seconds", () => {
    expect(rt.timestamp("2024-01-15T12:30:45")).toBe(rt.timestamp(2024, 1, 15, 12, 30, 45));
  });

  it("hand-verified: ISO datetime with space separator, no seconds", () => {
    expect(rt.timestamp("2024-01-15 12:30")).toBe(rt.timestamp(2024, 1, 15, 12, 30, 0));
  });

  it("hand-verified: ISO datetime with explicit UTC offset shifts the epoch by the offset", () => {
    // "-06:00" local wall-clock 00:00 == 06:00 UTC same day.
    expect(rt.timestamp("2024-01-15T00:00:00-06:00")).toBe(rt.timestamp(2024, 1, 15, 6, 0, 0));
    expect(rt.timestamp("2024-01-15T06:00:00+0900")).toBe(rt.timestamp(2024, 1, 14, 21, 0, 0));
  });

  it("hand-verified: ISO datetime with Z or UTC suffix is equivalent to no suffix", () => {
    expect(rt.timestamp("2024-01-15T12:00:00Z")).toBe(rt.timestamp("2024-01-15T12:00:00"));
    expect(rt.timestamp("2024-01-15T12:00:00 UTC")).toBe(rt.timestamp("2024-01-15T12:00:00"));
  });

  it("hand-verified: RFC-style 'D Mon YYYY[ HH:mm[:ss]]' with abbreviated or full month name", () => {
    expect(rt.timestamp("1 Jan 2022 00:00")).toBe(rt.timestamp(2022, 1, 1, 0, 0));
    expect(rt.timestamp("1 July 2024")).toBe(rt.timestamp(2024, 7, 1));
    expect(rt.timestamp("01 Jan 2022 00:00 +0000")).toBe(rt.timestamp(2022, 1, 1, 0, 0));
  });

  it("hand-verified: RFC-style with an explicit offset shifts the epoch (matches ISO offset handling)", () => {
    expect(rt.timestamp("1 Jan 2022 00:00 -0600")).toBe(rt.timestamp(2022, 1, 1, 6, 0, 0));
  });

  it("hand-verified: month-name matching is case-insensitive", () => {
    expect(rt.timestamp("1 jan 2022")).toBe(rt.timestamp("1 Jan 2022"));
  });

  it("hand-verified: unparseable date strings return NaN (na) rather than crashing", () => {
    expect(Number.isNaN(rt.timestamp("not a date"))).toBe(true);
    expect(Number.isNaN(rt.timestamp("2024/01/15"))).toBe(true);
  });
});

// ── timestamp(...) kwargs (C406, next_hint(C405) 1순위) — pine2py wavealgo.timestamp(*args)는
// 순수 위치 전용(python 직접 실행 재확인, `def timestamp(*args)`가 어떤 키워드 이름도 구조적으로
// 못 받음)이라 100% 오라클 불가, 이미 오라클 검증된 위치 인자 폼과 바이트 단위로 동일한 런타임
// 호출을 emit하는지로 대조하는 codegen 동치성 hand-verified 전용(math.*, C404와 동일 원칙).
// analyzer/call-expr.ts resolveTimestampKwargSlots 참조 — timezone 유무로 슬롯 표 자체가 동적으로
// 바뀐다(맨 앞이 tz면 TIMESTAMP_WITH_TZ_SLOTS, 아니면 TIMESTAMP_WITHOUT_TZ_SLOTS).
describe("CodeGen timestamp(...) kwargs (C406, next_hint(C405) 1순위)", () => {
  it("emits timestamp(dateString=) identically to the string-literal positional form (wild corpus shape, 8977083b1183.pine)", () => {
    const code = codegenSource('t = timestamp(dateString = "2024-01-01T00:00:00")');
    expect(code).toBe(codegenSource('t = timestamp("2024-01-01T00:00:00")'));
    expect(code).toBe('var t = rt.timestamp("2024-01-01T00:00:00");');
  });

  it("rejects a non-string-literal dateString= value (preserves the compile-time-literal constraint)", () => {
    const prog = analyze(parse('x = "2024-01-01"\ny = timestamp(dateString = x)'));
    expect(prog.errors.some((e) => e.includes("'dateString' 인자는 컴파일타임 문자열 리터럴만 지원"))).toBe(true);
  });

  it("emits the positional-tz + full-keyword-rest form identically to the all-positional form (wild corpus shape, 30851f34b5cf.pine)", () => {
    const code = codegenSource(
      "t = timestamp(syminfo.timezone, year = 2024, month = 1, day = 1, minute = 0, hour = 0, second = 0)",
    );
    expect(code).toBe(codegenSource("t = timestamp(syminfo.timezone, 2024, 1, 1, 0, 0, 0)"));
  });

  it("emits the full-keyword-with-timezone form identically to the positional-tz form (wild corpus shape, 99e6da977b61.pine)", () => {
    const code = codegenSource(
      't = timestamp(timezone = "America/New_York", year = 2024, month = 1, day = 1, hour = 9, minute = 30)',
    );
    expect(code).toBe(codegenSource('t = timestamp("America/New_York", 2024, 1, 1, 9, 30)'));
  });

  it("emits the full-keyword-without-timezone form identically to the positional form (wild corpus shape, 40ab1296349a.pine t2)", () => {
    const code = codegenSource("t = timestamp(year=2024, month=1, day=1, hour=0, minute=0, second=0)");
    expect(code).toBe(codegenSource("t = timestamp(2024, 1, 1, 0, 0, 0)"));
  });

  it("is insensitive to keyword argument order (wild corpus shape, 40ab1296349a.pine t3 — fully reversed order)", () => {
    const forward = codegenSource("t = timestamp(year=2024, month=1, day=1, hour=0, minute=0, second=0)");
    const reversed = codegenSource("t = timestamp(second=0, minute=0, hour=0, day=1, month=1, year=2024)");
    expect(reversed).toBe(forward);
  });

  it("a trailing optional keyword (minute/second) can be omitted, defaulting exactly like the shorter positional form (wild corpus shape, 9ad2d55c553d.pine — no second given)", () => {
    const code = codegenSource('t = timestamp(timezone = "America/New_York", year = 2024, month = 1, day = 1, hour = 9, minute = 30)');
    expect(code).toBe(codegenSource('t = timestamp("America/New_York", 2024, 1, 1, 9, 30)'));
  });

  it("does not affect existing pure-positional timestamp() call sites (no kwargs branch — output unchanged)", () => {
    const code = codegenSource("t = timestamp(2024, 1, 15, 12, 0, 0)");
    expect(code).toBe("var t = rt.timestamp(2024, 1, 15, 12, 0, 0);");
  });

  it("errors on an unknown keyword argument name", () => {
    const prog = analyze(parse("x = timestamp(year=2024, month=1, day=1, bogus=1)"));
    expect(prog.errors.some((e) => e.includes("'timestamp'에 없는 인자 이름: 'bogus'"))).toBe(true);
  });

  it("rejects year given both positionally and as a keyword (positional-tz form)", () => {
    const prog = analyze(parse("x = timestamp(syminfo.timezone, 2024, year=2025, month=1, day=1)"));
    expect(prog.errors.some((e) => e.includes("'year'이(가) 위치 인자와 키워드 인자로 중복 지정됨"))).toBe(true);
  });

  it("rejects a duplicate keyword argument", () => {
    const prog = analyze(parse("x = timestamp(year=2024, month=1, day=1, day=2)"));
    expect(prog.errors.some((e) => e.includes("키워드 인자 'day' 중복 지정"))).toBe(true);
  });

  it("rejects timestamp(...) missing a required year argument", () => {
    const prog = analyze(parse("x = timestamp(month=1, day=1)"));
    expect(prog.errors.some((e) => e.includes("'timestamp' 호출에는 'year' 인자가 필요"))).toBe(true);
  });

  it("rejects a hole left when an earlier slot is skipped but a later one is named (day omitted, hour named)", () => {
    const prog = analyze(parse("x = timestamp(year=2024, month=1, hour=9)"));
    expect(prog.errors.some((e) => e.includes("'timestamp' 호출에 'day' 인자가 누락됨(뒤 인자가 이름으로 지정됨)"))).toBe(true);
  });

  it("allows timestamp(...) kwargs inside a conditional if-body (stateless, same as nz/na)", () => {
    const prog = analyze(parse('if close > open\n    x = timestamp(year=2024, month=1, day=1)'));
    expect(prog.errors).toEqual([]);
  });
});

// ── time(timeframe[, session[, timezone]]) 호출형 bare builtin (C299, wild 3위 클러스터 "알 수
// 없는 함수 호출"의 지배 함수 — 510건 중 443건). bare 무인자 `time`(TIME_VAR_NAMES, $.barTimeMs)과
// 별개 — pine2py에 대응 구현이 전혀 없어 오라클 구조적 불가, runtime/time.ts 헤더 참조로 전부
// hand-verified(DIVERGENCES.md 'TV 미검증(가설)').
describe("CodeGen time() bare builtin (C299)", () => {
  it("emits rt.time.resolve(...) with $.barTimeMs injected as the first arg (1-arg form)", () => {
    const code = codegenSource(['t = time("D")'].join("\n"));
    expect(code).toContain('rt.time.resolve($.barTimeMs, "D")');
  });

  it("emits rt.time.resolve(...) with $.barTimeMs injected first, positional args unshifted after it (2/3-arg forms)", () => {
    expect(codegenSource(['t = time("D", "0930-1600")'].join("\n"))).toContain(
      'rt.time.resolve($.barTimeMs, "D", "0930-1600")',
    );
    expect(codegenSource(['t = time("D", "0930-1600", "America/New_York")'].join("\n"))).toContain(
      'rt.time.resolve($.barTimeMs, "D", "0930-1600", "America/New_York")',
    );
  });

  it("errors on time() called with 0 or 5+ args", () => {
    for (const call of ['time()', 'time("D", "0930-1600", "UTC", 1, "extra")']) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("accepts a 4th positional bars_back argument (C727, wild 4th-positional-arg form)", () => {
    const prog = analyze(parse('x = time("D", "0930-1600", "UTC", 1)'));
    expect(prog.errors).toEqual([]);
  });

  it("does not require top-level statement position — usable inside expressions/conditionals", () => {
    const prog = analyze(parse(['t = time("D")', "if close > 0", '    x = time("D", "0930-1600")'].join("\n")));
    expect(prog.errors).toEqual([]);
  });

  it("accepts arbitrary runtime expressions for all three args (no compile-time-literal constraint, unlike request.security's tf)", () => {
    const prog = analyze(
      parse(
        [
          'sess = "0930-1600"',
          'tz = "America/New_York"',
          "x = time(timeframe.period, sess, tz)",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified: 1-arg form returns the UTC calendar-day start for tf='D'", () => {
    const bar = Date.UTC(2024, 0, 15, 14, 30, 0);
    expect(rt.time.resolve(bar, "D")).toBe(Date.UTC(2024, 0, 15));
  });

  it("hand-verified: 1-arg form returns the ISO week (Monday) start for tf='W'", () => {
    // 2024-01-18 is a Thursday; the ISO week it belongs to starts Monday 2024-01-15.
    const bar = Date.UTC(2024, 0, 18, 9, 0, 0);
    expect(rt.time.resolve(bar, "W")).toBe(Date.UTC(2024, 0, 15));
  });

  it("hand-verified: 1-arg form returns the calendar-month start for tf='M'", () => {
    const bar = Date.UTC(2024, 2, 20, 23, 59, 0);
    expect(rt.time.resolve(bar, "M")).toBe(Date.UTC(2024, 2, 1));
  });

  it("hand-verified: 1-arg form floors intraday tf strings to an epoch-aligned boundary (e.g. '60' == hourly)", () => {
    const bar = Date.UTC(2024, 0, 15, 14, 45, 0);
    expect(rt.time.resolve(bar, "60")).toBe(Date.UTC(2024, 0, 15, 14, 0, 0));
  });

  it("hand-verified: 2-arg form returns na (NaN) outside the given HHMM-HHMM session, the resolved time inside it", () => {
    const before = Date.UTC(2024, 0, 15, 9, 0, 0); // 09:00, before 09:30 session start
    const inside = Date.UTC(2024, 0, 15, 9, 45, 0); // 09:45
    const after = Date.UTC(2024, 0, 15, 16, 30, 0); // 16:30, after 16:00 session end
    expect(Number.isNaN(rt.time.resolve(before, "D", "0930-1600"))).toBe(true);
    expect(rt.time.resolve(inside, "D", "0930-1600")).toBe(Date.UTC(2024, 0, 15));
    expect(Number.isNaN(rt.time.resolve(after, "D", "0930-1600"))).toBe(true);
  });

  it("hand-verified: session day-of-week suffix (':23456' == Mon-Fri) excludes weekend bars at the same time-of-day", () => {
    // 2024-01-15 Mon, 2024-01-20 Sat, 2024-01-21 Sun, all at 09:00 UTC.
    const mon = Date.UTC(2024, 0, 15, 9, 0, 0);
    const sat = Date.UTC(2024, 0, 20, 9, 0, 0);
    const sun = Date.UTC(2024, 0, 21, 9, 0, 0);
    expect(Number.isNaN(rt.time.resolve(mon, "D", "0800-1000:23456"))).toBe(false);
    expect(Number.isNaN(rt.time.resolve(sat, "D", "0800-1000:23456"))).toBe(true);
    expect(Number.isNaN(rt.time.resolve(sun, "D", "0800-1000:23456"))).toBe(true);
  });

  it("hand-verified: overnight-wrapping sessions (start > end, e.g. '2200-0600') match both sides of midnight", () => {
    const lateNight = Date.UTC(2024, 0, 15, 23, 0, 0);
    const midday = Date.UTC(2024, 0, 15, 12, 0, 0);
    expect(Number.isNaN(rt.time.resolve(lateNight, "D", "2200-0600"))).toBe(false);
    expect(Number.isNaN(rt.time.resolve(midday, "D", "2200-0600"))).toBe(true);
  });

  it("hand-verified: '24x7' (wild literal, crypto round-the-clock idiom) always matches regardless of time", () => {
    expect(Number.isNaN(rt.time.resolve(Date.UTC(2024, 0, 15, 3, 0, 0), "D", "24x7"))).toBe(false);
    expect(Number.isNaN(rt.time.resolve(Date.UTC(2024, 0, 21, 23, 59, 0), "D", "24x7"))).toBe(false);
  });

  it("hand-verified: '0000-0000' (equal start/end, syminfo.session's own round-the-clock convention) means the full day, not zero-width", () => {
    expect(Number.isNaN(rt.time.resolve(Date.UTC(2024, 0, 15, 3, 0, 0), "D", "0000-0000"))).toBe(false);
    expect(Number.isNaN(rt.time.resolve(Date.UTC(2024, 0, 15, 23, 59, 0), "D", "0000-0000"))).toBe(false);
  });

  it("hand-verified: '2400' as a range endpoint normalizes to midnight (e.g. '2400-0700' == '0000-0700')", () => {
    expect(rt.time.resolve(Date.UTC(2024, 0, 15, 3, 0, 0), "D", "2400-0700")).toBe(
      rt.time.resolve(Date.UTC(2024, 0, 15, 3, 0, 0), "D", "0000-0700"),
    );
  });

  it("hand-verified: comma-separated multi-session strings match if ANY sub-range matches", () => {
    const morning = Date.UTC(2024, 0, 15, 9, 30, 0);
    const midday = Date.UTC(2024, 0, 15, 12, 0, 0);
    const afternoon = Date.UTC(2024, 0, 15, 14, 30, 0);
    const session = "0900-1000,1400-1500";
    expect(Number.isNaN(rt.time.resolve(morning, "D", session))).toBe(false);
    expect(Number.isNaN(rt.time.resolve(midday, "D", session))).toBe(true);
    expect(Number.isNaN(rt.time.resolve(afternoon, "D", session))).toBe(false);
  });

  it("hand-verified: an empty/malformed session string is treated as no restriction rather than crashing", () => {
    const bar = Date.UTC(2024, 0, 15, 3, 0, 0);
    expect(Number.isNaN(rt.time.resolve(bar, "D", ""))).toBe(false);
    expect(Number.isNaN(rt.time.resolve(bar, "D", "not-a-session"))).toBe(false);
  });

  it("hand-verified: the timezone argument is accepted but does not affect the result (same divergence datetime.ts already documents for hour/minute/dayofweek — UTC-fixed)", () => {
    const bar = Date.UTC(2024, 0, 15, 9, 45, 0);
    expect(rt.time.resolve(bar, "D", "0930-1600", "America/New_York")).toBe(rt.time.resolve(bar, "D", "0930-1600"));
    expect(rt.time.resolve(bar, "D", "0930-1600", "Asia/Seoul")).toBe(rt.time.resolve(bar, "D", "0930-1600"));
  });

  it("hand-verified: barTimeMs===0 (no time channel, datetime.ts sentinel) returns na", () => {
    expect(Number.isNaN(rt.time.resolve(0, "D"))).toBe(true);
    expect(Number.isNaN(rt.time.resolve(0, "D", "0930-1600"))).toBe(true);
  });

  it("hand-verified E2E: the common 'in regular trading hours' idiom (time(timeframe.period, session)) correctly gates bars inside/outside the session across a real bar-by-bar run", () => {
    const source = [
      "var float __obs_x = na",
      '__obs_x := time(timeframe.period, "0930-1600")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const day = Date.UTC(2024, 0, 15);
    const time = [day + 9 * 3600000, day + 9 * 3600000 + 45 * 60000, day + 16 * 3600000 + 30 * 60000];
    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(Number.isNaN(bars[0]!["var:__obs_x"] as number)).toBe(true); // 09:00, before session
    expect(bars[1]!["var:__obs_x"]).toBe(day); // 09:45, inside session -> timeframe.period="D" folds to day start
    expect(Number.isNaN(bars[2]!["var:__obs_x"] as number)).toBe(true); // 16:30, after session
  });

  // ── C575: na 인자(wild `time(na)` 관용구) — genExpr(NaLiteral)의 범용 경로는 항상 스칼라 NaN을
  // 내지만 time()의 세 인자는 전부 string 타입이라 GOAL.md 규약대로 null로 낮춰야 한다(colorCast
  // 분기와 동일 사정). 이전에는 NaN이 그대로 rt.time.resolve의 timeframe 인자로 흘러
  // parseTfMinutes(NaN).trim()이 "tf.trim is not a function"으로 죽었다(corpus_scan --exec 실측,
  // wild 81fc082cc6d3.pine) — codegen이 NaLiteral을 "null"로 방출하도록, runtime이 null timeframe을
  // na 전파(NaN)로 처리하도록 함께 수정.
  it("C575: emits null (not NaN) for a na literal argument, since timeframe/session/timezone are all string-typed", () => {
    expect(codegenSource('t = time(na)')).toContain("rt.time.resolve($.barTimeMs, null)");
    expect(codegenSource('t = time("D", na)')).toContain('rt.time.resolve($.barTimeMs, "D", null)');
    expect(codegenSource('t = time("D", "0930-1600", na)')).toContain(
      'rt.time.resolve($.barTimeMs, "D", "0930-1600", null)',
    );
  });

  it("C575: hand-verified — a null (na) timeframe propagates to na (NaN) instead of crashing", () => {
    expect(Number.isNaN(rt.time.resolve(Date.UTC(2024, 0, 15), null))).toBe(true);
  });

  it("C575: hand-verified — a null (na) session is treated as no restriction, same as an empty/malformed session string", () => {
    const bar = Date.UTC(2024, 0, 15, 3, 0, 0);
    expect(rt.time.resolve(bar, "D", null)).toBe(rt.time.resolve(bar, "D", ""));
  });

  it("C575: hand-verified E2E: time(na) runs to completion (no crash) and yields na on every bar", () => {
    const source = ["var float __obs_x = na", "__obs_x := time(na)"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const close = [1, 2, 3];
    const time = [Date.UTC(2024, 0, 15), Date.UTC(2024, 0, 16), Date.UTC(2024, 0, 17)];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    for (const bar of bars) expect(Number.isNaN(bar["var:__obs_x"] as number)).toBe(true);
  });
});

// ── time_close(timeframe[, session[, timezone]]) 호출형 bare builtin (C400, wild "알 수 없는 함수
// 호출" 클러스터 재세분화 1위 — 61건 중 19건, 전수 순수 위치 인자). time()(C299)의 직접 형제 — bare
// 무인자 `time_close`(TIME_VAR_NAMES, $.timeCloseMs)와 별개인 호출형. pine2py에 대응 구현이 전혀
// 없어 오라클 구조적 불가, runtime/time.ts resolveClose 헤더 참조로 전부 hand-verified
// (DIVERGENCES.md 'TV 미검증(가설)'). resolve()와 다른 점은 periodStartMs 대신 periodEndMs 하나뿐 —
// 세션/na/timezone-무시 정책은 완전히 동일해 그 축의 회귀 테스트는 반복하지 않고 period-end 계산과
// 위임 배선만 검증한다.
describe("CodeGen time_close() bare builtin (C400)", () => {
  it("emits rt.time.resolveClose(...) with $.barTimeMs injected as the first arg (1-arg form)", () => {
    const code = codegenSource(['t = time_close("D")'].join("\n"));
    expect(code).toContain('rt.time.resolveClose($.barTimeMs, "D")');
  });

  it("emits rt.time.resolveClose(...) with $.barTimeMs injected first, positional args unshifted after it (2/3-arg forms)", () => {
    expect(codegenSource(['t = time_close("D", "0930-1600")'].join("\n"))).toContain(
      'rt.time.resolveClose($.barTimeMs, "D", "0930-1600")',
    );
    expect(codegenSource(['t = time_close("D", "0930-1600", "America/New_York")'].join("\n"))).toContain(
      'rt.time.resolveClose($.barTimeMs, "D", "0930-1600", "America/New_York")',
    );
  });

  it("errors on time_close() called with 0 or 5+ args", () => {
    for (const call of ['time_close()', 'time_close("D", "0930-1600", "UTC", 1, "extra")']) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("accepts a 4th positional bars_back argument (C727, same as time())", () => {
    const prog = analyze(parse('x = time_close("D", "0930-1600", "UTC", 1)'));
    expect(prog.errors).toEqual([]);
  });

  it("does not require top-level statement position — usable inside expressions/conditionals", () => {
    const prog = analyze(parse(['t = time_close("D")', "if close > 0", '    x = time_close("D", "0930-1600")'].join("\n")));
    expect(prog.errors).toEqual([]);
  });

  it("accepts arbitrary runtime expressions for all three args (no compile-time-literal constraint, unlike request.security's tf)", () => {
    const prog = analyze(
      parse(
        [
          'sess = "0930-1600"',
          'tz = "America/New_York"',
          "x = time_close(timeframe.period, sess, tz)",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified: 1-arg form returns the UTC calendar-day END for tf='D' (period start + 1 day, unlike time()'s start)", () => {
    const bar = Date.UTC(2024, 0, 15, 14, 30, 0);
    expect(rt.time.resolveClose(bar, "D")).toBe(Date.UTC(2024, 0, 16));
  });

  it("hand-verified: 1-arg form returns the ISO week (next Monday) end for tf='W'", () => {
    // 2024-01-18 is a Thursday; the ISO week it belongs to starts Monday 2024-01-15 and ends Monday 2024-01-22.
    const bar = Date.UTC(2024, 0, 18, 9, 0, 0);
    expect(rt.time.resolveClose(bar, "W")).toBe(Date.UTC(2024, 0, 22));
  });

  it("hand-verified: 1-arg form returns the calendar-month end (1st of next month, handles variable month length) for tf='M'", () => {
    const feb = Date.UTC(2024, 1, 20, 23, 59, 0); // 2024 is a leap year (Feb has 29 days)
    expect(rt.time.resolveClose(feb, "M")).toBe(Date.UTC(2024, 2, 1));
    const dec = Date.UTC(2024, 11, 15, 0, 0, 0);
    expect(rt.time.resolveClose(dec, "M")).toBe(Date.UTC(2025, 0, 1)); // year rollover
  });

  it("hand-verified: 1-arg form returns the epoch-aligned boundary end for intraday tf strings (e.g. '60' == hourly)", () => {
    const bar = Date.UTC(2024, 0, 15, 14, 45, 0);
    expect(rt.time.resolveClose(bar, "60")).toBe(Date.UTC(2024, 0, 15, 15, 0, 0));
  });

  it("hand-verified: 2-arg form returns na (NaN) outside the given session, the resolved period-end time inside it (session check uses the bar's own actual time, not the returned value)", () => {
    const before = Date.UTC(2024, 0, 15, 9, 0, 0); // 09:00, before 09:30 session start
    const inside = Date.UTC(2024, 0, 15, 9, 45, 0); // 09:45
    const after = Date.UTC(2024, 0, 15, 16, 30, 0); // 16:30, after 16:00 session end
    expect(Number.isNaN(rt.time.resolveClose(before, "D", "0930-1600"))).toBe(true);
    expect(rt.time.resolveClose(inside, "D", "0930-1600")).toBe(Date.UTC(2024, 0, 16));
    expect(Number.isNaN(rt.time.resolveClose(after, "D", "0930-1600"))).toBe(true);
  });

  it("hand-verified: the timezone argument is accepted but does not affect the result (same divergence as time(), UTC-fixed)", () => {
    const bar = Date.UTC(2024, 0, 15, 9, 45, 0);
    expect(rt.time.resolveClose(bar, "D", "0930-1600", "America/New_York")).toBe(
      rt.time.resolveClose(bar, "D", "0930-1600"),
    );
  });

  it("hand-verified: barTimeMs===0 (no time channel, datetime.ts sentinel) returns na", () => {
    expect(Number.isNaN(rt.time.resolveClose(0, "D"))).toBe(true);
    expect(Number.isNaN(rt.time.resolveClose(0, "D", "0930-1600"))).toBe(true);
  });

  it("hand-verified: tfMs defensive fallback (numeric tf<=0, e.g. '0') returns the bar's own time unchanged, mirroring periodStartMs's fallback rather than crashing (unrecognized non-numeric strings like 'not-a-tf' instead default to a 1440-minute/daily block via parseTfMinutes, not this fallback)", () => {
    const bar = Date.UTC(2024, 0, 15, 14, 30, 0);
    expect(rt.time.resolveClose(bar, "0")).toBe(bar);
  });

  it("C575: emits null (not NaN) for a na literal argument, and a null (na) timeframe propagates to na (NaN) — same fix/policy as time(), see that describe block for the full rationale", () => {
    expect(codegenSource('t = time_close(na)')).toContain("rt.time.resolveClose($.barTimeMs, null)");
    expect(Number.isNaN(rt.time.resolveClose(Date.UTC(2024, 0, 15), null))).toBe(true);
  });

  it("hand-verified E2E: time_close(timeframe.period) yields the next-day boundary across a real bar-by-bar run, contrasting with time()'s same-day start", () => {
    const source = [
      "var float __obs_close = na",
      "var float __obs_open = na",
      '__obs_close := time_close(timeframe.period)',
      '__obs_open := time(timeframe.period)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const day = Date.UTC(2024, 0, 15);
    const time = [day + 9 * 3600000];
    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_open"]).toBe(day);
    expect(bars[0]!["var:__obs_close"]).toBe(day + 86400000);
  });
});

// ── time()/time_close(timeframe=/session=/timezone=/bars_back=) 키워드 인자 폼 (C475/C727, next_hint
// (C474) 지시대로 잔여 '키워드 인자' 클러스터 재세분화 1위 — wild 8개 파일 중 5개가 완전/부분 키워드
// 폼). 위치 인자와 완전히 같은 순서(timeframe, session, timezone, bars_back)의 순수 문법 확장 —
// pine2py엔 time() 함수 자체가 없어(C299) 이 축은 원래도 hand-verified(DIVERGENCES.md 'TV
// 미검증(가설)'). bars_back=은 C727(배치37 지시)에서 wild 9개 파일 실측으로 TV v6 실제 시그니처임을
// 재확정해 지원 추가(과거 거부 결정 번복, DIVERGENCES #219) — 전용 describe 블록(아래) 참조.
describe("CodeGen time()/time_close() keyword-argument form (C475)", () => {
  it("time(timeframe=...) full-kwarg 1-arg form emits the same code as the positional form", () => {
    expect(codegenSource(['t = time(timeframe="D")'].join("\n"))).toContain('rt.time.resolve($.barTimeMs, "D")');
  });

  it("time(timeframe=..., session=..., timezone=...) full-kwarg 3-arg form emits the same code as the positional form", () => {
    expect(
      codegenSource(['t = time(timeframe="D", session="0930-1600", timezone="America/New_York")'].join("\n")),
    ).toContain('rt.time.resolve($.barTimeMs, "D", "0930-1600", "America/New_York")');
  });

  it("time(timeframe.period, session=...) mixed positional+kwarg form fills the session slot", () => {
    expect(codegenSource(['t = time(timeframe.period, session="0930-1600")'].join("\n"))).toContain(
      'rt.time.resolve($.barTimeMs, "D", "0930-1600")',
    );
  });

  it("time_close(timeframe=...) full-kwarg form emits rt.time.resolveClose(...)", () => {
    expect(codegenSource(['t = time_close(timeframe="D")'].join("\n"))).toContain(
      'rt.time.resolveClose($.barTimeMs, "D")',
    );
  });

  it("accepts kwargs in any declaration order (session=/timeframe= reversed)", () => {
    expect(codegenSource(['t = time(session="0930-1600", timeframe="D")'].join("\n"))).toContain(
      'rt.time.resolve($.barTimeMs, "D", "0930-1600")',
    );
  });

  it("rejects an unknown keyword argument name (e.g. foo=, still not part of the 4-slot signature)", () => {
    for (const call of ['time(timeframe.period, foo = -1)', 'time_close("", foo = 1)']) {
      const prog = analyze(parse(`x = ${call}`));
      expect(
        prog.errors.some((e) => e.includes("키워드 인자는 'timeframe='/'session='/'timezone='/'bars_back='만 지원")),
      ).toBe(true);
    }
  });

  it("accepts bars_back= as a keyword argument (C727, was rejected — TV v6 4th signature slot, wild 4 files)", () => {
    for (const call of ['time(timeframe.period, bars_back = -1)', 'time_close("", bars_back = 1)']) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors).toEqual([]);
    }
  });

  it("rejects timeframe specified both positionally and by keyword", () => {
    const prog = analyze(parse('x = time("D", timeframe="60")'));
    expect(prog.errors.some((e) => e.includes("위치 인자와 키워드 인자로 중복 지정됨"))).toBe(true);
  });

  it("accepts timeframe specified both positionally and by keyword when syntactically identical (C654)", () => {
    const prog = analyze(parse('x = time("D", timeframe="D")'));
    expect(prog.errors.some((e) => e.includes("위치 인자와 키워드 인자로 중복 지정됨"))).toBe(false);
  });

  it("rejects a kwarg-only call missing the required timeframe argument", () => {
    const prog = analyze(parse('x = time(session="0930-1600")'));
    expect(prog.errors.some((e) => e.includes("'timeframe' 인자가 필요"))).toBe(true);
  });

  it("hand-verified E2E: full triple-kwarg form gates a session identically to the positional form", () => {
    const source = [
      "var float __obs_x = na",
      '__obs_x := time(timeframe=timeframe.period, session="0930-1600", timezone="UTC")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const day = Date.UTC(2024, 0, 15);
    const time = [day + 9 * 3600000, day + 9 * 3600000 + 45 * 60000, day + 16 * 3600000 + 30 * 60000];
    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(Number.isNaN(bars[0]!["var:__obs_x"] as number)).toBe(true);
    expect(bars[1]!["var:__obs_x"]).toBe(day);
    expect(Number.isNaN(bars[2]!["var:__obs_x"] as number)).toBe(true);
  });
});

// ── time()/time_close(...)의 4번째 인자 bars_back (C727, 배치37 지시 — wild 9개 파일: 4번째
// 위치인자 5건 + 키워드 4건). "그 바 자신의 시각을 bars_back만큼 과거/미래로 이동해 같은
// timeframe/session/timezone으로 재계산"(runtime/context.ts timeAtBarsBack) — 양수/0은
// barTimeAt(C368)과 동일한 실제 과거 바 시각(워밍업이면 na), 음수(미래)는 배치 리플레이가 이미
// 쥔 배열 범위 안이면 실제 미래 바 시각을, 범위 밖이면 timeCloseMs와 동일한 "마지막 두 바 간격
// 외삽"을 쓴다. pine2py 대응 구현이 없어(C299) 오라클 불가, 전부 hand-verified(DIVERGENCES #219).
describe("CodeGen time()/time_close() bars_back argument (C727)", () => {
  it("emits $.timeAtBarsBack(...) as the injected first arg when bars_back is given positionally (4th slot)", () => {
    expect(codegenSource(['t = time("60", "0930-1600", "UTC", 1)'].join("\n"))).toContain(
      'rt.time.resolve($.timeAtBarsBack(1), "60", "0930-1600", "UTC")',
    );
  });

  it("emits $.timeAtBarsBack(...) when bars_back is given as a keyword, padding skipped session/timezone with undefined", () => {
    expect(codegenSource(['t = time(timeframe.period, bars_back = -1)'].join("\n"))).toContain(
      'rt.time.resolve($.timeAtBarsBack((-1)), "D", undefined, undefined)',
    );
  });

  it("falls back to $.barTimeMs (unchanged) when bars_back is not given", () => {
    expect(codegenSource(['t = time("60", "0930-1600")'].join("\n"))).toContain(
      'rt.time.resolve($.barTimeMs, "60", "0930-1600")',
    );
  });

  it("works the same way for time_close()", () => {
    expect(codegenSource(['t = time_close("60", bars_back = 2)'].join("\n"))).toContain(
      'rt.time.resolveClose($.timeAtBarsBack(2), "60", undefined, undefined)',
    );
  });

  it("a bare runtime expression (not just a literal) is passed through to timeAtBarsBack unchanged", () => {
    expect(codegenSource(["n = -bar_index", 't = time("60", bars_back = n)'].join("\n"))).toContain(
      "rt.time.resolve($.timeAtBarsBack(n), \"60\", undefined, undefined)",
    );
  });

  it("C575: a na literal in the bars_back slot lowers to NaN (numeric-typed), unlike timeframe/session/timezone which lower to null (string-typed)", () => {
    const code = codegenSource(['t = time(na, na, na, na)'].join("\n"));
    expect(code).toContain("rt.time.resolve($.timeAtBarsBack(NaN), null, null, null)");
  });

  it("hand-verified E2E: bars_back>=0 matches the real past bar's own time (aligned hourly tf so period-start == raw time, no drift)", () => {
    const source = [
      "var float __obs_look = na",
      '__obs_look := time("60", bars_back = 1)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const day = Date.UTC(2024, 0, 15);
    const time = [0, 1, 2, 3, 4].map((i) => day + i * 3600000);
    const close = [1, 2, 3, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(Number.isNaN(bars[0]!["var:__obs_look"] as number)).toBe(true); // warmup — no bar before idx 0
    expect(bars[1]!["var:__obs_look"]).toBe(time[0]);
    expect(bars[2]!["var:__obs_look"]).toBe(time[1]);
    expect(bars[3]!["var:__obs_look"]).toBe(time[2]);
    expect(bars[4]!["var:__obs_look"]).toBe(time[3]);
  });

  it("hand-verified E2E: negative bars_back (lookahead) reads real future bars already held by the batch-replay array, and extrapolates via the last known interval only past the array end (same principle as timeCloseMs)", () => {
    const source = [
      "var float __obs_ahead = na",
      '__obs_ahead := time("60", bars_back = -2)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const day = Date.UTC(2024, 0, 15);
    const time = [0, 1, 2, 3, 4].map((i) => day + i * 3600000);
    const close = [1, 2, 3, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_ahead"]).toBe(time[2]!); // real future bar, still inside the array
    expect(bars[1]!["var:__obs_ahead"]).toBe(time[3]!);
    expect(bars[2]!["var:__obs_ahead"]).toBe(time[4]!); // last real bar
    expect(bars[3]!["var:__obs_ahead"]).toBe(time[4]! + 3600000); // 1 interval past the array end
    expect(bars[4]!["var:__obs_ahead"]).toBe(time[4]! + 2 * 3600000); // 2 intervals past the array end
  });

  it("hand-verified E2E: bars_back=0 is equivalent to omitting it entirely", () => {
    const withZero = transpile(['var float __obs_x = na', 't = time("60", bars_back = 0)', "__obs_x := t"].join("\n"));
    const omitted = transpile(['var float __obs_x = na', '__obs_x := time("60")'].join("\n"));
    expect(withZero.ok && omitted.ok).toBe(true);
    if (!withZero.ok || !omitted.ok) return;

    const day = Date.UTC(2024, 0, 15);
    const time = [day, day + 3600000];
    const close = [1, 2];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close, time };
    const a = run(withZero.code, withZero.varSlots, withZero.taSlotCount, data, withZero.fnVarSlotCount);
    const b = run(omitted.code, omitted.varSlots, omitted.taSlotCount, data, omitted.fnVarSlotCount);
    expect(a.bars[0]!["var:__obs_x"]).toBe(b.bars[0]!["var:__obs_x"]);
    expect(a.bars[1]!["var:__obs_x"]).toBe(b.bars[1]!["var:__obs_x"]);
  });
});

// ── color(x[, transp]) bare type-cast builtin (C300, wild 3위 클러스터 "알 수 없는 함수 호출"의
// 새 1위 — 69건 중 32건). pine2py에 대응 구현이 전혀 없어 오라클 구조적 불가, time()(C299)과 동일한
// 계열 — colorNew(rt.new, color.new의 rtPath)와 완전히 동일한 시맨틱으로 판정해 재사용, 전부
// hand-verified(DIVERGENCES.md 'TV 미검증(가설)').
describe("CodeGen color() bare type-cast builtin (C300)", () => {
  it("emits rt.new(...) for the 1-arg form", () => {
    const code = codegenSource(["x = color(#FF0000)"].join("\n"));
    expect(code).toContain('rt.new("#FF0000")');
  });

  it("emits rt.new(...) with the transp arg passed through unchanged for the 2-arg form", () => {
    const code = codegenSource(["x = color(#FF0000, 70)"].join("\n"));
    expect(code).toContain('rt.new("#FF0000", 70)');
  });

  it("lowers a na first argument to null (reference-type na, GOAL.md 3-way na convention) instead of the generic NaN path", () => {
    const code = codegenSource(["x = color(na)"].join("\n"));
    expect(code).toContain("rt.new(null)");
    expect(code).not.toContain("rt.new(NaN)");
  });

  it("errors on color() called with 0 or 3+ args", () => {
    for (const call of ["color()", "color(#FF0000, 50, 1)"]) {
      const prog = analyze(parse(`x = ${call}`));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
    }
  });

  it("a user-declared function named 'color' shadows the builtin cast (same precedence as int/float/bool/string)", () => {
    const code = codegenSource(["color(x) =>", "    x", "y = color(5)"].join("\n"));
    expect(code).not.toContain("rt.new(");
  });

  it("does not require top-level statement position — usable inside expressions/conditionals (unlike plot/hline)", () => {
    const prog = analyze(parse(["x = color(#FF0000)", "if close > 0", "    y = color(#0000FF, 50)"].join("\n")));
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified E2E: transpile()+run() — color(na) resolves to null, color(hex) passes through, color(hex, transp) matches color.new's alpha encoding exactly (same rt.new call)", () => {
    const source = [
      "var color __obs_na = na",
      "__obs_na := color(na)",
      "var color __obs_hex = na",
      "__obs_hex := color(#FF0000)",
      "var color __obs_transp = na",
      "__obs_transp := color(#FF0000, 50)",
      "var color __obs_new_equiv = na",
      "__obs_new_equiv := color.new(#FF0000, 50)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    const bar = bars[0]!;

    expect(bar["var:__obs_na"]).toBe(null);
    expect(bar["var:__obs_hex"]).toBe("#FF0000");
    expect(bar["var:__obs_transp"]).toBe("#FF00007F");
    expect(bar["var:__obs_transp"]).toBe(bar["var:__obs_new_equiv"]); // color(x,t) === color.new(x,t)
  });
});

// ── line(x)/label(x)/box(x)/table(x) bare drawing type-cast builtin (C301, wild 잔존 37-클러스터
// "알 수 없는 함수 호출"의 신규 1위 — color(C300) 소멸 후 등장, line 3/label 2/box 1/table 1건).
// pine2py에 대응 구현이 전혀 없어 오라클 구조적 불가, color(C300)/time(C299)과 동일 계열이나 colorCast와
// 달리 실제 값 변환이 없다(GOAL.md "drawing 객체는 no-op" — 핸들 자체가 이미 순수 참조값) — na
// 리터럴만 null로 낮추고 그 외는 항등 통과, 전부 hand-verified(DIVERGENCES.md 'TV 미검증(가설)').
describe("CodeGen line/label/box/table() bare drawing type-cast builtin (C301)", () => {
  it("lowers a na argument to null (reference-type na, GOAL.md 3-way na convention) instead of the generic NaN path", () => {
    for (const fn of ["line", "label", "box", "table"]) {
      const code = codegenSource(`x = ${fn}(na)`);
      expect(code).toBe("var x = null;");
    }
  });

  it("passes a non-na argument through unchanged (identity cast — drawing handles are already pure references, no runtime wrapper needed)", () => {
    for (const fn of ["line", "label", "box", "table"]) {
      const code = codegenSource(`y = 1\nx = ${fn}(y)`);
      expect(code).toContain("var x = y;");
    }
  });

  it("errors on 0 or 2+ args", () => {
    for (const fn of ["line", "label", "box", "table"]) {
      for (const call of [`${fn}()`, `${fn}(na, na)`]) {
        const prog = analyze(parse(`x = ${call}`));
        expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
      }
    }
  });

  it("a user-declared function sharing one of these names shadows the builtin cast (same precedence as int/float/bool/string/color)", () => {
    const code = codegenSource(["line(x) =>", "    x", "y = line(5)"].join("\n"));
    expect(code).not.toBe("var y = null;");
  });

  it("does not require top-level statement position — usable inside expressions/conditionals", () => {
    const prog = analyze(parse(["x = line(na)", "if close > 0", "    y = label(na)"].join("\n")));
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified E2E: transpile()+run() — the wild idiom 'var line X = line(na)' initializes to null, and a later line.new(...) reassignment replaces it with a real DrawingHandle", () => {
    const source = [
      "var line __obs_x = line(na)",
      "if bar_index == 1",
      "    __obs_x := line.new(bar_index, close, bar_index, close)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:__obs_x"]).toBe(null);
    expect(bars[1]!["var:__obs_x"]).not.toBe(null);
    expect((bars[1]!["var:__obs_x"] as unknown as { kind: string }).kind).toBe("line");
    expect(bars[2]!["var:__obs_x"]).toBe(bars[1]!["var:__obs_x"]); // no reset once assigned (var persists)
  });

  // ── bare 캐스트 폼도 isDrawingConstructorCall이 drawingKindHints를 등록하는 생성자 콜로 인정
  // (C633, next_hint(C632) 조사 — wild v5+ 1위 '지원하지 않는 호출' 재조사). 위 E2E 테스트는 명시
  // `var line __obs_x = line(na)` typeHint가 있어 그 typeHint 폴백 경로로 이미 통과했었다 — 아래는
  // wild 지배적 관용구인 typeHint 없는 `var box1 = box(na)` 형태(112개 wild 파일 실측)로, 이 fallback
  // 없이는 isDrawingConstructorCall 자체가 bare 콜을 인식해야만 통과한다. ──

  it("resolves method-call sugar codegen on a bare-cast top-level var with no explicit typeHint (wild 'var box1 = box(na)' idiom, C633)", () => {
    const code = codegenSource(
      ["var box1 = box(na)", "if bar_index == 5", "    box1 := box.new(bar_index, high, bar_index + 1, low)", "    box1.set_right(bar_index + 10)"].join(
        "\n",
      ),
    );
    expect(code).toContain("rt.box.set_right(");
  });

  // ── analyzeAssignment의 drawingKind 폴백(C698, analyzeVarDecl의 typeHint 폴백(C359)과 대칭 —
  // isDrawingConstructorCall만 보고 명시 typeHint 폴백이 없던 비대칭). wild `box up = na`
  // (comma 다중선언 `x1 = 0, ..., box up = na, box dn = na`) 후 `up.get_left()`류. ──
  it("resolves method-call sugar codegen on an explicit-typeHint non-var '=' local initialized to na (wild 'box up = na' idiom, C698)", () => {
    const code = codegenSource(["box up = na", "up.get_left()"].join("\n"));
    expect(code).toContain("rt.box.get_left(");
  });

  it("hand-verified E2E: transpile()+run() — 'var box1 = box(na)' (no explicit typeHint) round-trips through box.new()+set_right() identically to the typeHint'd form (C633)", () => {
    const source = [
      "var box1 = box(na)",
      "if bar_index == 1",
      "    box1 := box.new(bar_index, high, bar_index, high)",
      "if bar_index == 2",
      "    box1.set_right(bar_index + 5)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);

    expect(bars[0]!["var:box1"]).toBe(null);
    expect(bars[1]!["var:box1"]).not.toBe(null);
    expect((bars[1]!["var:box1"] as unknown as { kind: string }).kind).toBe("box");
    expect(bars[2]!["var:box1"]).toBe(bars[1]!["var:box1"]); // same reference, mutated in place (no-op setter)
  });
});

// ── hline/bgcolor/barcolor/plotshape/plotchar/plotarrow/plotcandle/plotbar/alertcondition/alert/
// max_bars_back(C208, ROADMAP corpus 스캔 최다빈도 '알 수 없는 함수 호출' — pine2py wavealgo/
// builtins/plot.py + __init__.py의 no-op/순수 metadata-dict 구현 이식). plot()과 달리 기록 채널
// 자체가 없다(GOAL.md "drawing 객체는 no-op + 발생 카운트 기록"과 동일 원칙을 시각화/알림 함수군에
// 확장) — codegen이 statement 전체를 완전히 드롭한다(directives와 동일한 no-op, C160 선례). ──
describe("CodeGen visualization/alert no-op builtins (C208)", () => {
  it("drops a bare top-level hline()/bgcolor()/plotshape() statement entirely, emitting nothing", () => {
    const code = codegenSource(['hline(70, "OB")', "bgcolor(color.red)", "plotshape(close > open)"].join("\n"));
    expect(code).toBe("");
  });

  it("accepts kwargs without registering them anywhere (values fully discarded, no crash)", () => {
    const code = codegenSource(
      'hline(70, title="OB", color=color.red, linestyle=hline.style_dotted)\nalertcondition(close > open, title="X", message="Y")',
    );
    expect(code).toBe("");
  });

  it("does not disturb codegen of surrounding statements (plot() still records correctly around a no-op call)", () => {
    const code = codegenSource('plot(close, "C")\nbgcolor(color.blue)\nplot(open, "O")');
    expect(code).toBe('$.plots[0].record($.close.get(0));\n$.plots[1].record($.open.get(0));');
  });

  it("resolves shape.*/location.*/alert.freq_*/hline.style_* namespace constants without error", () => {
    const prog = analyze(
      parse(
        [
          "plotshape(close > open, style=shape.triangleup, location=location.belowbar)",
          "hline(50, linestyle=hline.style_dashed)",
          "alert(\"hi\", alert.freq_once_per_bar)",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("errors on an unrecognized shape.*/location.* member (constant folding is a closed set, not a blanket namespace pass-through)", () => {
    const prog = analyze(parse("plotshape(close > open, style=shape.nonexistent)"));
    expect(prog.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("rejects hline/bgcolor/plotshape/alertcondition/max_bars_back called from a local scope (v5 plotting-function restriction, same class as plot() C135)", () => {
    for (const call of [
      'hline(70, "OB")',
      "bgcolor(color.red)",
      "plotshape(close > open)",
      "plotchar(close > open)",
      "plotarrow(close)",
      "plotcandle(open, high, low, close)",
      "plotbar(open, high, low, close)",
      'alertcondition(close > open, "X")',
      "max_bars_back(close, 500)",
    ]) {
      const prog = analyze(parse(`if close > open\n    ${call}`));
      expect(
        prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원")),
        `expected a top-level-only error for: ${call}`,
      ).toBe(true);
    }
  });

  it("allows alert() (unlike its siblings) inside a conditional block — TV's alert() is designed for conditional use", () => {
    const prog = analyze(parse('if close > open\n    alert("crossed", alert.freq_once_per_bar)'));
    expect(prog.errors).toEqual([]);
  });

  it("errors on a wrong argument count for these builtins (e.g. bgcolor() with 0 args, hline() with 0 args)", () => {
    for (const call of ["bgcolor()", "hline()", "plotcandle(open, high)"]) {
      const prog = analyze(parse(call));
      expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치")), `expected an arity error for: ${call}`).toBe(
        true,
      );
    }
  });

  it("a user-declared function sharing one of these names shadows the no-op builtin (same precedence as nz/plot/int)", () => {
    const code = codegenSource(["alert(x) =>", "    x + 1", "y = alert(5)"].join("\n"));
    expect(code).toContain("y = ");
    expect(code).not.toBe("");
  });

  it("hand-verified E2E: no-op calls (including a stateful ta.crossover() embedded directly in an alertcondition() argument) never crash and don't disturb a neighboring plot()'s recorded values", () => {
    const source = [
      "fast = ta.sma(close, 2)",
      "slow = ta.sma(close, 3)",
      "alertcondition(ta.crossover(fast, slow), title=\"Cross\", message=\"up\")",
      "bgcolor(fast > slow ? color.new(color.green, 90) : na)",
      "hline(0, title=\"Zero\", color=color.gray, linestyle=hline.style_dotted)",
      "plotshape(ta.crossover(fast, slow), style=shape.triangleup, location=location.belowbar)",
      "max_bars_back(close, 50)",
      'if close > open\n    alert("up bar", alert.freq_once_per_bar)',
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// NOOP_BUILTIN_ARITY 상한 확장(C290, ROADMAP P4 wild corpus "'X' 호출 인자 개수 불일치" 잔여
// 369-클러스터의 2~6위 서브클러스터 — plotshape 186건/bgcolor 78건/plotchar 15건/barcolor 13건/
// hline 8건/plotcandle 7건, 총 307건). pine2py docs/pinescript_visualization_reference.md 1.2~2.2절
// (TV 공식 시그니처 전체 나열)이 근거 — 값은 전부 discard되는 no-op이라 상한을 TV 실제 파라미터
// 개수까지 올려도 위험 0. plotarrow/plotbar는 wild 미발현이지만 같은 문서·같은 표·같은 위험 0
// 수정이라 함께 상향(next 회귀 방지).
describe("CodeGen no-op builtin arity ceiling widened to full TV signature (C290)", () => {
  it("accepts plotshape()/plotchar() with the full TV 13-parameter signature (was capped at 6/5)", () => {
    const prog = analyze(
      parse(
        [
          'plotshape(close > open, title="T", style=shape.triangleup, location=location.belowbar, color=color.red, offset=0, text="X", textcolor=color.white, editable=true, size=size.small, show_last=10, display=display.all, force_overlay=false)',
          'plotchar(close > open, title="T", char="x", location=location.abovebar, color=color.blue, offset=0, text="Y", textcolor=color.black, editable=false, size=size.normal, show_last=5, display=display.pane, force_overlay=true)',
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("accepts bgcolor()/barcolor() with the full TV 6-parameter signature (was capped at 1)", () => {
    const prog = analyze(
      parse(
        [
          'bgcolor(color.red, offset=0, editable=true, show_last=10, title="BG", force_overlay=false)',
          'barcolor(color.blue, offset=0, editable=false, show_last=5, title="BC", display=display.all)',
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("accepts hline()/plotcandle() with the full TV signature (7/12 parameters, was capped at 5/8)", () => {
    const prog = analyze(
      parse(
        [
          'hline(50, title="H", color=color.gray, linestyle=hline.style_dotted, linewidth=2, editable=true, display=display.all)',
          'plotcandle(open, high, low, close, title="C", color=color.green, wickcolor=color.black, editable=true, show_last=10, bordercolor=color.white, display=display.all, force_overlay=false)',
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("accepts plotarrow()/plotbar() with the full TV signature (11/10 parameters, was capped at 4/6 — wild not yet observed but same doc/table fix)", () => {
    const prog = analyze(
      parse(
        [
          'plotarrow(close - open, title="A", colorup=color.green, colordown=color.red, offset=0, minheight=5, maxheight=50, editable=true, show_last=10, display=display.all, force_overlay=false)',
          'plotbar(open, high, low, close, title="B", color=color.blue, editable=true, show_last=10, display=display.all, force_overlay=false)',
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("still rejects one argument beyond the new ceiling (arity check remains meaningful, not blanket-disabled)", () => {
    const prog = analyze(
      parse(
        'plotshape(close > open, "T", shape.triangleup, location.belowbar, color.red, 0, "X", color.white, true, size.small, 10, display.all, false, "extra")',
      ),
    );
    expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
  });

  it("hand-verified E2E: wild-realistic plotshape()/bgcolor() calls (13/6-arg forms) transpile and run without crashing, values still fully discarded", () => {
    const source = [
      'plotshape(close > open, title="Long", style=shape.triangleup, location=location.belowbar, color=color.green, offset=0, text="L", textcolor=color.white, editable=true, size=size.small, show_last=10, display=display.all, force_overlay=false)',
      'bgcolor(close > open ? color.new(color.green, 90) : na, offset=0, editable=true, show_last=10, title="BG", force_overlay=false)',
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// alertcondition() 상한 재확장 3->4(C656, 배치33 (6) argcount 재조사 잔여 — DIVERGENCES #202
// "초과인자 관용" 가설). wild 660108167ef8.pine의 `alertcondition(cond, "T", "M",
// alert.freq_once_per_bar_close)`(19 콜사이트, alert()의 freq= 상수를 4번째 위치 인자로 얹는
// 관용구)가 TV facade 컴파일러 실측 accept — 값은 discard되는 no-op이라 C290과 동일하게 상한만
// 넓힌다. 5-인자(0ad1bda0c322.pine, 소스 자체가 "ERROR: Too Many" 자기선언 무효 예제)는 여전히
// 거부돼야 한다(무제한 관용이 아님).
describe("CodeGen alertcondition() arity ceiling widened 3->4 (C656, excess-arg tolerance hypothesis)", () => {
  it("accepts alertcondition() with a 4th positional argument (was capped at 3)", () => {
    const prog = analyze(parse('alertcondition(close > open, "BUY", "BUY", alert.freq_once_per_bar_close)'));
    expect(prog.errors).toEqual([]);
  });

  it("still rejects a 5th argument (tolerance is +1, not unbounded)", () => {
    const prog = analyze(parse('alertcondition(close > open, "T", "M", alert.freq_once_per_bar_close, 333)'));
    expect(prog.errors.some((e) => e.includes("'alertcondition' 호출 인자 개수 불일치"))).toBe(true);
  });

  it("hand-verified E2E: the 4-arg wild idiom transpiles and runs as a fully discarded no-op statement", () => {
    const source = [
      'alertcondition(close > open, "BUY Alert", "BUY Alert", alert.freq_once_per_bar_close)',
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.code).not.toContain("alertcondition");

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// plot.style_*(7종)/display.*(5종) 네임스페이스 상수(C254, ROADMAP P4 corpus "네임스페이스 접근은
// 호출식만 지원" 클러스터 잔여 — shape.*/location.*/hline.style_*(C208)와 동일한 컴파일타임 문자열
// 폴딩 패턴). plot()의 style=/display= kwarg 자리와 bare 대입 RHS(corpus 실측: `s = plot.style_line`)
// 둘 다에서 성립해야 한다.
describe("CodeGen plot.style_*/display.* namespace constants (C254)", () => {
  it("resolves plot.style_*/display.* namespace constants without error inside plot() kwargs", () => {
    const prog = analyze(
      parse(
        [
          'plot(volume, title="Volume", style=plot.style_histogram)',
          "plot(close, display=display.none)",
          "plot(open, style=plot.style_line, display=display.all)",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("errors on an unrecognized plot.*/display.* member (constant folding is a closed set, not a blanket namespace pass-through)", () => {
    const prog1 = analyze(parse("plot(close, style=plot.style_nonexistent)"));
    expect(prog1.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
    const prog2 = analyze(parse("plot(close, display=display.nonexistent)"));
    expect(prog2.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("codegens a bare `s = plot.style_line` / `d = display.all` assignment as a folded string literal (corpus exact pattern, d0370747fc2d.pine/35b1cad60c96.pine)", () => {
    expect(codegenSource("s = plot.style_line")).toBe('var s = "line";');
    expect(codegenSource("d = display.all")).toBe('var d = "all";');
  });

  it("all 7 plot.style_* and all 5 display.* members fold to their pine2py IDENTIFIER_MAP string values", () => {
    const styleCases: Array<[string, string]> = [
      ["style_line", "line"],
      ["style_stepline", "stepline"],
      ["style_histogram", "histogram"],
      ["style_cross", "cross"],
      ["style_area", "area"],
      ["style_columns", "columns"],
      ["style_circles", "circles"],
    ];
    for (const [member, value] of styleCases) {
      expect(codegenSource(`x = plot.${member}`)).toBe(`var x = "${value}";`);
    }
    const displayCases: Array<[string, string]> = [
      ["none", "none"],
      ["all", "all"],
      ["data_window", "data_window"],
      ["pane", "pane"],
      ["status_line", "status_line"],
    ];
    for (const [member, value] of displayCases) {
      expect(codegenSource(`x = display.${member}`)).toBe(`var x = "${value}";`);
    }
  });

  it("hand-verified E2E: plot() with style=/display= kwargs still only records the series value (metadata fully discarded)", () => {
    const source = [
      'sma3 = ta.sma(close, 3)',
      'plot(sma3, "SMA", color=color.blue, linewidth=2, style=plot.style_line)',
      'plot(close, display=display.none)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[1]).toEqual({ title: "Plot 1", values: close });
  });
});

// currency.*(15종)/format.*(5종) 네임스페이스 상수(C284, ROADMAP P4 wild 코퍼스 클러스터 1위
// "네임스페이스 접근은 호출식만 지원" 서브클러스터 — currency 428건/format 317건, 합쳐 78%).
// plot.style_*/display.*(C254)와 완전히 동일한 컴파일타임 문자열 폴딩 패턴. strategy()의 currency=,
// indicator()/strategy()/plot()의 format= kwarg 값으로만 쓰이는 회계·표시 전용 no-op 메타데이터.
describe("CodeGen currency.*/format.* namespace constants (C284)", () => {
  it("resolves currency.*/format.* namespace constants without error inside directive/plot kwargs", () => {
    const prog1 = analyze(parse('strategy("t", currency=currency.USD, format=format.price)'));
    expect(prog1.errors).toEqual([]);
    const prog2 = analyze(
      parse(['indicator("t2", format=format.volume)', "plot(close, format=format.mintick)"].join("\n")),
    );
    expect(prog2.errors).toEqual([]);
  });

  it("errors on an unrecognized currency.*/format.* member (constant folding is a closed set, not a blanket namespace pass-through)", () => {
    const prog1 = analyze(parse("x = currency.BOGUS"));
    expect(prog1.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
    const prog2 = analyze(parse("x = format.nonexistent"));
    expect(prog2.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("codegens a bare `c = currency.USD` / `f = format.price` assignment as a folded string literal (corpus exact pattern)", () => {
    expect(codegenSource("c = currency.USD")).toBe('var c = "USD";');
    expect(codegenSource("f = format.price")).toBe('var f = "price";');
  });

  it("currency.NONE folds to an empty string (pine2py IDENTIFIER_MAP \"currency.NONE\": \"''\")", () => {
    expect(codegenSource("c = currency.NONE")).toBe('var c = "";');
  });

  it("all 15 currency.* and all 5 format.* members fold to their string values", () => {
    const currencyCases: Array<[string, string]> = [
      ["USD", "USD"],
      ["EUR", "EUR"],
      ["GBP", "GBP"],
      ["JPY", "JPY"],
      ["AUD", "AUD"],
      ["CAD", "CAD"],
      ["CHF", "CHF"],
      ["CNY", "CNY"],
      ["KRW", "KRW"],
      ["NONE", ""],
      ["USDT", "USDT"],
      ["INR", "INR"],
      ["SEK", "SEK"],
      ["AED", "AED"],
      ["TRY", "TRY"],
    ];
    for (const [member, value] of currencyCases) {
      expect(codegenSource(`x = currency.${member}`)).toBe(`var x = "${value}";`);
    }
    const formatCases: Array<[string, string]> = [
      ["mintick", "mintick"],
      ["percent", "percent"],
      ["volume", "volume"],
      ["inherit", "inherit"],
      ["price", "price"],
    ];
    for (const [member, value] of formatCases) {
      expect(codegenSource(`x = format.${member}`)).toBe(`var x = "${value}";`);
    }
  });

  it("hand-verified E2E: strategy()/plot() with currency=/format= kwargs still transpile and run, metadata fully discarded", () => {
    const source = [
      'strategy("t", currency=currency.USD, format=format.price)',
      'sma3 = ta.sma(close, 3)',
      'plot(sma3, "SMA", format=format.mintick)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[0]!.title).toBe("SMA");
  });
});

// plot.style_linebr/style_stepline_diamond(C285, wild 잔여 233-클러스터 1위, 70+2건) +
// label.style_label_upper_left/upper_right/lower_left/lower_right(4+1+3+7=15건, label obj 전량) +
// display.price_scale(9건) -- 전부 pine2py 자신의 docs/pinescript_visualization_reference.md
// 9.5절 "상수 미매핑" 표가 명시한 실제 TV 상수(pine2py codegen.py IDENTIFIER_MAP 누락분), C254/
// C284와 동일한 컴파일타임 문자열 폴딩. 기존 PLOT_STYLE_CONSTANTS/LABEL_STYLE_CONSTANTS/
// DISPLAY_CONSTANTS 3개 Map에 항목만 추가(codegen 변경 0줄, 새 Map 불필요).
describe("CodeGen plot.style_linebr/label corner styles/display.price_scale namespace constants (C285)", () => {
  it("resolves the 3 new members without error inside plot()/label.new() kwargs", () => {
    const prog1 = analyze(parse('plot(close, style=plot.style_linebr, display=display.price_scale)'));
    expect(prog1.errors).toEqual([]);
    const prog2 = analyze(parse('plot(close, style=plot.style_stepline_diamond)'));
    expect(prog2.errors).toEqual([]);
    const prog3 = analyze(
      parse('label.new(bar_index, close, style=label.style_label_upper_left)'),
    );
    expect(prog3.errors).toEqual([]);
  });

  it("errors on an unrecognized plot.*/label.*/display.* member (constant folding is a closed set)", () => {
    const prog1 = analyze(parse("x = plot.style_bogus"));
    expect(prog1.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
    const prog2 = analyze(parse("x = label.style_bogus"));
    expect(prog2.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("codegens bare assignments as folded string literals (corpus exact pattern)", () => {
    expect(codegenSource("x = plot.style_linebr")).toBe('var x = "linebr";');
    expect(codegenSource("x = plot.style_stepline_diamond")).toBe('var x = "stepline_diamond";');
    expect(codegenSource("x = display.price_scale")).toBe('var x = "price_scale";');
    expect(codegenSource("x = label.style_label_upper_left")).toBe('var x = "label_upper_left";');
  });

  it("all 9 plot.style_*, 6 display.*, and 21 label.style_* members fold to their string values", () => {
    const plotStyleCases: Array<[string, string]> = [
      ["style_line", "line"],
      ["style_linebr", "linebr"],
      ["style_stepline", "stepline"],
      ["style_stepline_diamond", "stepline_diamond"],
      ["style_histogram", "histogram"],
      ["style_cross", "cross"],
      ["style_area", "area"],
      ["style_columns", "columns"],
      ["style_circles", "circles"],
    ];
    for (const [member, value] of plotStyleCases) {
      expect(codegenSource(`x = plot.${member}`)).toBe(`var x = "${value}";`);
    }
    const displayCases: Array<[string, string]> = [
      ["none", "none"],
      ["all", "all"],
      ["data_window", "data_window"],
      ["pane", "pane"],
      ["status_line", "status_line"],
      ["price_scale", "price_scale"],
    ];
    for (const [member, value] of displayCases) {
      expect(codegenSource(`x = display.${member}`)).toBe(`var x = "${value}";`);
    }
    const labelStyleCases: Array<[string, string]> = [
      ["style_none", "none"],
      ["style_label_up", "label_up"],
      ["style_label_down", "label_down"],
      ["style_label_left", "label_left"],
      ["style_label_right", "label_right"],
      ["style_label_upper_left", "label_upper_left"],
      ["style_label_upper_right", "label_upper_right"],
      ["style_label_lower_left", "label_lower_left"],
      ["style_label_lower_right", "label_lower_right"],
      ["style_cross", "cross"],
      ["style_circle", "circle"],
      ["style_diamond", "diamond"],
      ["style_label_center", "label_center"],
      ["style_triangleup", "triangleup"],
      ["style_triangledown", "triangledown"],
      ["style_flag", "flag"],
      ["style_arrowup", "arrowup"],
      ["style_arrowdown", "arrowdown"],
      ["style_square", "square"],
      ["style_text_outline", "text_outline"],
      ["style_xcross", "xcross"],
    ];
    for (const [member, value] of labelStyleCases) {
      expect(codegenSource(`x = label.${member}`)).toBe(`var x = "${value}";`);
    }
  });

  it("hand-verified E2E: display.all - display.price_scale arithmetic combination (real TV syntax, discarded value) transpiles and runs", () => {
    const source = [
      'plot(close, "P1", display=display.all - display.price_scale - display.status_line)',
      'plot(close, "P2", style=plot.style_linebr)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[0]!.title).toBe("P1");
    expect(plots[1]!.title).toBe("P2");
  });
});

// plot.style_areabr/style_steplinebr(C336, wild next_hint(C335) 이월 재조사 -- plot.style_*
// 11종 완전판을 PineTS pinescript-v6/types.json plot 네임스페이스 열거와 대조해 기존
// PLOT_STYLE_CONSTANTS(9종)의 누락 2종을 발견). style_areabr은 pine2py 참조문서 1.1절
// plot.style_* 표(C285가 근거로 쓴 것과 동일 표, line/linebr/stepline/stepline_diamond/area/
// areabr/columns/histogram/circles/cross 10종 나열)에 명시 -- style_linebr/stepline_diamond
// (C285)와 동일한 "문서엔 있으나 codegen.py 포트 누락" 근거. style_steplinebr은 이 문서에도
// 없는 완전 신규 갭이라 PineTS 타입 커버리지 표 교차확인만으로 hand-verified 채택(C335
// format_bold/italic/none과 동일 절차), DIVERGENCES 'TV 미검증(가설)' 등재.
// plot.linestyle_dashed/dotted/solid는 C336 당시 "plot()엔 그런 kwarg가 없음"(pine2py 참조문서 +
// PineTS Plots.ts 구조분해 둘 다 linestyle을 hline() 전용으로만 인식)으로 스킵 확정됐으나, C670에서
// TV 실측 대장(tv_verdict_v2.jsonl) 재조사 결과 wild "네임스페이스 접근은 호출식만 지원" 클러스터
// 최다 서브그룹(32건)이 전량 //@version=6 + TV accept로 확인 -- TV v6에서 plot()에 linestyle= kwarg가
// 신규 추가됐다는 뜻(ROADMAP 배치34 (3) "판정 뒤집힌 축 재점검" 해당 사례). plot.style_dashed는
// 여전히 실제 TV 상수가 아니므로(plot.style_*는 line/linebr/stepline/stepline_diamond/histogram/
// cross/area/areabr/columns/circles/steplinebr 11종뿐, "dashed"는 hline.style_dashed/line.style_dashed
// 전용) 계속 거부.
describe("CodeGen plot.style_areabr/style_steplinebr namespace constants (C336)", () => {
  it("resolves plot.style_areabr/style_steplinebr without error inside plot() kwargs", () => {
    const prog1 = analyze(parse('plot(close, style=plot.style_areabr)'));
    expect(prog1.errors).toEqual([]);
    const prog2 = analyze(parse('plot(close, style=plot.style_steplinebr)'));
    expect(prog2.errors).toEqual([]);
  });

  it("errors on an unrecognized plot.style_* member (constant folding is still a closed set)", () => {
    const prog = analyze(parse("x = plot.style_areadashed"));
    expect(prog.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("codegens bare assignments as folded string literals (corpus exact pattern, 855d41cdea22.pine/075ac566c213.pine)", () => {
    expect(codegenSource("x = plot.style_areabr")).toBe('var x = "areabr";');
    expect(codegenSource("x = plot.style_steplinebr")).toBe('var x = "steplinebr";');
  });

  it("plot.linestyle_dashed/dotted/solid now fold (C670: TV v6 addition, verdict-reversed from C336) but plot.style_dashed remains rejected (never a real plot.style_* member)", () => {
    expect(codegenSource("x = plot.linestyle_dashed")).toBe('var x = "dashed";');
    expect(codegenSource("x = plot.linestyle_dotted")).toBe('var x = "dotted";');
    expect(codegenSource("x = plot.linestyle_solid")).toBe('var x = "solid";');
    const prog3 = analyze(parse("x = plot.style_dashed"));
    expect(prog3.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  // plot() linestyle= kwarg (C670) -- transp=와 동일한 kwarg 전용 discard(PLOT_PARAM_NAMES에는
  // 안 들어가는 위치 슬롯 없는 파라미터, call-expr.ts "linestyle" 전용 분기 참조).
  it("hand-verified E2E: plot() with linestyle=plot.linestyle_dashed (wild exact pattern) transpiles and runs, metadata fully discarded", () => {
    const source = [
      'sma3 = ta.sma(close, 3)',
      'plot(sma3, "SMA", color=color.blue, linestyle=plot.linestyle_dotted, linewidth=2)',
      'plot(close, "Stop", linestyle = plot.linestyle_dashed)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[0]!.title).toBe("SMA");
    expect(plots[1]!.title).toBe("Stop");
    expect(plots[1]!.values).toEqual(close);
  });

  it("hand-verified E2E: plot() with style=plot.style_steplinebr still only records the series value (metadata fully discarded)", () => {
    const source = [
      'sma3 = ta.sma(close, 3)',
      'plot(sma3, "SMA", color=color.blue, style=plot.style_areabr)',
      'plot(close, "Stop", style=plot.style_steplinebr)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[0]!.title).toBe("SMA");
    expect(plots[1]!.title).toBe("Stop");
  });
});

// scale.right/left/none(C286, wild 잔여 138건 서브클러스터 2위, 23건) + session.regular/extended
// (서브클러스터 3위, 17건) -- currency/format(C284)과 완전히 동일한 컴파일타임 문자열 폴딩.
// scale.*은 indicator()/strategy()의 scale= kwarg(Y축 위치, INDICATOR_PARAM_NAMES/
// STRATEGY_PARAM_NAMES에 이미 등록된 no-op discard) 값으로만 쓰이며, pine2py codegen.py엔
// 매핑이 없지만 pine2py 자신의 docs/pinescript_visualization_reference.md 17.3절 "미매핑 상수"
// 표가 TV v5 공식 scale= 값으로 명시(format.price/C284와 동일 급 근거). session.regular/extended는
// pine2py codegen.py IDENTIFIER_MAP L2021-2022의 "session.regular": "'regular'" 등 문자열 값을
// 그대로 옮긴 literal-port -- session.ismarket 등(SESSION_PROPS, 바마다 바뀌는 런타임 bool)과는
// 이름이 겹치지 않는 별도 맵(SESSION_STRING_CONSTANTS)이라 충돌 없음.
describe("CodeGen scale.*/session.regular·extended namespace constants (C286)", () => {
  it("resolves scale.*/session.regular·extended without error inside directive kwargs", () => {
    const prog1 = analyze(parse('indicator("t", scale=scale.right)'));
    expect(prog1.errors).toEqual([]);
    const prog2 = analyze(parse('strategy("t2", scale=scale.none)'));
    expect(prog2.errors).toEqual([]);
    const prog3 = analyze(parse("s = session.regular"));
    expect(prog3.errors).toEqual([]);
  });

  it("errors on an unrecognized scale.*/session.* member (constant folding is a closed set, not a blanket namespace pass-through)", () => {
    const prog1 = analyze(parse("x = scale.bogus"));
    expect(prog1.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
    const prog2 = analyze(parse("x = session.bogus"));
    expect(prog2.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("codegens bare assignments as folded string literals (corpus exact pattern)", () => {
    expect(codegenSource("x = scale.right")).toBe('var x = "right";');
    expect(codegenSource("x = scale.left")).toBe('var x = "left";');
    expect(codegenSource("x = scale.none")).toBe('var x = "none";');
    expect(codegenSource("x = session.regular")).toBe('var x = "regular";');
    expect(codegenSource("x = session.extended")).toBe('var x = "extended";');
  });

  it("session.ismarket (runtime bool, SESSION_PROPS) and session.regular (string constant, SESSION_STRING_CONSTANTS) coexist without name collision", () => {
    expect(codegenSource("x = session.ismarket")).toBe("var x = (true);");
    expect(codegenSource("x = session.regular")).toBe('var x = "regular";');
  });

  it("hand-verified E2E: indicator()/strategy() with scale=/ticker.modify(..., session.regular) still transpile and run, metadata fully discarded", () => {
    const source = [
      'strategy("t", scale=scale.right)',
      'sma3 = ta.sma(close, 3)',
      't1 = ticker.modify(syminfo.tickerid, session.regular)',
      'plot(sma3, "SMA")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[0]!.title).toBe("SMA");
  });
});

// text.align_top/bottom · text.format_bold/italic/none · font.family_default/monospace(C335,
// ROADMAP P4 wild 재실측 신규 후보) -- currency/format(C284)/scale·session(C286)과 동일한
// 컴파일타임 문자열 폴딩. align_top/bottom·family_default/monospace는 pine2py 참조문서/codegen.py에
