// chart.*(C287, wild 잔여 98건 1위 클러스터 25건 — left_visible_bar_time 7/fg_color 7/bg_color 4/
// is_standard 3/left_visible_bar_index 2/right_visible_bar_time 1) — pine2py에 매핑/문서 근거가
// 전혀 없어(C286 교차검증, 오라클 불가) "헤드리스 배치 리플레이 엔진의 chart.* 시맨틱"을 설계로
// 확정한 hand-verified 축(C239 rt.chart.is_standard=true 선례 연장, analyzer.ts CHART_* 맵 주석/
// LIMITATIONS.md C287 참조): 뷰포트 없음 → 전체 바 배열이 항상 "보임"(left_visible_bar_index=0,
// left/right_visible_bar_time=첫/마지막 바 time), 테마 없음 → TV 기본 라이트 테마 고정
// (bg_color=#FFFFFF/fg_color=#000000). bare chart.is_* 7종은 C239 호출형 하드코딩 값 미러.
describe("CodeGen chart.* headless viewport/theme semantics (C287)", () => {
  it("resolves all 6 wild-observed chart.* names without analyzer error", () => {
    const prog = analyze(
      parse(
        [
          "a = chart.left_visible_bar_time",
          "b = chart.right_visible_bar_time",
          "i = chart.left_visible_bar_index",
          "f = chart.fg_color",
          "g = chart.bg_color",
          "s = chart.is_standard",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("errors on an unrecognized chart.* member (closed set, not a blanket namespace pass-through)", () => {
    const prog1 = analyze(parse("x = chart.bogus"));
    expect(prog1.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
    // right_visible_bar_index는 wild 0건이라 의도적으로 미추가(C283 큐레이션 원칙) — 거부 유지가 계약
    const prog2 = analyze(parse("x = chart.right_visible_bar_index"));
    expect(prog2.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("codegens theme colors as folded string literals identical to color.black/color.white", () => {
    expect(codegenSource("x = chart.fg_color")).toBe('var x = "#000000";');
    expect(codegenSource("x = chart.bg_color")).toBe('var x = "#FFFFFF";');
    // COLOR_CONSTANTS와 문자열이 정확히 일치해야 color.black/white와의 비교/합성이 일관된다
    expect(codegenSource("x = color.black")).toBe('var x = "#000000";');
    expect(codegenSource("x = color.white")).toBe('var x = "#FFFFFF";');
  });

  it("codegens viewport values: left index folds to 0, left/right times emit Context getters", () => {
    expect(codegenSource("x = chart.left_visible_bar_index")).toBe("var x = 0;");
    expect(codegenSource("x = chart.left_visible_bar_time")).toBe("var x = ($.firstBarTimeMs);");
    expect(codegenSource("x = chart.right_visible_bar_time")).toBe("var x = ($.lastBarTimeMs);");
    // right_visible_bar_time은 last_bar_time과 의도적으로 동일 getter($.lastBarTimeMs) 재사용
    expect(codegenSource("x = last_bar_time")).toBe("var x = $.lastBarTimeMs;");
  });

  it("codegens bare chart.is_* as boolean literals mirroring the C239 call-form hardcoded values", () => {
    expect(codegenSource("x = chart.is_standard")).toBe("var x = true;");
    expect(codegenSource("x = chart.is_heikinashi")).toBe("var x = false;");
    expect(codegenSource("x = chart.is_renko")).toBe("var x = false;");
    expect(codegenSource("x = chart.is_kagi")).toBe("var x = false;");
    expect(codegenSource("x = chart.is_linebreak")).toBe("var x = false;");
    expect(codegenSource("x = chart.is_pnf")).toBe("var x = false;");
    expect(codegenSource("x = chart.is_range")).toBe("var x = false;");
  });

  it("hand-verified E2E: viewport times reflect the injected time[] channel (first/last bar) on every bar", () => {
    const source = [
      "var float __obs_left_t = na",
      "var float __obs_right_t = na",
      "var float __obs_left_i = na",
      "var float __obs_std = na",
      "__obs_left_t := chart.left_visible_bar_time",
      "__obs_right_t := chart.right_visible_bar_time",
      "__obs_left_i := chart.left_visible_bar_index",
      "__obs_std := chart.is_standard ? 1.0 : 0.0",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const data: OHLCVData = {
      open: [10, 11, 12],
      high: [15, 16, 17],
      low: [5, 6, 7],
      close: [12, 13, 14],
      volume: [1, 1, 1],
      time: [1704078000000, 1704171600000, 1704265200000],
    };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    for (let i = 0; i < 3; i++) {
      expect(bars[i]!["var:__obs_left_t"]).toBe(1704078000000);
      expect(bars[i]!["var:__obs_right_t"]).toBe(1704265200000);
      expect(bars[i]!["var:__obs_left_i"]).toBe(0);
      expect(bars[i]!["var:__obs_std"]).toBe(1);
    }
  });

  it("hand-verified E2E: viewport times fall back to 0 when no time[] channel is loaded (barTimeMs/lastBarTimeMs precedent)", () => {
    const source = ["var float __obs_lt = na", "var float __obs_rt = na", "__obs_lt := chart.left_visible_bar_time", "__obs_rt := chart.right_visible_bar_time"].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { bars } = run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount);
    expect(bars[2]!["var:__obs_lt"]).toBe(0);
    expect(bars[2]!["var:__obs_rt"]).toBe(0);
  });

  it("hand-verified E2E: wild corpus exact pattern `plot(close, color=chart.fg_color)` transpiles and runs", () => {
    const source = ['indicator("t")', 'plot(close, "C", color=chart.fg_color)'].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots[0]!.title).toBe("C");
    expect(Array.from(plots[0]!.values)).toEqual([1, 2, 3]);
  });
});

// fill() 신규 구현 + plot()/hline()의 대입-RHS 지원(C209, PROGRESS next_hint 1순위 — corpus 최다빈도
// '알 수 없는 함수 호출: fill' 패턴, 전부 `p1 = plot(...)` / `h1 = hline(...)` 뒤 `fill(p1, p2,
// color=...)` 형태로 12건 실측). fill()은 plot1/plot2 핸들이 전부 discard 대상인 순수 metadata
// no-op(pine2py wavealgo/builtins/plot.py의 fill(), python 직접 실행으로 확인)이라 NOOP_BUILTIN_TOPLEVEL
// 그룹에 합류. plot()/hline() 자체의 topLevel 판정은 기존 "scope.depth===0 AND ExprStmt"(C135)에서
// "대입 RHS냐 아니냐" 축만 분리해, depth===0이면 '=' 대입 RHS(정확히 bare 콜인 경우만)도 허용한다.
describe("CodeGen fill() + plot()/hline() assignment-RHS (C209)", () => {
  it("codegens `p1 = plot(...)` as a JS local holding the plot slot's record() call", () => {
    const code = codegenSource('p1 = plot(close, "C")');
    expect(code).toBe("var p1 = $.plots[0].record($.close.get(0));");
  });

  it("codegens `h1 = hline(...)` as a JS local holding undefined (hline is a value-less no-op)", () => {
    const code = codegenSource('h1 = hline(70, "OB")');
    expect(code).toBe("var h1 = undefined;");
  });

  it("drops a bare top-level fill(p1, p2, color=...) statement entirely, emitting nothing", () => {
    const code = codegenSource(
      ['p1 = plot(close)', 'p2 = plot(open)', "fill(p1, p2, color=color.new(color.blue, 90))"].join("\n"),
    );
    expect(code).toBe("var p1 = $.plots[0].record($.close.get(0));\nvar p2 = $.plots[1].record($.open.get(0));");
  });

  it("does not disturb plot() slot ordering when assignment-RHS plots/hlines and fill() are interleaved with a bare plot()", () => {
    const code = codegenSource(
      ['p1 = plot(close, "C")', 'h1 = hline(70, "OB")', "fill(p1, h1, color=color.red)", 'plot(open, "O")'].join("\n"),
    );
    expect(code).toBe(
      ["var p1 = $.plots[0].record($.close.get(0));", "var h1 = undefined;", "$.plots[1].record($.open.get(0));"].join(
        "\n",
      ),
    );
  });

  it("rejects `p1 = plot(...)` when not at script top level (still local scope, C135's restriction unchanged for non-depth-0 assignments)", () => {
    const prog = analyze(parse("if close > open\n    p1 = plot(close)\n    x = p1"));
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("rejects `h1 = hline(...)` when not at script top level", () => {
    const prog = analyze(parse("if close > open\n    h1 = hline(70)\n    x = h1"));
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("still rejects plot()/hline() buried in a larger expression on the RHS (not a bare call — plot handles aren't operands)", () => {
    const prog1 = analyze(parse("x = plot(close) + 1"));
    expect(prog1.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
    const prog2 = analyze(parse('x = close > open ? hline(70) : hline(30)'));
    expect(prog2.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("still rejects `var float p1 = plot(close)` (var initial value — unaffected, once-only gate would break plot()'s every-bar semantics)", () => {
    const prog = analyze(parse("var float p1 = plot(close)"));
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("rejects fill() called from a local scope (same v5 plotting-function restriction as its siblings)", () => {
    const prog = analyze(parse("p1 = plot(close)\np2 = plot(open)\nif close > open\n    fill(p1, p2)"));
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("errors on a wrong argument count for fill() (0 args)", () => {
    const prog = analyze(parse("fill()"));
    expect(prog.errors.some((e) => e.includes("호출 인자 개수 불일치"))).toBe(true);
  });

  it("accepts fill()'s color kwarg without tripping the blanket kwargs rejection", () => {
    const prog = analyze(parse("p1 = plot(close)\np2 = plot(open)\nfill(p1, p2, color=color.new(color.blue, 90))"));
    expect(prog.errors).toEqual([]);
  });

  it("a user-declared function named 'fill' shadows the no-op builtin (same precedence as nz/plot/int/alert)", () => {
    const code = codegenSource(["fill(x) =>", "    x + 1", "y = fill(5)"].join("\n"));
    expect(code).toContain("y = ");
    expect(code).not.toBe("");
  });

  it("hand-verified E2E: the BB-fill idiom (p1 = plot(upper); p2 = plot(lower); fill(p1, p2, ...)) transpiles+runs, recording both plots correctly", () => {
    const source = [
      "upper = close + 1",
      "lower = close - 1",
      'p1 = plot(upper, "Upper")',
      'p2 = plot(lower, "Lower")',
      "fill(p1, p2, color=color.new(color.blue, 90))",
      "h1 = hline(70)",
      "h2 = hline(30)",
      "fill(h1, h2)",
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([
      { title: "Upper", values: close.map((c) => c + 1) },
      { title: "Lower", values: close.map((c) => c - 1) },
    ]);
  });
});

// fill(plot(...), plot(...))/fill(hline(...), hline(...)) 중첩 인자(C346, PROGRESS next_hint 1순위
// — wild "'X' 호출은 스크립트 최상위 문장 위치에서만 지원함" 클러스터의 최다빈도 서브패턴, plot
// 43/69건). TV 공식 fill(plot1, plot2, ...) 시그니처는 두 핸들을 `p1 = plot(...)` 사전 대입(C209) 없이
// 인자 자리에서 bare 콜로 직접 받는 것도 정상 문법이다 — analyzer가 args[0]/args[1](및 plot1=/plot2=
// kwarg)이 정확히 bare plot()/hline() 콜일 때만 그 콜 자신을 topLevel=true로 분석. codegen은 fill()
// 문장 전체가 noopStmtCalls라 통째로 스킵되므로, 중첩 plot()의 .record() 부작용만 별도 문장으로
// 방출해야 그 plot 채널이 조용히 안 비게 된다(hline은 애초에 값 채널이 없어 그대로 스킵).
describe("CodeGen fill(plot(...), plot(...)) nested-argument idiom (C346)", () => {
  it("codegens fill(plot(a), plot(b), color=...) as the two nested record() statements, dropping fill() itself", () => {
    const code = codegenSource('fill(plot(close, "C"), plot(open, "O"), color=color.red)');
    expect(code).toBe("$.plots[0].record($.close.get(0));\n$.plots[1].record($.open.get(0));");
  });

  it("codegens fill(hline(...), hline(...)) as nothing at all (hline has no value channel to preserve)", () => {
    const code = codegenSource("fill(hline(70), hline(30))");
    expect(code).toBe("");
  });

  it("codegens fill(plot1=plot(a), plot2=plot(b)) keyword form the same as the positional form", () => {
    const code = codegenSource('fill(plot1=plot(close, "C"), plot2=plot(open, "O"))');
    expect(code).toBe("$.plots[0].record($.close.get(0));\n$.plots[1].record($.open.get(0));");
  });

  it("only re-records the nested plot() argument when the sibling is an already-recorded handle variable", () => {
    const code = codegenSource(['p1 = plot(close, "C")', "fill(p1, plot(open, \"O\"), color=color.blue)"].join("\n"));
    expect(code).toBe(["var p1 = $.plots[0].record($.close.get(0));", "$.plots[1].record($.open.get(0));"].join("\n"));
  });

  it("does not extend the nested-call exception past args[0]/args[1] (color position still rejects a bare plot())", () => {
    const prog = analyze(
      parse(['p1 = plot(close)', 'p2 = plot(open)', "fill(p1, p2, plot(close))"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("does not extend the kwarg exception past plot1=/plot2= (e.g. a hypothetical title=plot(...) still rejects)", () => {
    const prog = analyze(parse('fill(plot(close), plot(open), title=plot(close))'));
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("hand-verified E2E: fill(plot(fast), plot(slow), color) idiom (wild 16ea92ffe7d0.pine pattern) records both plots without an intermediate assignment", () => {
    const source = [
      "fastMA = close + 1",
      "slowMA = close - 1",
      'fill(plot(fastMA, display=display.none), plot(slowMA, display=display.none), color.blue)',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([
      { title: "Plot 0", values: close.map((c) => c + 1) },
      { title: "Plot 1", values: close.map((c) => c - 1) },
    ]);
  });

  it("hand-verified E2E: fill(hline(...), hline(...)) idiom (wild 8f297f246377.pine pattern) transpiles+runs with no plot channels", () => {
    const source = "fill(hline(80), hline(100), color=color.red)";
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([]);
  });
});

// max_bars_back() UDF 본문 무조건 위치 허용(C347, PROGRESS next_hint 1순위 — wild "'X' 호출은
// 스크립트 최상위 문장 위치에서만 지원함" 클러스터의 최다빈도 서브패턴 10건, 전부
// `calcSlope(source, length) =>\n    max_bars_back(source, 5000)`류 UDF 본문 첫 문장 무조건 호출).
// pine2py codegen.py/analyzer.py 전수 확인 결과 max_bars_back은 위치 제약이 전혀 없는 순수 no-op
// FUNC_MAP 항목(런타임도 pass뿐) — plot()류(TV 공식 문서가 명시적으로 local scope 금지)와 달리
// UDF 본문을 막을 근거가 없다. TV 공식 문서로 직접 검증은 못 했으므로(VERIFIED_SEMANTICS.md
// 미기재) "TV 미검증(가설)"로 pine2py 전례만 근거 삼아 완화 — DIVERGENCES.md에 등재.
// scope.kind==="udf-body"+prog.stmtCalls 이중 조건이라 (a) if/for로 한 번 더 감싸인 경우
// (b) 값 위치(VarDecl/Assignment RHS)로 쓰인 경우는 여전히 거부되고, siblings(hline/bgcolor 등)는
// 전혀 영향받지 않는다.
describe("CodeGen max_bars_back() allowed unconditionally at UDF-body top level (C347)", () => {
  it("allows max_bars_back() as the unconditional first statement of a UDF body (was rejected — same class as plot())", () => {
    const prog = analyze(parse(["calcSlope(source, length) =>", "    max_bars_back(source, 5000)", "    source"].join("\n")));
    expect(prog.errors).toEqual([]);
  });

  it("still rejects max_bars_back() nested one level deeper inside an if inside a UDF body (double-conditional, not the observed idiom)", () => {
    const prog = analyze(
      parse(["f(source, length) =>", "    if length > 1", "        max_bars_back(source, 5000)", "    source"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("still rejects max_bars_back() used as a value (VarDecl RHS) inside a UDF body, not just as a bare statement", () => {
    const prog = analyze(
      parse(["f(source, length) =>", "    x = max_bars_back(source, 5000)", "    source"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원"))).toBe(true);
  });

  it("does not extend the relaxation to sibling no-op builtins (hline/bgcolor/plotshape still reject inside a UDF body)", () => {
    for (const call of ['hline(70, "OB")', "bgcolor(color.red)", "plotshape(close > open)"]) {
      const prog = analyze(parse(["f() =>", `    ${call}`, "    close"].join("\n")));
      expect(
        prog.errors.some((e) => e.includes("스크립트 최상위 문장 위치에서만 지원")),
        `expected max_bars_back's relaxation NOT to extend to: ${call}`,
      ).toBe(true);
    }
  });

  it("still allows max_bars_back() at genuine script top level (unchanged from before)", () => {
    const prog = analyze(parse('max_bars_back(close, 500)'));
    expect(prog.errors).toEqual([]);
  });

  it("relaxation also applies to a method body (method's bodyScope is the same udf-body kind as a plain UDF)", () => {
    const prog = analyze(
      parse(
        ["type Point", "    float x = 0.0", "method calc(Point p, float src) =>", "    max_bars_back(src, 100)", "    p.x"].join(
          "\n",
        ),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("codegens the UDF-body max_bars_back() call as nothing (fully dropped, same as top-level no-op)", () => {
    const code = codegenSource(["calcSlope(source, length) =>", "    max_bars_back(source, 5000)", "    source * 2"].join("\n"));
    expect(code).not.toContain("max_bars_back");
    expect(code).toContain("source * 2");
  });

  it("hand-verified E2E: a calcSlope-style UDF with an unconditional max_bars_back() first line transpiles+runs and its real computation is unaffected", () => {
    const source = [
      "calcSlope(source, length) =>",
      "    max_bars_back(source, 5000)",
      "    source * length",
      "y = calcSlope(close, 2)",
      'plot(y, "slope")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 4, 7, 11, 16];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "slope", values: close.map((c) => c * 2) }]);
  });
});

// label/line/box/table/polyline 드로잉 객체(C211, PROGRESS next_hint 1순위 — corpus 93개 파일 실측,
// GOAL.md "drawing 객체(label/line/box/table)는 no-op + 발생 카운트 기록"). 관측 가능한 수치 채널이
// 전혀 없는 순수 핸들/no-op이라(C208의 hline/bgcolor류와 동일 성격) 오라클 golden 케이스는 추가하지
// 않는다 — codegen 단위 테스트 + hand-verified E2E(transpile()+run(), 크래시 없음 + 이웃 plot() 값
// 무변화)로 검증.
describe("CodeGen label/line/box/table/polyline drawing objects (C211)", () => {
  it("codegens `l = label.new(...)` as a JS local holding the rt.label.new(...) call (assignment-RHS, not restricted to top level unlike plot()/hline())", () => {
    const code = codegenSource('l = label.new(bar_index, high, "hi")');
    expect(code).toBe("var l = rt.label.new($.idx, $.high.get(0), \"hi\");");
  });

  it("codegens a bare (unassigned) label.new()/line.new()/box.new()/table.new()/polyline.new() statement as a plain call, not dropped like hline/bgcolor", () => {
    const code = codegenSource('label.new(bar_index, high)\ntable.new(position.top_right, 2, 2)');
    expect(code).toBe('rt.label.new($.idx, $.high.get(0));\nrt.table.new("top_right", 2, 2);');
  });

  // C813(C572 수정): state kwarg(label.new의 x/y/text)는 위치 슬롯으로 낮추고, 표시용 kwarg
  // (color/style/size — GOAL.md "drawing = no-op")는 예전 그대로 전부 버린다. 이전 기대값은
  // `rt.label.new($.idx, $.high.get(0))`로 text= 까지 버리는 결함 동작을 고정하고 있었다.
  it("lowers state kwargs to positional slots but still drops display-only kwargs (values discarded — same principle as hline/fill, no crash)", () => {
    const code = codegenSource(
      'l = label.new(bar_index, high, text="hi", color=color.red, style=label.style_label_down, size=size.normal)',
    );
    expect(code).toBe('var l = rt.label.new($.idx, $.high.get(0), "hi");');
  });

  it("resolves label.style_*/line.style_*/size.*/position.*/extend.*/xloc.*/yloc.*/text.align_*·wrap_* namespace constants without error", () => {
    const prog = analyze(
      parse(
        [
          "l = label.new(bar_index, high, style=label.style_label_down, size=size.huge, textalign=text.align_center)",
          "lin = line.new(bar_index, high, bar_index, low, style=line.style_arrow_both, xloc=xloc.bar_time, extend=extend.both)",
          "b = box.new(bar_index, high, bar_index, low, extend=extend.left, text_halign=text.wrap_auto)",
          "b2 = box.new(bar_index, high, bar_index, low, border_style=line.style_dashed)",
          "t = table.new(position.bottom_center, 1, 1)",
          "lb = label.new(bar_index, high, yloc=yloc.abovebar)",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("errors on an unrecognized member of these namespaces (closed-set constant folding, not a blanket pass-through)", () => {
    const prog = analyze(parse("l = label.new(bar_index, high, style=label.style_nonexistent)"));
    expect(prog.errors.some((e) => e.includes("네임스페이스 접근은 호출식만 지원"))).toBe(true);
  });

  it("errors on an unsupported method name within a drawing namespace", () => {
    const prog = analyze(parse("label.frobnicate(bar_index, high)"));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does NOT restrict these calls to script top level (unlike plot()/hline()/fill() — TV allows conditional label/line/box/table updates)", () => {
    const prog = analyze(
      parse(['l = label.new(bar_index, high)', "if close > open", "    label.set_text(l, \"up\")", "    label.delete(l)"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
  });

  it("accepts kwargs on any of these calls without tripping the blanket kwargs rejection", () => {
    const prog = analyze(
      parse('l = label.new(bar_index, high, text="hi")\nline.new(bar_index, high, bar_index, low, color=color.blue)'),
    );
    expect(prog.errors).toEqual([]);
  });

  it("does not enforce a fixed arity for these methods (pine2py itself validates none — *args/**kwargs — 0-arg and many-arg calls both pass)", () => {
    const prog = analyze(
      parse(
        [
          't = table.new(position.top_right, 1, 1)',
          'table.clear(t)',
          'label.new()',
          'box.new(bar_index, high, bar_index, low, color.red, color.blue, 1, "x", "y")',
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("an unrelated UDT constructor call coexists with drawing calls without dispatch interference", () => {
    const code = codegenSource(['type Point', '    float x', '    float y', 'p = Point.new(1.0, 2.0)', 'l = label.new(bar_index, high)'].join("\n"));
    expect(code).toContain("var l = rt.label.new(");
  });

  it("does not disturb codegen of a surrounding plot() (no-op drawing calls interleaved with plot don't shift its slot or value)", () => {
    const code = codegenSource('plot(close, "C")\nlabel.new(bar_index, high)\nplot(open, "O")');
    expect(code).toBe(
      '$.plots[0].record($.close.get(0));\nrt.label.new($.idx, $.high.get(0));\n$.plots[1].record($.open.get(0));',
    );
  });

  it("hand-verified E2E: label/line/box/table/polyline transpile()+run() without crashing across several bars, and a neighboring plot() still records the correct values", () => {
    const source = [
      'l = label.new(bar_index, high, text="peak", color=color.red, style=label.style_label_down)',
      'label.set_text(l, "updated")',
      'label.set_xy(l, bar_index, low)',
      'if close > open',
      '    label.delete(l)',
      'lin = line.new(bar_index[1], low, bar_index, high, xloc=xloc.bar_index, extend=extend.right)',
      'line.set_color(lin, color.blue)',
      'line.set_width(lin, 2)',
      'b = box.new(bar_index[1], high, bar_index, low, bgcolor=color.new(color.green, 90))',
      'box.set_text(b, "box text")',
      'box.delete(b)',
      't = table.new(position.top_right, 2, 2, bgcolor=color.white)',
      'table.cell(t, 0, 0, "cell text", text_color=color.black)',
      'table.cell_set_bgcolor(t, 0, 0, color.gray)',
      'table.merge_cells(t, 0, 0, 1, 0)',
      'p = polyline.new(na, true, true)',
      'polyline.delete(p)',
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });

  it("hand-verified E2E: each label.new()/line.new()/box.new()/table.new() call returns a distinct handle (the shared per-process id counter increments — a dead channel per GOAL.md, but verified non-crashing and distinguishable)", () => {
    const result = transpile(['a = label.new(bar_index, high)', 'b = label.new(bar_index, low)'].join("\n"));
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const close = [1, 2, 3];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    expect(() =>
      run(result.code, result.varSlots, result.taSlotCount, data, result.fnVarSlotCount, result.historySlotCount, result.taScratchSize),
    ).not.toThrow();
  });
});

// box.set_text_halign/valign/wrap/font_family(C351, wild 코퍼스 "지원하지 않는 호출: 'box.set_text_halign'"
