// ── method-call 스타일 drawing 콜(C232, ROADMAP P3 next_hint 1순위 — corpus 재스캔 lbl.set_text(4)/
// ln.set_color(2)/b.set_lefttop·set_top/t.cell_set_text·set_bgcolor·merge_cells/ln.set_x1·delete/
// lbl.set_xy·get_text류 18개 파일). array/map method-call sugar(C222, resolveContainerExprKind)와
// 완전히 동일한 원칙 — resolveDrawingExprKind(analyzer.ts, containerKindHints과 나란한
// drawingKindHints 체인 조회 + top-level var 전용 prog.drawingVarKinds 폴백)로 receiver의 정적
// kind를 확정한 뒤 그 kind의 DRAWING_METHODS 집합에 method가 있는지만 검사한다. ──
describe("CodeGen method-call style drawing objects (C232)", () => {
  it("routes method-call style lbl.set_text ('=' local receiver) to the dotted 'label.set_text' builtin name", () => {
    const prog = analyze(parse(["lbl = label.new(bar_index, high)", 'lbl.set_text("hi")'].join("\n")));
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as { expr: CallExpr };
    expect(prog.builtinCalls.get(stmt.expr)).toBe("label.set_text");
    const receiver = prog.methodCallReceivers.get(stmt.expr);
    expect(receiver?.kind).toBe("Identifier");
    expect((receiver as { name: string }).name).toBe("lbl");
  });

  it("routes method-call style t.cell (top-level var receiver, drawingVarKinds path) to the dotted 'table.cell' builtin name", () => {
    const prog = analyze(parse(["var t = table.new(position.top_right, 2, 2)", 't.cell(0, 0, "x")'].join("\n")));
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as { expr: CallExpr };
    expect(prog.builtinCalls.get(stmt.expr)).toBe("table.cell");
  });

  it("emits method-call style lbl.set_text identically (receiver prepended) to the namespace form", () => {
    const code = codegenSource(['lbl = label.new(bar_index, high)', 'lbl.set_text("hi")'].join("\n"));
    expect(code).toBe('var lbl = rt.label.new($.idx, $.high.get(0));\nrt.label.set_text(lbl, "hi");');
  });

  it("emits method-call style ln.set_color for a line handle using the plain JS var name (not a $.vars slot)", () => {
    const code = codegenSource(["ln = line.new(bar_index, high, bar_index, low)", "ln.set_color(color.red)"].join("\n"));
    expect(code).toContain('rt.line.set_color(ln, "#FF5252");');
  });

  it("emits method-call style t.cell for a top-level var table receiver through the $.vars slot", () => {
    const code = codegenSource(["var t = table.new(position.top_right, 2, 2)", 't.cell(0, 0, "x")'].join("\n"));
    expect(code).toContain('rt.table.cell($.vars[0], 0, 0, "x");');
  });

  it("emits method-call style p.delete for a polyline handle", () => {
    const code = codegenSource(["p = polyline.new(na, true, true)", "p.delete()"].join("\n"));
    expect(code).toContain("rt.polyline.delete(p);");
  });

  it("kind-checks method sugar: a line-typed receiver cannot call a label-only method (still 'unsupported')", () => {
    const prog = analyze(
      parse(["ln = line.new(bar_index, high, bar_index, low)", 'ln.set_text("x")'].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does not misfire for a plain (non-drawing) local sharing a common variable name", () => {
    const prog = analyze(parse(["lbl = close + 1", 'lbl.set_text("x")'].join("\n")));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does not route method-call style drawing calls for a UDF parameter receiver (no value-flow tracking — still 'unsupported')", () => {
    const prog = analyze(
      parse(["f(a) =>", '    a.set_text("x")', "lbl = label.new(bar_index, high)", "s = f(lbl)"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("coexists with the namespace-call form in the same script without dispatch interference", () => {
    const prog = analyze(
      parse(
        ["lbl = label.new(bar_index, high)", 'label.set_color(lbl, color.blue)', 'lbl.set_text("mixed")'].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified E2E: method-call style drawing sugar across several bars transpiles and runs without crashing, and a neighboring plot() still records the correct values", () => {
    const source = [
      "lbl = label.new(bar_index, high, text=\"peak\")",
      'lbl.set_text("updated")',
      "lbl.set_xy(bar_index, low)",
      "if close > open",
      "    lbl.delete()",
      "ln = line.new(bar_index[1], low, bar_index, high)",
      "ln.set_color(color.blue)",
      "ln.set_width(2)",
      "b = box.new(bar_index[1], high, bar_index, low)",
      'b.set_text("box text")',
      "b.delete()",
      "var t = table.new(position.top_right, 2, 2)",
      't.cell(0, 0, "cell text")',
      "t.merge_cells(0, 0, 1, 0)",
      "p = polyline.new(na, true, true)",
      "p.delete()",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });

  // linefill(C238, ROADMAP P3 next_hint 1순위 -- corpus b7dde3c9d51e.pine `lf = linefill.new(ln1,
  // ln2, color)` + `linefill.delete(lf)`). label/line/box/table/polyline과 완전히 동일한 원칙으로
  // DRAWING_METHODS/isDrawingConstructorCall에 여섯 번째 kind로 편입 -- new도 진짜 핸들이 아니라
  // polyline과 동일하게 drawing_noop(pine2py FUNC_MAP이 linefill.new도 그대로 _DN으로 매핑).
  it("routes namespace-style linefill.new(...) to the dotted 'linefill.new' builtin name (not a constructor -- no handle, unlike label/line/box/table)", () => {
    const prog = analyze(parse(["ln1 = line.new(bar_index, high, bar_index, low)", "lf = linefill.new(ln1, ln1, color.blue)"].join("\n")));
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as { value: CallExpr };
    expect(prog.builtinCalls.get(stmt.value)).toBe("linefill.new");
  });

  it("emits namespace-style linefill.new/delete as rt.linefill.new/delete", () => {
    const code = codegenSource(
      ["ln1 = line.new(bar_index, high, bar_index, low)", "lf = linefill.new(ln1, ln1, color.blue)", "linefill.delete(lf)"].join("\n"),
    );
    expect(code).toContain('var lf = rt.linefill.new(ln1, ln1, "#2196F3");');
    expect(code).toContain("rt.linefill.delete(lf);");
  });

  it("routes method-call style lf.delete() ('=' local receiver, linefill kind) to the dotted 'linefill.delete' builtin name", () => {
    const prog = analyze(
      parse(["ln1 = line.new(bar_index, high, bar_index, low)", "lf = linefill.new(ln1, ln1, color.blue)", "lf.delete()"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[2] as { expr: CallExpr };
    expect(prog.builtinCalls.get(stmt.expr)).toBe("linefill.delete");
    const receiver = prog.methodCallReceivers.get(stmt.expr);
    expect(receiver?.kind).toBe("Identifier");
    expect((receiver as { name: string }).name).toBe("lf");
  });

  it("emits method-call style lf.set_color for a linefill handle using the plain JS var name", () => {
    const code = codegenSource(
      ["ln1 = line.new(bar_index, high, bar_index, low)", "lf = linefill.new(ln1, ln1, color.blue)", "lf.set_color(color.red)"].join("\n"),
    );
    expect(code).toContain('rt.linefill.set_color(lf, "#FF5252");');
  });

  it("kind-checks method sugar: a linefill-typed receiver cannot call a label-only method (still 'unsupported')", () => {
    const prog = analyze(
      parse(
        ["ln1 = line.new(bar_index, high, bar_index, low)", "lf = linefill.new(ln1, ln1, color.blue)", 'lf.set_text("x")'].join("\n"),
      ),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("kind-checks method sugar: a label-typed receiver cannot call a linefill-only method (still 'unsupported')", () => {
    const prog = analyze(
      parse(["lbl = label.new(bar_index, high)", "lbl.get_line1()"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("hand-verified E2E: linefill.new/delete (both namespace and method-call sugar forms) transpile and run without crashing, and a neighboring plot() still records the correct values", () => {
    const source = [
      "ln1 = line.new(bar_index - 1, high, bar_index, high)",
      "ln2 = line.new(bar_index - 1, low, bar_index, low)",
      "lf = linefill.new(ln1, ln2, color.new(color.blue, 80))",
      "linefill.set_color(lf, color.red)",
      "if close > open",
      "    lf.delete()",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });

  // ── linefill.get_line1/get_line2 반환 kind 체이닝 codegen(C648, analyzer.test.ts C648 블록의
  // codegen 짝) — receiverExpr가 그 자체로 또 다른 method-call-sugar CallExpr(rt.linefill.get_line1(lf))
  // 이라 genExpr가 재귀로 알아서 중첩 출력한다(codegen 변경 0줄, analyzer 판별만으로 해소). ──

  it("emits a nested rt call for a linefill.get_line1() chain (lf.get_line1().set_xy1(x, y))", () => {
    const code = codegenSource(
      [
        "ln1 = line.new(bar_index, high, bar_index, low)",
        "ln2 = line.new(bar_index, high, bar_index, low)",
        "lf = linefill.new(ln1, ln2, color.blue)",
        "lf.get_line1().set_xy1(bar_index, high)",
      ].join("\n"),
    );
    expect(code).toContain("rt.line.set_xy1(rt.linefill.get_line1(lf), $.idx, $.high.get(0));");
  });

  it("hand-verified E2E: linefill.get_line1().set_xy1(...) chain transpiles and runs without crashing, and a neighboring plot() still records the correct values (C648)", () => {
    const source = [
      "ln1 = line.new(bar_index - 1, high, bar_index, high)",
      "ln2 = line.new(bar_index - 1, low, bar_index, low)",
      "lf = linefill.new(ln1, ln2, color.new(color.blue, 80))",
      "lf.get_line1().set_xy1(bar_index, close)",
      "lf.get_line2().set_color(color.red)",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// ── method-call-sugar 형태 drawing 콜의 kwargs(`dash.cell(0, 0, "x", text_color=..., text_size=...)`,
// C384, wild gate(220) 잔여 최다 서브클러스터 — dash.cell 5/tb.cell 4/tbl.cell 2/dashboard.cell·
// info_table.cell·tableInfo.cell 등, 순증 상한 16건). 리터럴 네임스페이스 폼(`table.cell(t, ...)`,
// isDrawingCall)은 이미 blanket kwargs 거부 예외였지만 sugar 폼(`t.cell(...)`, receiver가 변수)은
// array/map sugar(C222)와 같은 축으로 여전히 거부되고 있었다 — text_color/text_size류가 순수
// 표시값(GOAL.md drawing no-op 불변식)이라는 근거로 이 축만 반대로 뒤집는다(array/map sugar kwargs는
// wild 실사용 0건이라 계속 거부 유지, 아래 회귀 테스트로 확인). ──
describe("CodeGen method-call style drawing objects: kwargs on the sugar receiver (C384)", () => {
  it("accepts text_color=/text_size= kwargs on t.cell(...) (top-level var receiver, drawingVarKinds path)", () => {
    const prog = analyze(
      parse(
        ["var t = table.new(position.top_right, 2, 2)", 't.cell(0, 0, "x", text_color=color.gray, text_size=size.small)'].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as { expr: CallExpr };
    expect(prog.builtinCalls.get(stmt.expr)).toBe("table.cell");
  });

  it("accepts a kwarg on lbl.set_xy(...) (label kind, '=' local receiver)", () => {
    const prog = analyze(
      parse(["lbl = label.new(bar_index, high)", "lbl.set_xy(bar_index, high, force_overlay=true)"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
  });

  it("accepts a kwarg on b.set_lefttop(...) (box kind, '=' local receiver)", () => {
    const prog = analyze(
      parse(["b = box.new(bar_index, high, bar_index, low)", "b.set_lefttop(50, 200, force_overlay=true)"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
  });

  it("does not validate kwarg names on the sugar receiver (permissive, matching the literal namespace form's blanket exemption)", () => {
    const prog = analyze(
      parse(["var t = table.new(position.top_right, 2, 2)", 't.cell(0, 0, "x", not_a_real_param=1)'].join("\n")),
    );
    expect(prog.errors).toEqual([]);
  });

  it("still rejects a kwarg on array.push(...) sugar (a.push(id=..., value=...)) -- C222 scope unchanged, only drawing sugar was reversed", () => {
    const prog = analyze(parse(["a = array.new_float(1, 0.0)", "a.push(value=5.0)"].join("\n")));
    expect(prog.errors.some((e) => e.includes("키워드 인자('value=...')는"))).toBe(true);
  });

  it("still rejects a kwarg on map.put(...) sugar (m.put(key=..., value=...)) -- C222 scope unchanged, only drawing sugar was reversed", () => {
    const prog = analyze(parse(["m = map.new<int, float>()", "m.put(key=1, value=2.0)"].join("\n")));
    expect(prog.errors.some((e) => e.includes("키워드 인자('key=...')는"))).toBe(true);
  });

  it("emits t.cell(...) with the kwargs fully discarded (only positional args reach the generated call, same as the literal namespace form)", () => {
    const code = codegenSource(
      ["var t = table.new(position.top_right, 2, 2)", 't.cell(0, 0, "x", text_color=color.gray, text_size=size.small)'].join("\n"),
    );
    expect(code).toContain('rt.table.cell($.vars[0], 0, 0, "x");');
  });

  it("emits lbl.set_xy(...) with a trailing kwarg discarded, receiver still prepended", () => {
    const code = codegenSource(
      ["lbl = label.new(bar_index, high)", "lbl.set_xy(bar_index, high, force_overlay=true)"].join("\n"),
    );
    expect(code).toContain("rt.label.set_xy(lbl, $.idx, $.high.get(0));");
  });

  it("coexists with the literal namespace form's own kwargs in the same script (t2 uses table.cell(t2, ...) with text_color=, t uses sugar t.cell(...) with text_color=)", () => {
    const prog = analyze(
      parse(
        [
          "var t = table.new(position.top_right, 2, 2)",
          "var t2 = table.new(position.bottom_right, 2, 2)",
          't.cell(0, 0, "sugar", text_color=color.gray)',
          'table.cell(t2, 0, 0, "literal", text_color=color.black)',
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
  });

  it("hand-verified E2E: t.cell(...) with text_color=/text_size= kwargs transpiles and runs without crashing, and a neighboring plot() still records the correct values", () => {
    const source = [
      "var t = table.new(position.top_right, 2, 2)",
      't.cell(0, 0, "cell text", text_color=color.black, text_size=size.small)',
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// ── method-call 스타일 drawing 콜의 수신자가 func-local var(UDF 본문 안 var, C358, ROADMAP P4
// next_hint(C357) 1순위 — wild `drawBox(condition, y1, y2, color) =>` UDF 안 `var box drawBox = na`
// 뒤 `drawBox.set_extend(extend.none)`류 2파일 + `var l=label.new(...)` 뒤 `l.set_xy(...)`류 1파일).
// top-level var(C232, prog.drawingVarKinds)와 달리 func-local var는 지금까지 어떤 참조형 판별
// 맵에도 등록되지 않아 전부 "지원하지 않는 호출"로 거부됐다 — FuncInfo.localVarDrawingKinds
// 신설(paramUdtTypes/C124와 나란한 구조)로 해소. codegen 변경 0줄(기존
// isDrawingMethodSugarCall/resolveDrawingExprKind 디스패치(C232) 그대로 재사용, resolveDrawingExprKind가
// scope.func 경유로 이 맵을 추가 조회할 뿐). ──
describe("CodeGen method-call style drawing objects: func-local var receiver (C358)", () => {
  it("emits rt.box.set_extend for a func-local 'var box drawBox = na' receiver (exact wild idiom)", () => {
    const code = codegenSource(
      ["f() =>", "    var box drawBox = na", "    drawBox.set_extend(extend.none)", "f()"].join("\n"),
    );
    expect(code).toContain('rt.box.set_extend($.fnVars[__slotBase + 0], "none");');
  });

  it("emits rt.label.set_xy for a func-local bare-constructor 'var l = label.new(...)' receiver (no explicit typeHint)", () => {
    const code = codegenSource(
      ["ma_label(x, y) =>", "    var l = label.new(x, y)", "    l.set_xy(x, y)", "    l", "m = ma_label(bar_index, close)"].join(
        "\n",
      ),
    );
    expect(code).toContain("rt.label.set_xy($.fnVars[__slotBase + 0], x, y);");
  });

  it("kind-checks method sugar: a func-local box receiver cannot call a label-only method (still 'unsupported')", () => {
    const prog = analyze(parse(["f() =>", "    var box b = na", "    b.get_text()", "f()"].join("\n")));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("keeps drawing kind independent per function (same local var name 'b', box in one function, line in another)", () => {
    const code = codegenSource(
      [
        "f1() =>",
        "    var box b = na",
        "    b.set_extend(extend.none)",
        "f2() =>",
        "    var line b = na",
        "    b.set_extend(extend.none)",
        "f1()",
        "f2()",
      ].join("\n"),
    );
    expect(code).toContain('rt.box.set_extend($.fnVars[__slotBase + 0], "none");');
    expect(code).toContain('rt.line.set_extend($.fnVars[__slotBase + 0], "none");');
  });

  it("does not route method-call sugar for a func-local var with a non-drawing typeHint (no regression)", () => {
    const prog = analyze(
      parse(["f() =>", "    var float acc = na", "    acc.set_extend(extend.none)", "f()"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does not misfire when a top-level var of the same name pattern coexists (different scopes, no cross-talk)", () => {
    const code = codegenSource(
      ["var float topB = 1.0", "f() =>", "    var box b = na", "    b.set_extend(extend.none)", "f()", "y = topB"].join(
        "\n",
      ),
    );
    expect(code).toContain('rt.box.set_extend($.fnVars[__slotBase + 0], "none");');
  });

  it("hand-verified E2E: transpile()+run() — the wild idiom (func-local var box, na-init, conditional constructor reassignment, chained method-call sugar) runs across several bars without crashing", () => {
    const source = [
      "drawBox(condition, y1, y2) =>",
      "    var box b = na",
      "    if condition",
      "        b.set_extend(extend.none)",
      "        b := box.new(bar_index, y1, bar_index, y2)",
      "    b",
      "sb = drawBox(ta.change(close) > 0, high, low)",
      "topv = box.get_top(sb)",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// ── method-call 스타일 drawing 콜의 수신자가 UDF/method 매개변수 자신이고 명시 typeHint로 drawing
// kind를 선언한 경우(C476, ROADMAP P4 next_hint(C475) 1순위 — wild
// `cell(table t_able, int column, int row, string data, color textColor) =>
//   t_able.cell(column, row, data, text_color = textColor)`류 4파일). C358(func-local var)/
// C359(top-level var na 초기값)와 나란한 세 번째 축이지만 이건 var가 아니라 매개변수 자체다 —
// resolveDrawingExprKind에 scope.func.paramTypeHints 폴백(drawingKindFromTypeHint, C415
// containerKindFromTypeHint와 동일한 qualifier-strip 원칙) 한 줄 추가로 해소. 매개변수는 슬롯이
// 아니라 함수 인자로 그대로 codegen되므로(파라미터 자체가 이미 로컬 바인딩) $.fnVars 경유가
// 필요 없다는 점만 C358과 다르다. ──
describe("CodeGen method-call style drawing objects: UDF parameter receiver with explicit typeHint (C476)", () => {
  it("emits rt.table.cell for a 'table t_able' parameter receiver (exact wild idiom, kwargs discarded per C211)", () => {
    const code = codegenSource(
      [
        "cell(table t_able, int column, int row, string data, color textColor) =>",
        "    t_able.cell(column, row, data, text_color = textColor)",
        "tb = table.new(position.top_right, 2, 2)",
        'cell(tb, 0, 0, "x", color.white)',
      ].join("\n"),
    );
    expect(code).toContain("rt.table.cell(t_able, column, row, data);");
  });

  it("kind-checks method sugar on a parameter receiver: a box parameter cannot call a label-only method (still 'unsupported')", () => {
    const prog = analyze(parse(["f(box b) =>", "    b.get_text()", "f(box.new(0, 0, 1, 1))"].join("\n")));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does not route method-call sugar for a non-drawing parameter typeHint (no regression)", () => {
    const prog = analyze(parse(["f(float acc) =>", "    acc.set_extend(extend.none)", "f(1.0)"].join("\n")));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does not route method-call sugar for an untyped parameter (no typeHint, matches the pre-existing C124 limitation)", () => {
    const prog = analyze(parse(["f(b) =>", "    b.set_extend(extend.none)", "f(box.new(0, 0, 1, 1))"].join("\n")));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("hand-verified E2E: transpile()+run() — a table-typed UDF parameter with method-call sugar (incl. discarded kwargs) runs across several bars without crashing", () => {
    const source = [
      "cell(table t_able, int column, int row, string data, color textColor) =>",
      "    t_able.cell(column, row, data, text_color = textColor)",
      "tb = table.new(position.top_right, 2, 2)",
      'cell(tb, 0, 0, "x", color.white)',
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// ── method-call 스타일 drawing 콜의 수신자가 무힌트 UDF 매개변수이고, 그 drawing kind가 top-level
// UDT var의 필드(DotAccess) 콜사이트 인자로만 역추론되는 경우(C496, ROADMAP P4 next_hint(C495) —
// wild `color_lines(line_m, line_t, line_l, color, label) => ... line_m.get_y1() ...` 뒤
// `color_lines(c.line_mid1, c.line_top1, c.line_low1, color_up, label_up)`류, c는 top-level
// `var c = channel.new(...)`, line_mid1은 channel의 line 필드). C476(매개변수 explicit typeHint)과
// 나란한 축이지만 이건 매개변수 자신에 typeHint가 전혀 없다 — analyzer.ts
// prepassInferParamUdtTypesFromCallSites가 C492 paramContainerKinds의 인프라를 재사용해 DotAccess
// 인자도 스캔하도록 확장(FuncInfo.paramDrawingKinds 신설), resolveDrawingExprKind에 조회 분기 1개
// 추가로 소비. codegen 변경 0줄(기존 method-call sugar 디스패치(C232) 그대로 재사용). ──
describe("CodeGen method-call style drawing objects: untyped UDF parameter inferred from a top-level UDT-field call-site argument (C496)", () => {
  it("emits rt.line.get_y1 for an untyped 'line_m' parameter receiver (exact wild color_lines idiom)", () => {
    const code = codegenSource(
      [
        "type channel",
        "    line line_mid1 = na",
        "var c = channel.new()",
        "color_lines(line_m) =>",
        "    line_m.get_y1()",
        "color_lines(c.line_mid1)",
      ].join("\n"),
    );
    expect(code).toContain("rt.line.get_y1(line_m)");
  });

  it("kind-checks the inferred receiver: passing a box field where 'get_y1' (line-only) is called stays 'unsupported'", () => {
    const prog = analyze(
      parse(
        [
          "type zone",
          "    box zoneBox = na",
          "var z = zone.new()",
          "f(h) =>",
          "    h.get_y1()",
          "f(z.zoneBox)",
        ].join("\n"),
      ),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("hand-verified E2E: transpile()+run() — an untyped UDF parameter whose drawing kind is inferred from a top-level UDT-field call-site argument runs across several bars without crashing", () => {
    const source = [
      "type channel",
      "    line line_mid1 = na",
      "    line line_top1 = na",
      "var c = channel.new()",
      "color_lines(line_m, line_t) =>",
      "    if line_m.get_y1() <= line_m.get_y2()",
      "        line_m.set_color(color.green)",
      "        line_t.set_color(color.green)",
      "color_lines(c.line_mid1, c.line_top1)",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok, result.ok ? "" : result.errors.join("; ")).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// ── method-call 스타일 drawing 콜의 수신자가 top-level var이고 초기값이 생성자 콜이 아니라 na인 경우
// (C359, ROADMAP P4 next_hint(C358) 1순위 — wild `var line bull_line = na` 뒤 조건부
// `bull_line := line.new(...)`, 이어서 `bull_line.set_x2(...)`류. C358이 func-local var 분기에
// 붙인 typeHint 폴백과 완전히 대칭되는 top-level var(analyzeVarDecl의 `else` 분기, prog.drawingVarKinds)
// 쪽 갭 — 지금까지 top-level 분기는 `isDrawingConstructorCall(stmt.value)`만 보고 na 초기값은
// 전혀 인정하지 않았다. analyzer.ts에 `?? (typeHint가 DRAWING_ALL_NAMESPACES 멤버면 그 kind)` 폴백
// 한 줄 추가로 해소, codegen 변경 0줄(기존 isDrawingMethodSugarCall/resolveDrawingExprKind 디스패치
// (C232) 그대로 재사용). ──
describe("CodeGen method-call style drawing objects: top-level var with na initializer + explicit typeHint (C359)", () => {
  it("registers prog.drawingVarKinds from an explicit typeHint 'var line bull_line = na' at top level (the exact wild idiom)", () => {
    const prog = analyze(parse(["var line bull_line = na", "bull_line.set_x2(bar_index)"].join("\n")));
    expect(prog.errors).toEqual([]);
    expect(prog.drawingVarKinds.get("bull_line")).toBe("line");
  });

  it.each(["box", "line", "label", "table", "polyline", "linefill"])(
    "registers prog.drawingVarKinds for each of the 6 drawing namespaces via explicit typeHint ('var %s h = na')",
    (ns) => {
      const prog = analyze(parse([`var ${ns} h = na`, `h.delete()`].join("\n")));
      expect(prog.errors).toEqual([]);
      expect(prog.drawingVarKinds.get("h")).toBe(ns);
    },
  );

  it("emits rt.line.set_x2 for a top-level 'var line bull_line = na' receiver reassigned inside a conditional (exact wild idiom)", () => {
    const code = codegenSource(
      [
        "var line bull_line = na",
        "if bar_index == 5",
        "    bull_line := line.new(bar_index, close, bar_index, close)",
        "bull_line.set_x2(bar_index)",
      ].join("\n"),
    );
    expect(code).toContain("rt.line.set_x2($.vars[0], $.idx);");
  });

  it("kind-checks method sugar: a top-level na-initialized box receiver cannot call a label-only method (still 'unsupported')", () => {
    const prog = analyze(parse(["var box b = na", "b.get_text()"].join("\n")));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("does not register drawingVarKinds for a non-drawing top-level var typeHint (regression guard)", () => {
    const prog = analyze(parse(["var float acc = na", "s = acc"].join("\n")));
    expect(prog.errors).toEqual([]);
    expect(prog.drawingVarKinds.has("acc")).toBe(false);
  });

  it("does not misfire when a func-local drawing var coexists in a different scope (no cross-talk)", () => {
    const code = codegenSource(
      [
        "var line topLine = na",
        "f() =>",
        "    var box b = na",
        "    b.set_extend(extend.none)",
        "f()",
        "topLine.set_x2(bar_index)",
      ].join("\n"),
    );
    expect(code).toContain('rt.box.set_extend($.fnVars[__slotBase + 0], "none");');
    expect(code).toContain("rt.line.set_x2($.vars[0], $.idx);");
  });

  it("hand-verified E2E: transpile()+run() — the wild idiom (top-level var line, na-init, conditional constructor reassignment, chained method-call sugar) runs across several bars without crashing", () => {
    const source = [
      "var line bull_line = na",
      "if bar_index == 2",
      "    bull_line := line.new(bar_index, close, bar_index, close)",
      "if not na(bull_line)",
      "    bull_line.set_x2(bar_index)",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

// ── array<label/line/box/table/linefill> 원소를 순회하는 for-in 루프 변수의 drawing method-call
// sugar(C352, wild "지원하지 않는 호출" 클러스터 세분화 — `heatmap = array.new_box()` 뒤 `for b in
// heatmap \n b.delete()`류 4~7파일). C232(단일 핸들 '=' 로컬/top-level var)/C323(UDT 필드 단일
// 핸들)과 동일한 resolveDrawingExprKind 디스패치를 그대로 재사용하되, 이번엔 receiver kind가
// analyzeForInStmt가 이터러블의 원소 kind(arrayElemDrawingKind, arrayUdtElemType(C341)의 drawing
// 버전)를 조회해 루프 변수에 직접 다는 새 경로다 — codegen 변경 0줄(기존 method-call sugar 디스패치
// 그대로 재사용). ──
describe("CodeGen for-in loop over typed drawing arrays (C352)", () => {
  it("routes a for-in loop var over array.new_box() to the dotted 'box.delete' builtin name (top-level var elem-kind tracking)", () => {
    const prog = analyze(
      parse(["var boxes = array.new_box()", "for b in boxes", "    b.delete()"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
    const forIn = prog.script.body[1] as { body: { expr: CallExpr }[] };
    const stmt = forIn.body[0]!;
    expect(prog.builtinCalls.get(stmt.expr)).toBe("box.delete");
    const receiver = prog.methodCallReceivers.get(stmt.expr);
    expect(receiver?.kind).toBe("Identifier");
    expect((receiver as { name: string }).name).toBe("b");
  });

  it("routes a for-in loop var over a UDT field typed array<line> to the dotted 'line.set_color' builtin name", () => {
    const prog = analyze(
      parse(
        [
          "type Chart",
          "    array<line> lns",
          "c = Chart.new(array.new_line())",
          "for ln in c.lns",
          "    ln.set_color(color.red)",
        ].join("\n"),
      ),
    );
    expect(prog.errors).toEqual([]);
    const forIn = prog.script.body[2] as { body: { expr: CallExpr }[] };
    const stmt = forIn.body[0]!;
    expect(prog.builtinCalls.get(stmt.expr)).toBe("line.set_color");
  });

  it("emits rt.box.delete(b) for a for-in loop var over array.new_box()", () => {
    const code = codegenSource(["var boxes = array.new_box()", "for b in boxes", "    b.delete()"].join("\n"));
    expect(code).toContain("rt.box.delete(b);");
  });

  it("emits rt.line.set_width for a for-in loop var over array.new_line()", () => {
    const code = codegenSource(
      ["var lns = array.new_line()", "for ln in lns", "    ln.set_width(2)"].join("\n"),
    );
    expect(code).toContain("rt.line.set_width(ln, 2);");
  });

  it("kind-checks the for-in elem hint: a box-typed loop var cannot call a label-only method (still 'unsupported')", () => {
    const prog = analyze(
      parse(["var boxes = array.new_box()", "for b in boxes", "    b.get_text()"].join("\n")),
    );
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("tags the loop var for a '=' local iterable too (C620 — arrayElemDrawingKindHints scope-chain hint closes this gap, same fix as the C353 drawing-handle-extraction axis)", () => {
    const prog = analyze(
      parse(["boxes = array.new_box()", "for b in boxes", "    b.delete()"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
    const forIn = prog.script.body[1] as { body: { expr: CallExpr }[] };
    const stmt = forIn.body[0]!;
    expect(prog.builtinCalls.get(stmt.expr)).toBe("box.delete");
  });

  it("routes the loop var for the generic array.new<box>() form too (C357 — arrayDrawingConstructorElemKind now also recognizes 'new_generic'+genericElemType, closing the gap C352 left open)", () => {
    const prog = analyze(
      parse(["var boxes = array.new<box>()", "for b in boxes", "    b.delete()"].join("\n")),
    );
    expect(prog.errors).toEqual([]);
    const forIn = prog.script.body[1] as { body: { expr: CallExpr }[] };
    const stmt = forIn.body[0]!;
    expect(prog.builtinCalls.get(stmt.expr)).toBe("box.delete");
  });

  it("leaves a plain (non-drawing) array for-in loop unaffected (no regression)", () => {
    const code = codegenSource(
      ["var nums = array.new_float()", "array.push(nums, 1.0)", "sum = 0.0", "for n in nums", "    sum := sum + n"].join("\n"),
    );
    expect(code).toContain("sum = (sum + n);");
  });

  it("hand-verified E2E: for-in loop var drawing method-call sugar (box.delete) transpiles and runs across several bars without crashing, and a neighboring plot() still records the correct values", () => {
    const source = [
      "var boxes = array.new_box()",
      "if bar_index == 0",
      "    array.push(boxes, box.new(bar_index, high, bar_index + 1, low))",
      "    array.push(boxes, box.new(bar_index, high, bar_index + 1, low))",
      "for b in boxes",
      "    b.delete()",
      "array.clear(boxes)",
      'plot(close, "C")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4, 5];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([{ title: "C", values: close }]);
  });
});

