// ── chart.is_standard/is_heikinashi/is_renko/is_kagi/is_linebreak/is_pnf/is_range(C239, ROADMAP
// P3 next_hint 1순위, corpus 실측: is_heikinashi 1건(4b0f69bc8a0c.pine), is_standard 1건
// (f57998ea9f64.pine)). pine2py에 대응 구현이 전혀 없어(codegen.py/wavealgo 전수 grep 0건) 오라클
// 검증 불가 — 이 엔진은 메인 차트에 heikin-ashi/renko/kagi/line break/point&figure/range 합성 바
// 변환을 적용하지 않으므로 is_standard=true/나머지 6종=false 하드코딩이 TV 정의상 유일한 합리적
// 값(hand-verified, LIMITATIONS.md 참조).
describe("CodeGen chart.is_* (C239)", () => {
  it("emits chart.is_standard/is_heikinashi/is_renko/is_kagi/is_linebreak/is_pnf/is_range as rt.chart.is_* nested calls", () => {
    const code = codegenSource(
      [
        "a = chart.is_standard()",
        "b = chart.is_heikinashi()",
        "c = chart.is_renko()",
        "d = chart.is_kagi()",
        "e = chart.is_linebreak()",
        "f = chart.is_pnf()",
        "g = chart.is_range()",
      ].join("\n"),
    );
    expect(code).toBe(
      [
        "var a = rt.chart.is_standard();",
        "var b = rt.chart.is_heikinashi();",
        "var c = rt.chart.is_renko();",
        "var d = rt.chart.is_kagi();",
        "var e = rt.chart.is_linebreak();",
        "var f = rt.chart.is_pnf();",
        "var g = rt.chart.is_range();",
      ].join("\n"),
    );
  });

  it("errors when chart.is_standard is called with an argument (TV signature is 0-arity)", () => {
    const prog = analyze(parse("x = chart.is_standard(1)"));
    expect(prog.errors.some((e) => e.includes("'chart.is_standard' 호출 인자 개수 불일치"))).toBe(true);
  });

  it("still rejects an unrecognized chart.* method as an unsupported call (not silently accepted by the namespace match)", () => {
    const prog = analyze(parse("x = chart.frobnicate()"));
    expect(prog.errors.some((e) => e.includes("지원하지 않는 호출"))).toBe(true);
  });

  it("hand-verified E2E: chart.is_heikinashi()/is_standard() transpile()+run() across several bars, reproducing the exact corpus pattern (`chart.is_heikinashi() ? 1.0 : 0.0`), and always resolve to the hardcoded standard-chart values", () => {
    const source = [
      "var float ha = 0.0",
      "ha := chart.is_heikinashi() ? 1.0 : 0.0",
      "var float std = 0.0",
      "std := chart.is_standard() ? 1.0 : 0.0",
      'plot(ha, "HA")',
      'plot(std, "STD")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([
      { title: "HA", values: [0, 0, 0, 0, 0] },
      { title: "STD", values: [1, 1, 1, 1, 1] },
    ]);
  });
});

// ── syminfo.ticker(symbol)(신규, C430 — next_hint(C429): wild 2건 6c0c2a7c04ab.pine/
// a22502c376a6.pine, `ticker1 = syminfo.ticker(sym1)`). bare `syminfo.ticker` 프로퍼티 접근
