// ── request.security_lower_tf(신규, C310 — wild 3위 서브클러스터 14건). pine2py
// wavealgo/__init__.py L103-113가 symbol/timeframe/context를 전부 무시하고(codegen.py
// CONTEXT_FUNCS가 context=ctx를 얹어도 이 함수 시그니처엔 그 파라미터가 없어 **kwargs로 흡수돼
// 버려짐) expression을 현재 바 값으로 평가해 원소 1개짜리 배열로 감싸는 순수 스텁이다 —
// request.security(실제 HTF 캐시 집계)와 근본적으로 다른 함수라 narrow 표현식 제약 없이 임의
// 표현식을 그대로 genExpr 허용(oracle/cases/request_security_lower_tf.pine 참조).
describe("CodeGen request.security_lower_tf (C310)", () => {
  it("emits request.security_lower_tf as an rt.request.security_lower_tf nested call, with the expression argument genExpr'd like any other call arg", () => {
    const code = codegenSource('a = request.security_lower_tf(syminfo.tickerid, "1", close)');
    expect(code).toBe('var a = rt.request.security_lower_tf("", "1", $.close.get(0));');
  });

  it("emits an arbitrary (non-literal) timeframe expression unchanged, since the pine2py stub ignores it entirely", () => {
    const code = codegenSource(
      ["f() =>\n    \"1\"", 'a = request.security_lower_tf(syminfo.tickerid, f(), close > open)'].join("\n"),
    );
    expect(code).toContain("rt.request.security_lower_tf(");
  });

  it("errors when request.security_lower_tf is called with more than 7 arguments", () => {
    const prog = analyze(parse('x = request.security_lower_tf("a", "b", close, true, "c", true, 5, "extra")'));
    expect(prog.errors.some((e) => e.includes("'request.security_lower_tf' 호출 인자 개수 불일치"))).toBe(true);
  });

  it("hand-verified E2E: request.security_lower_tf(...) transpile()+run() across several bars, wrapping the per-bar close value as a single-element array (array.get(sub, 0) recovers it, array.size(sub) is always 1)", () => {
    const source = [
      "var float val = na",
      "var float sz = na",
      "sub = request.security_lower_tf(syminfo.tickerid, \"1\", close)",
      "val := array.get(sub, 0)",
      "sz := array.size(sub)",
      'plot(val, "VAL")',
      'plot(sz, "SZ")',
    ].join("\n");
    const result = transpile(source);
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const close = [1, 2, 3, 2, 4];
    const data: OHLCVData = { open: close, high: close, low: close, close, volume: close };
    const { plots } = run(
      result.code,
      result.varSlots,
      result.taSlotCount,
      data,
      result.fnVarSlotCount,
      result.historySlotCount,
      result.taScratchSize,
      {},
      result.plotTitles,
    );
    expect(plots).toEqual([
      { title: "VAL", values: close },
      { title: "SZ", values: [1, 1, 1, 1, 1] },
    ]);
  });

  it("emits a trailing kwarg (ignore_invalid_timeframe=) folded into its pine2py-signature slot 5, undefined padding the skipped currency slot (C381, wild 실사용 폼)", () => {
    const code = codegenSource('a = request.security_lower_tf(syminfo.tickerid, "1", close, ignore_invalid_timeframe = true)');
    expect(code).toBe('var a = rt.request.security_lower_tf("", "1", $.close.get(0), undefined, undefined, true);');
  });

  it("emits a trailing kwarg (calc_bars_count=) folded into its pine2py-signature slot 6 (C381)", () => {
    const code = codegenSource('a = request.security_lower_tf(syminfo.tickerid, "1", close, calc_bars_count = 5)');
    expect(code).toBe('var a = rt.request.security_lower_tf("", "1", $.close.get(0), undefined, undefined, undefined, 5);');
  });

  it("emits an all-keyword call (symbol=/timeframe=/expression=/ignore_invalid_symbol=/ignore_invalid_timeframe=/calc_bars_count=) with every value folded to its pine2py-signature positional slot (C381, 395803745923.pine 패턴)", () => {
    const code = codegenSource(
      'a = request.security_lower_tf(symbol = syminfo.tickerid, timeframe = "1", expression = close, ignore_invalid_symbol = true, ignore_invalid_timeframe = true, calc_bars_count = 3)',
    );
    expect(code).toBe('var a = rt.request.security_lower_tf("", "1", $.close.get(0), true, undefined, true, 3);');
  });
});

// ── request.seed(신규, C321 — corpus 실측 8건, 전량 `request.seed(source, symbol, expression)`
// 3-인자 위치 패턴). pine2py에 대응 구현이 전혀 없음(dividends/splits/financial/quandl과 달리
// 스텁조차 없음) — 커뮤니티 유지보수 "seed" 데이터셋(예: SEED_CRYPTO_SANTIMENT)을 조회하는 함수라
// 우리 엔진의 단일 OHLCV 배치 리플레이 데이터 모델에 그 데이터 소스가 없다. financial/economic과
// 동일한 "외부 데이터 부재 → NaN 고정" 원칙을 hand-verified로 신규 적용(TV 미검증 가설,
// DIVERGENCES 등재). expression 인자는 값을 버리지만 genExpr는 그대로 수행(security_lower_tf와
// 동일 관례 — 부작용 보존).
